INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u3-C28','sci',3,1,'u3',5,'사는 곳에 알맞은 생김새 — 사막 식물은 물을 저장하고 지키는 모습 — 사는 곳이 다르면 그곳에 알맞게 생김새도 다름',ARRAY['[4과03-02] 사는 곳에 따른 식물의 생김새와 생활 방식을 관찰하여 사는 곳과 관련지어 설명할 수 있다(성취기준 초안 · W7 확인)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u3-C29','sci',3,1,'u3',6,'식물의 특징을 본뜬 물건 — 사람들은 식물의 특징을 본떠 생활에 도움이 되는 물건을 만듦',ARRAY['[4과03-03] 식물의 특징을 본떠 생활에서 활용하는 예를 찾아 발표할 수 있다(성취기준 초안 · W7 확인)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u3-C30','sci',3,1,'u3',6,'도꼬마리 → 찍찍이 — 열매의 갈고리 모양 가시가 털·옷에 잘 붙는 점을 본떠 붙였다 떼는 찍찍이를 만듦',ARRAY['[4과03-03] 식물의 특징을 본떠 생활에서 활용하는 예를 찾아 발표할 수 있다(성취기준 초안 · W7 확인)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
