INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u3-C33','sci',3,1,'u3',6,'민들레 씨앗 → 낙하산 — 가벼운 솜털로 바람을 타고 천천히 내려오는 점을 본뜸',ARRAY['[4과03-03] 식물의 특징을 본떠 생활에서 활용하는 예를 찾아 발표할 수 있다(성취기준 초안 · W7 확인)']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u3-C34','sci',3,1,'u3',6,'쓰임과 본뜬 부분 — 날거나 천천히 내려오기 = 씨앗(단풍나무·민들레) · 붙이거나 물 막기 = 열매·잎(도꼬마리·연잎)',ARRAY['[4과03-03] 식물의 특징을 본떠 생활에서 활용하는 예를 찾아 발표할 수 있다(성취기준 초안 · W7 확인)']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-1-u3-C35','sci',3,1,'u3',6,'본뜨는 차례와 까닭 — 자세히 관찰 → 도움이 되는 특징 찾기 → 본떠 만들기 · 식물의 특징에는 환경에 알맞게 살아온 지혜가 담김',ARRAY['[4과03-03] 식물의 특징을 본떠 생활에서 활용하는 예를 찾아 발표할 수 있다(성취기준 초안 · W7 확인)']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
