INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X06','sci',3,'u3',ARRAY['SC3-1-u3-C6']::text[],'잎몸·잎맥·잎자루의 이름과 하는 일을 뒤바꾼다','넓은 부분 · 줄 · 자루') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X07','sci',3,'u3',ARRAY['SC3-1-u3-C7']::text[],'잎의 가장자리·갈라짐·길쭉함·잎맥 모양을 잘못 보고 무리에 넣는다','보이는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X08','sci',3,'u3',ARRAY['SC3-1-u3-C8']::text[],'분류하는 차례를 뒤바꾸거나 관찰 없이 바로 나눈다','관찰 → 공통점·차이점 → 기준') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X09','sci',3,'u3',ARRAY['SC3-1-u3-C9','SC3-1-u3-C10']::text[],'예쁜가·마음에 드는가처럼 사람마다 다른 기준을 알맞다고 여긴다','누가 해도 같은 기준') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X10','sci',3,'u3',ARRAY['SC3-1-u3-C11']::text[],'기준을 바꾸어도 무리가 같거나 한 잎은 늘 같은 무리에 든다고 여긴다','기준이 바뀌면 무리도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X11','sci',3,'u3',ARRAY['SC3-1-u3-C12']::text[],'들과 산에는 풀만, 또는 나무만 산다고 여긴다','풀도 나무도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X12','sci',3,'u3',ARRAY['SC3-1-u3-C13','SC3-1-u3-C14']::text[],'풀과 나무의 줄기 특징(가늘고 연함/굵고 단단함)을 뒤바꾼다','풀 = 가늘고 연함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X13','sci',3,'u3',ARRAY['SC3-1-u3-C16']::text[],'키만 보고 풀과 나무를 나누거나 나무는 모두 키가 아주 크다고 여긴다','줄기를 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X14','sci',3,'u3',ARRAY['SC3-1-u3-C15']::text[],'풀과 나무에 공통점이 없거나 풀에는 뿌리가 없다고 여긴다','뿌리·줄기·잎') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X15','sci',3,'u3',ARRAY['SC3-1-u3-C17']::text[],'물에는 식물이 살지 않거나 물에 사는 식물은 모두 떠서 산다고 여긴다','사는 모습이 여러 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X16','sci',3,'u3',ARRAY['SC3-1-u3-C18','SC3-1-u3-C20','SC3-1-u3-C21']::text[],'떠서 사는·잠겨 사는·잎이 뜨는·물가에 사는 식물을 뒤바꾼다','떠서 · 잠겨서 · 물가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X17','sci',3,'u3',ARRAY['SC3-1-u3-C19']::text[],'부레옥잠이 무거운 뿌리나 단단한 줄기 때문에 뜬다고 여긴다','잎자루 속 공기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X18','sci',3,'u3',ARRAY['SC3-1-u3-C20']::text[],'검정말의 가늘고 부드러운 줄기·잎이 물의 흐름과 관계없다고 여긴다','물살에 휘어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X19','sci',3,'u3',ARRAY['SC3-1-u3-C22']::text[],'물에 사는 식물은 뿌리가 없거나 생김새가 사는 곳과 관계없다고 여긴다','물에 사는 식물도 뿌리가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X20','sci',3,'u3',ARRAY['SC3-1-u3-C23']::text[],'사막에는 식물이 살 수 없다고 여기거나 사막 식물과 물 식물을 뒤바꾼다','사막에도 살아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X21','sci',3,'u3',ARRAY['SC3-1-u3-C24','SC3-1-u3-C25']::text[],'물을 저장하는 곳(줄기/잎)을 뒤바꾼다','선인장 = 줄기 · 알로에 = 잎') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X22','sci',3,'u3',ARRAY['SC3-1-u3-C26']::text[],'선인장 가시가 물을 지키는 일과 관계없다고 여긴다','가시 = 변한 잎') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X23','sci',3,'u3',ARRAY['SC3-1-u3-C27']::text[],'선인장은 뿌리가 없거나 뿌리가 물을 얻는 일과 관계없다고 여긴다','넓게 뻗는 뿌리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X24','sci',3,'u3',ARRAY['SC3-1-u3-C28']::text[],'사막 식물도 잎이 넓고 얇다고 여기거나 사는 곳과 생김새가 관계없다고 여긴다','사는 곳에 알맞게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X25','sci',3,'u3',ARRAY['SC3-1-u3-C29','SC3-1-u3-C35']::text[],'식물은 생활과 관계없거나 본뜬 물건이 쓸모없다고 여긴다','생활에 도움') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X26','sci',3,'u3',ARRAY['SC3-1-u3-C30','SC3-1-u3-C31','SC3-1-u3-C32','SC3-1-u3-C33']::text[],'식물의 특징과 본떠 만든 물건의 짝을 뒤바꾼다','갈고리 · 날개 · 연잎 · 솜털') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X27','sci',3,'u3',ARRAY['SC3-1-u3-C34']::text[],'쓰임(날기/붙이기·물 막기)이나 본뜬 부분(씨앗/잎·열매)을 뒤바꾼다','씨앗은 날기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X28','sci',3,'u3',ARRAY['SC3-1-u3-C35']::text[],'관찰 없이 아무 식물이나 모양만 똑같이 따라 만들면 된다고 여긴다','좋은 특징을 찾아') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X29','sci',3,'u3',ARRAY['SC3-1-u3-C36','SC3-1-u3-C40']::text[],'만들고 싶은 것과 맞지 않는 식물 특징을 고른다','쓰임에 맞는 특징') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X30','sci',3,'u3',ARRAY['SC3-1-u3-C37']::text[],'발명 3단계의 차례를 뒤바꾸거나 관찰 없이 만들기·색칠부터 한다','관찰 → 좋은 점 → 본뜨기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X31','sci',3,'u3',ARRAY['SC3-1-u3-C38']::text[],'스펀지·비닐·돌처럼 식물이 아닌 것을 본뜰 특징으로 여긴다','식물에서 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X32','sci',3,'u3',ARRAY['SC3-1-u3-C39']::text[],'친구의 발명 아이디어를 놀리거나 듣지 않는다','좋은 점을 말해 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X33','sci',3,'u3',ARRAY['SC3-1-u3-C41','SC3-1-u3-C44']::text[],'벌레를 잡는 식물은 없거나, 벌레를 잡으면 식물이 아니라 동물이라고 여긴다','벌레를 잡는 식물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X34','sci',3,'u3',ARRAY['SC3-1-u3-C42']::text[],'벌레잡이 식물이 모두 같은 방법으로 잡는다고 여기거나 식물과 방법의 짝을 뒤바꾼다','식물마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X35','sci',3,'u3',ARRAY['SC3-1-u3-C43']::text[],'벌레를 잡는 까닭을 햇빛이 싫어서·싸우려고처럼 잘못 안다','부족한 양분') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X36','sci',3,'u3',ARRAY['SC3-1-u3-C44']::text[],'벌레잡이 식물은 벌레만 먹고 살아 햇빛이 필요 없다고 여긴다','햇빛도 받아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u3-X37','sci',3,'u3',ARRAY['SC3-1-u3-C45']::text[],'신기하다고 잎을 자꾸 건드리거나 떼어 내도 된다고 여긴다','가만히 관찰') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#1','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C1',1,'mc','auto','식물은 어디에서 살까요?',ARRAY['SC3-1-u3-X01']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C1","difficulty":1,"kind":"mc","stem":"식물은 어디에서 살까요?","options":[{"t":"화단, 길가, 들판, 산, 물가처럼 우리 주변 곳곳에서 살아요","correct":true},{"t":"산속 깊은 곳에서만 살아요","mis":"SC3-1-u3-X01"},{"t":"사람이 사는 곳에는 살지 않아요","mis":"SC3-1-u3-X01"},{"t":"식물원 안에서만 살아요","mis":"SC3-1-u3-X01"}],"explanation":["주변을 둘러봐요.","길가에도 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#2','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C3',1,'mc','auto','노란 꽃이 피고, 꽃이 지면 하얀 솜털 씨앗이 바람에 날아가는 식물은 무엇인가요?',ARRAY['SC3-1-u3-X03']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C3","difficulty":1,"kind":"mc","stem":"노란 꽃이 피고, 꽃이 지면 하얀 솜털 씨앗이 바람에 날아가는 식물은 무엇인가요?","options":[{"t":"민들레","correct":true},{"t":"소나무","mis":"SC3-1-u3-X03"},{"t":"토끼풀","mis":"SC3-1-u3-X03"},{"t":"튤립","mis":"SC3-1-u3-X03"}],"explanation":["노란 꽃이에요.","솜털 씨앗이 날아가요.","민들레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#3','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C2',1,'ox','auto','식물마다 잎, 꽃, 줄기의 생김새가 서로 달라요.',ARRAY['SC3-1-u3-X02']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C2","difficulty":1,"kind":"ox","stem":"식물마다 잎, 꽃, 줄기의 생김새가 서로 달라요.","answer":"O","reason_options":[{"t":"소나무는 잎이 바늘 모양이고 토끼풀은 잎이 세 장처럼 보이듯 식물마다 생김새가 다르기 때문에","correct":true},{"t":"모든 식물은 잎과 꽃의 모양이 똑같기 때문에","mis":"SC3-1-u3-X02"}],"mis":"SC3-1-u3-X02","explanation":["소나무와 토끼풀을 떠올려요.","잎이 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#4','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C5',1,'sa','auto','식물의 특징을 알려면 식물을 자세히 「○○」해요. ○○에 알맞은 두 글자 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u3-C5","difficulty":1,"kind":"sa","stem":"식물의 특징을 알려면 식물을 자세히 「○○」해요. ○○에 알맞은 두 글자 말을 쓰세요.","answer":["관찰"],"explanation":["눈으로 자세히 살펴요.","두 글자예요.","「관찰」이에요."],"mis":"SC3-1-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#5','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C3',2,'match','auto','식물 관찰 수첩을 보고 식물과 생김새를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u3-C3","difficulty":2,"kind":"match","stem":"식물 관찰 수첩을 보고 식물과 생김새를 알맞게 이으세요.","pairs":[{"l":"소나무","r":"잎이 바늘 모양"},{"l":"토끼풀","r":"잎이 세 장처럼 보임"},{"l":"강아지풀","r":"꽃이 복슬복슬함"}],"mis":"SC3-1-u3-X03","explanation":["수첩을 한 줄씩 읽어요.","생김새를 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["민들레 — 길가에 자람 · 노란 꽃 · 솜털 씨앗이 바람에 날아감","소나무 — 산 · 키가 큰 나무 · 잎이 바늘 모양 · 겨울에도 푸름","토끼풀 — 풀밭 · 키가 작음 · 잎이 세 장처럼 보임","강아지풀 — 들이나 길가 · 잎이 가늘고 긺 · 꽃이 복슬복슬함","튤립 — 학교 화단 · 사람이 심어 기름"],"title":"식물 관찰 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#6','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C4',2,'mc','auto','식물 관찰 수첩에서 사람이 화단에 심어 기르는 식물은 무엇인가요?',ARRAY['SC3-1-u3-X04']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C4","difficulty":2,"kind":"mc","stem":"식물 관찰 수첩에서 사람이 화단에 심어 기르는 식물은 무엇인가요?","options":[{"t":"튤립","correct":true},{"t":"민들레","mis":"SC3-1-u3-X04"},{"t":"강아지풀","mis":"SC3-1-u3-X04"},{"t":"토끼풀","mis":"SC3-1-u3-X04"}],"explanation":["「심어 기름」을 찾아요.","학교 화단이에요.","튤립이에요."],"asset":{"type":"passage","lines":["민들레 — 길가에 자람 · 노란 꽃 · 솜털 씨앗이 바람에 날아감","소나무 — 산 · 키가 큰 나무 · 잎이 바늘 모양 · 겨울에도 푸름","토끼풀 — 풀밭 · 키가 작음 · 잎이 세 장처럼 보임","강아지풀 — 들이나 길가 · 잎이 가늘고 긺 · 꽃이 복슬복슬함","튤립 — 학교 화단 · 사람이 심어 기름"],"title":"식물 관찰 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#7','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C1',2,'ox','auto','식물 관찰 수첩을 보면 민들레와 강아지풀은 길가에서도 자라요.',ARRAY['SC3-1-u3-X01']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C1","difficulty":2,"kind":"ox","stem":"식물 관찰 수첩을 보면 민들레와 강아지풀은 길가에서도 자라요.","answer":"O","reason_options":[{"t":"수첩에 민들레와 강아지풀이 길가에서 자란다고 적혀 있기 때문에","correct":true},{"t":"식물은 산속에서만 자라기 때문에","mis":"SC3-1-u3-X01"}],"mis":"SC3-1-u3-X01","explanation":["사는 곳을 읽어요.","길가가 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["민들레 — 길가에 자람 · 노란 꽃 · 솜털 씨앗이 바람에 날아감","소나무 — 산 · 키가 큰 나무 · 잎이 바늘 모양 · 겨울에도 푸름","토끼풀 — 풀밭 · 키가 작음 · 잎이 세 장처럼 보임","강아지풀 — 들이나 길가 · 잎이 가늘고 긺 · 꽃이 복슬복슬함","튤립 — 학교 화단 · 사람이 심어 기름"],"title":"식물 관찰 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#8','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C2',2,'mc','auto','식물 관찰 수첩에서 키가 큰 식물은 무엇인가요?',ARRAY['SC3-1-u3-X03']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C2","difficulty":2,"kind":"mc","stem":"식물 관찰 수첩에서 키가 큰 식물은 무엇인가요?","options":[{"t":"소나무","correct":true},{"t":"토끼풀","mis":"SC3-1-u3-X03"},{"t":"강아지풀","mis":"SC3-1-u3-X03"},{"t":"민들레","mis":"SC3-1-u3-X03"}],"explanation":["「키가 큰」을 찾아요.","산에 있어요.","소나무예요."],"asset":{"type":"passage","lines":["민들레 — 길가에 자람 · 노란 꽃 · 솜털 씨앗이 바람에 날아감","소나무 — 산 · 키가 큰 나무 · 잎이 바늘 모양 · 겨울에도 푸름","토끼풀 — 풀밭 · 키가 작음 · 잎이 세 장처럼 보임","강아지풀 — 들이나 길가 · 잎이 가늘고 긺 · 꽃이 복슬복슬함","튤립 — 학교 화단 · 사람이 심어 기름"],"title":"식물 관찰 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#9','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C5',2,'mc','auto','길가에서 처음 보는 식물을 만났어요. 특징을 알아보는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X05']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C5","difficulty":2,"kind":"mc","stem":"길가에서 처음 보는 식물을 만났어요. 특징을 알아보는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"꺾지 않고 잎, 꽃, 줄기를 자세히 살펴봐요","correct":true},{"t":"바로 꺾어서 집에 가져가요","mis":"SC3-1-u3-X05"},{"t":"눈을 감고 지나가요","mis":"SC3-1-u3-X05"},{"t":"빨리 뛰어가며 한 번만 봐요","mis":"SC3-1-u3-X05"}],"explanation":["식물도 살아 있어요.","자세히 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_basic#10','sci',3,1,'u3','L01','g3_1_sci_u3_L01_basic','lesson_basic','SC3-1-u3-C3',3,'mc','auto','소나무의 특징을 바르게 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X03']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C3","difficulty":3,"kind":"mc","stem":"소나무의 특징을 바르게 모은 것은 무엇인가요?","options":[{"t":"잎이 바늘 모양이고 겨울에도 잎이 푸르러요","correct":true},{"t":"노란 꽃이 피고 솜털 씨앗이 날아가요","mis":"SC3-1-u3-X03"},{"t":"잎이 세 장처럼 보이고 키가 작아요","mis":"SC3-1-u3-X03"},{"t":"꽃이 복슬복슬하고 잎이 가늘고 길어요","mis":"SC3-1-u3-X03"}],"explanation":["소나무 줄을 읽어요.","바늘 모양 잎이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["민들레 — 길가에 자람 · 노란 꽃 · 솜털 씨앗이 바람에 날아감","소나무 — 산 · 키가 큰 나무 · 잎이 바늘 모양 · 겨울에도 푸름","토끼풀 — 풀밭 · 키가 작음 · 잎이 세 장처럼 보임","강아지풀 — 들이나 길가 · 잎이 가늘고 긺 · 꽃이 복슬복슬함","튤립 — 학교 화단 · 사람이 심어 기름"],"title":"식물 관찰 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#1','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C2',2,'blank','auto','「식물마다 잎, 꽃, 줄기의 (      ) 달라요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u3-X02','SC3-1-u3-X04']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C2","difficulty":2,"kind":"blank","stem":"「식물마다 잎, 꽃, 줄기의 (      ) 달라요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"생김새가","correct":true},{"t":"이름표가","mis":"SC3-1-u3-X02"},{"t":"주인이","mis":"SC3-1-u3-X04"},{"t":"나이가","mis":"SC3-1-u3-X02"}],"explanation":["잎·꽃·줄기의 모양이에요.","생긴 모습이에요.","「생김새가」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#2','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C1',2,'mc','auto','우리 주변에서 식물을 볼 수 있는 곳끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X01']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C1","difficulty":2,"kind":"mc","stem":"우리 주변에서 식물을 볼 수 있는 곳끼리 모은 것은 무엇인가요?","options":[{"t":"화단, 들판, 산, 물가","correct":true},{"t":"산속 깊은 곳에서만","mis":"SC3-1-u3-X01"},{"t":"식물원 안에서만","mis":"SC3-1-u3-X01"},{"t":"꽃집 안에서만","mis":"SC3-1-u3-X01"}],"explanation":["주변 곳곳이에요.","여러 곳이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#3','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C3',3,'error','auto','친구들이 식물 관찰 수첩을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u3-X03']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C3","difficulty":3,"kind":"error","stem":"친구들이 식물 관찰 수첩을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「토끼풀은 잎이 바늘 모양이야.」","correct":true,"mis_target":"SC3-1-u3-X03"},{"t":"친구 가 — 「민들레는 노란 꽃이 피어.」","mis":"SC3-1-u3-X03"},{"t":"친구 다 — 「강아지풀은 잎이 가늘고 길어.」","mis":"SC3-1-u3-X03"}],"explanation":["토끼풀 줄을 읽어요.","잎이 세 장처럼 보여요.","친구 나예요."],"asset":{"type":"passage","lines":["민들레 — 길가에 자람 · 노란 꽃 · 솜털 씨앗이 바람에 날아감","소나무 — 산 · 키가 큰 나무 · 잎이 바늘 모양 · 겨울에도 푸름","토끼풀 — 풀밭 · 키가 작음 · 잎이 세 장처럼 보임","강아지풀 — 들이나 길가 · 잎이 가늘고 긺 · 꽃이 복슬복슬함","튤립 — 학교 화단 · 사람이 심어 기름"],"title":"식물 관찰 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#4','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C4',3,'mc','auto','봉숭아와 민들레를 견주었을 때 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X01','SC3-1-u3-X04','SC3-1-u3-X02']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C4","difficulty":3,"kind":"mc","stem":"봉숭아와 민들레를 견주었을 때 알맞은 것은 무엇인가요?","options":[{"t":"봉숭아는 화단에 심어 기르고, 민들레는 길가에서 절로 자라기도 해요","correct":true},{"t":"둘 다 산속에서만 자라요","mis":"SC3-1-u3-X01"},{"t":"봉숭아는 길가에서 절로만, 민들레는 화단에서만 자라요","mis":"SC3-1-u3-X04"},{"t":"둘 다 생김새가 똑같아요","mis":"SC3-1-u3-X02"}],"explanation":["화단에 핀 봉숭아를 떠올려요.","민들레는 길가예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#5','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C3',3,'mc','auto','수수께끼예요. 「잎이 세 장처럼 보이고, 키가 작고, 풀밭에 많이 자라요.」 어떤 식물일까요?',ARRAY['SC3-1-u3-X03']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C3","difficulty":3,"kind":"mc","stem":"수수께끼예요. 「잎이 세 장처럼 보이고, 키가 작고, 풀밭에 많이 자라요.」 어떤 식물일까요?","options":[{"t":"토끼풀","correct":true},{"t":"소나무","mis":"SC3-1-u3-X03"},{"t":"민들레","mis":"SC3-1-u3-X03"},{"t":"튤립","mis":"SC3-1-u3-X03"}],"explanation":["잎이 세 장이에요.","풀밭에 많아요.","토끼풀이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#6','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C5',3,'ox','auto','식물을 관찰할 때 잎을 함부로 꺾어 가져가도 괜찮아요.',ARRAY['SC3-1-u3-X05']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C5","difficulty":3,"kind":"ox","stem":"식물을 관찰할 때 잎을 함부로 꺾어 가져가도 괜찮아요.","answer":"X","reason_options":[{"t":"식물도 살아 있으니 꺾지 않고 그 자리에서 자세히 살펴봐야 하기 때문에","correct":true},{"t":"관찰하려면 꼭 꺾어서 가져가야 하기 때문에","mis":"SC3-1-u3-X05"}],"mis":"SC3-1-u3-X05","explanation":["식물도 살아 있어요.","그 자리에서 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#7','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C2',3,'mc','auto','식물 관찰 수첩의 민들레와 소나무를 바르게 견준 것은 무엇인가요?',ARRAY['SC3-1-u3-X02','SC3-1-u3-X03']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C2","difficulty":3,"kind":"mc","stem":"식물 관찰 수첩의 민들레와 소나무를 바르게 견준 것은 무엇인가요?","options":[{"t":"민들레는 노란 꽃이 피고, 소나무는 키가 크고 잎이 바늘 모양이에요","correct":true},{"t":"둘 다 키가 크고 잎이 바늘 모양이에요","mis":"SC3-1-u3-X02"},{"t":"민들레는 잎이 바늘 모양이고 소나무는 노란 꽃이 펴요","mis":"SC3-1-u3-X03"},{"t":"둘 다 노란 꽃이 피고 솜털 씨앗이 날아가요","mis":"SC3-1-u3-X02"}],"explanation":["두 줄을 견줘요.","서로 달라요.","첫 번째예요."],"asset":{"type":"passage","lines":["민들레 — 길가에 자람 · 노란 꽃 · 솜털 씨앗이 바람에 날아감","소나무 — 산 · 키가 큰 나무 · 잎이 바늘 모양 · 겨울에도 푸름","토끼풀 — 풀밭 · 키가 작음 · 잎이 세 장처럼 보임","강아지풀 — 들이나 길가 · 잎이 가늘고 긺 · 꽃이 복슬복슬함","튤립 — 학교 화단 · 사람이 심어 기름"],"title":"식물 관찰 수첩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#8','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C2',4,'mc','auto','친구가 「식물은 다 초록색이니 생김새가 모두 같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X02','SC3-1-u3-X01','SC3-1-u3-X05']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C2","difficulty":4,"kind":"mc","stem":"친구가 「식물은 다 초록색이니 생김새가 모두 같아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「잎이 바늘 모양인 소나무, 잎이 세 장처럼 보이는 토끼풀처럼 식물마다 생김새가 달라.」","correct":true},{"t":"「맞아, 식물은 생김새가 모두 같아.」","mis":"SC3-1-u3-X02"},{"t":"「식물은 산에만 살아서 우리는 볼 수 없어.」","mis":"SC3-1-u3-X01"},{"t":"「생김새는 꺾어 보아야만 알 수 있어.」","mis":"SC3-1-u3-X05"}],"explanation":["소나무와 토끼풀을 견줘요.","잎이 달라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#9','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C1',4,'mc','auto','친구가 「우리 학교에는 식물이 없어. 식물은 산에 가야만 볼 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X01','SC3-1-u3-X04','SC3-1-u3-X02']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C1","difficulty":4,"kind":"mc","stem":"친구가 「우리 학교에는 식물이 없어. 식물은 산에 가야만 볼 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「학교 화단의 튤립, 길가의 민들레처럼 식물은 우리 주변 곳곳에 살아.」","correct":true},{"t":"「맞아, 식물은 산에만 살아.」","mis":"SC3-1-u3-X01"},{"t":"「화단에서 기르는 꽃은 들에서 절로 자란 거야.」","mis":"SC3-1-u3-X04"},{"t":"「식물은 모두 생김새가 같아.」","mis":"SC3-1-u3-X02"}],"explanation":["화단과 길가를 떠올려요.","곳곳에 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L01_challenge#10','sci',3,1,'u3','L01','g3_1_sci_u3_L01_challenge','lesson_challenge','SC3-1-u3-C3',4,'essay','teacher','우리 주변에서 본 식물 하나를 골라 어디에서 보았는지 쓰고, 잎·꽃·줄기 가운데 두 가지의 생김새를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u3-C3","difficulty":4,"kind":"essay","stem":"우리 주변에서 본 식물 하나를 골라 어디에서 보았는지 쓰고, 잎·꽃·줄기 가운데 두 가지의 생김새를 쓰세요.","answer_guide":{"answer":"예: 학교 길가에서 민들레를 보았다. 꽃은 노란색이고, 꽃이 진 뒤에는 하얀 솜털 씨앗이 생겨 바람에 날아갔다.","scoring_points":["식물을 본 곳을 썼는가","생김새 두 가지를 썼는가","보이는 그대로 자세히 썼는가"]},"explanation":["본 식물을 떠올려요.","어디서 보았나요?","생김새 두 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#1','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C6',1,'mc','auto','잎에서 넓고 납작한 부분을 무엇이라고 하나요?',ARRAY['SC3-1-u3-X06']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C6","difficulty":1,"kind":"mc","stem":"잎에서 넓고 납작한 부분을 무엇이라고 하나요?","options":[{"t":"잎몸","correct":true},{"t":"잎맥","mis":"SC3-1-u3-X06"},{"t":"잎자루","mis":"SC3-1-u3-X06"},{"t":"뿌리","mis":"SC3-1-u3-X06"}],"explanation":["넓은 부분이에요.","잎의 몸통이에요.","「잎몸」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#2','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C9',1,'mc','auto','잎을 분류하는 기준으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X09']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C9","difficulty":1,"kind":"mc","stem":"잎을 분류하는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"가장자리가 톱니 모양인가?","correct":true},{"t":"잎이 예쁜가?","mis":"SC3-1-u3-X09"},{"t":"잎이 마음에 드는가?","mis":"SC3-1-u3-X09"},{"t":"잎이 멋져 보이는가?","mis":"SC3-1-u3-X09"}],"explanation":["누가 해도 같아야 해요.","그렇다·그렇지 않다예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#3','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C8',1,'ox','auto','잎을 분류하려면 먼저 잎을 자세히 관찰해 특징을 찾아야 해요.',ARRAY['SC3-1-u3-X08']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C8","difficulty":1,"kind":"ox","stem":"잎을 분류하려면 먼저 잎을 자세히 관찰해 특징을 찾아야 해요.","answer":"O","reason_options":[{"t":"특징을 알아야 공통점과 차이점을 찾아 기준을 정할 수 있기 때문에","correct":true},{"t":"관찰하지 않고 아무렇게나 나누어도 되기 때문에","mis":"SC3-1-u3-X08"}],"mis":"SC3-1-u3-X08","explanation":["분류의 첫걸음이에요.","자세히 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#4','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C6',1,'sa','auto','잎몸을 줄기에 잇는 자루를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u3-C6","difficulty":1,"kind":"sa","stem":"잎몸을 줄기에 잇는 자루를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["잎자루"],"explanation":["자루예요.","잎 + 자루예요.","「잎자루」예요."],"mis":"SC3-1-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#5','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C7',2,'match','auto','잎 관찰 기록을 보고 잎과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u3-C7","difficulty":2,"kind":"match","stem":"잎 관찰 기록을 보고 잎과 특징을 알맞게 이으세요.","pairs":[{"l":"단풍나무","r":"잎몸이 여러 갈래로 갈라짐"},{"l":"강아지풀","r":"잎맥이 나란히 뻗음"},{"l":"은행나무","r":"부채 모양"}],"mis":"SC3-1-u3-X07","explanation":["기록을 한 줄씩 읽어요.","특징을 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#6','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C11',2,'mc','auto','잎 관찰 기록을 「가장자리가 톱니 모양인가?」로 나눌 때 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u3-X10','SC3-1-u3-X07']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C11","difficulty":2,"kind":"mc","stem":"잎 관찰 기록을 「가장자리가 톱니 모양인가?」로 나눌 때 「그렇다」 무리는 무엇인가요?","options":[{"t":"단풍나무, 토끼풀, 민들레","correct":true},{"t":"은행나무, 강아지풀, 소나무","mis":"SC3-1-u3-X10"},{"t":"단풍나무, 은행나무, 소나무","mis":"SC3-1-u3-X07"},{"t":"강아지풀, 토끼풀, 민들레","mis":"SC3-1-u3-X07"}],"explanation":["「톱니」를 찾아요.","세 잎이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#7','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C10',2,'ox','auto','「잎이 예쁜가?」는 누가 나누어도 결과가 같은 알맞은 분류 기준이에요.',ARRAY['SC3-1-u3-X09']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C10","difficulty":2,"kind":"ox","stem":"「잎이 예쁜가?」는 누가 나누어도 결과가 같은 알맞은 분류 기준이에요.","answer":"X","reason_options":[{"t":"예쁘다고 느끼는 것은 사람마다 달라 분류 결과가 달라지기 때문에","correct":true},{"t":"예쁜 잎은 누가 보아도 똑같이 예쁘기 때문에","mis":"SC3-1-u3-X09"}],"mis":"SC3-1-u3-X09","explanation":["사람마다 같을까요?","다를 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#8','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C6',2,'mc','auto','물과 양분이 지나는 줄로, 잎몸에 퍼져 있는 것은 무엇인가요?',ARRAY['SC3-1-u3-X06']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C6","difficulty":2,"kind":"mc","stem":"물과 양분이 지나는 줄로, 잎몸에 퍼져 있는 것은 무엇인가요?","options":[{"t":"잎맥","correct":true},{"t":"잎자루","mis":"SC3-1-u3-X06"},{"t":"잎몸","mis":"SC3-1-u3-X06"},{"t":"꽃잎","mis":"SC3-1-u3-X06"}],"explanation":["줄이에요.","잎에 퍼져 있어요.","「잎맥」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#9','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C11',2,'mc','auto','잎 관찰 기록을 「잎이 길쭉한가?」로 나눌 때 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u3-X10','SC3-1-u3-X07']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C11","difficulty":2,"kind":"mc","stem":"잎 관찰 기록을 「잎이 길쭉한가?」로 나눌 때 「그렇다」 무리는 무엇인가요?","options":[{"t":"강아지풀, 소나무","correct":true},{"t":"단풍나무, 민들레","mis":"SC3-1-u3-X10"},{"t":"은행나무, 토끼풀","mis":"SC3-1-u3-X07"},{"t":"강아지풀, 은행나무","mis":"SC3-1-u3-X07"}],"explanation":["「길쭉함」을 찾아요.","두 잎이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_basic#10','sci',3,1,'u3','L02','g3_1_sci_u3_L02_basic','lesson_basic','SC3-1-u3-C8',3,'mc','auto','잎을 분류하는 차례를 바르게 늘어놓은 것은 무엇인가요?',ARRAY['SC3-1-u3-X08']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C8","difficulty":3,"kind":"mc","stem":"잎을 분류하는 차례를 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"잎을 자세히 관찰해요 → 공통점과 차이점을 찾아요 → 기준을 정해 무리 지어요","correct":true},{"t":"기준을 정해 무리 지어요 → 잎을 관찰해요 → 공통점을 찾아요","mis":"SC3-1-u3-X08"},{"t":"공통점을 찾아요 → 무리 지어요 → 잎을 관찰해요","mis":"SC3-1-u3-X08"},{"t":"관찰하지 않고 바로 무리 지어요","mis":"SC3-1-u3-X08"}],"explanation":["먼저 무엇을 할까요?","관찰이 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#1','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C9',2,'blank','auto','「좋은 분류 기준은 누가 나누어도 결과가 (      ) 명확한 기준이에요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u3-X09','SC3-1-u3-X10']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C9","difficulty":2,"kind":"blank","stem":"「좋은 분류 기준은 누가 나누어도 결과가 (      ) 명확한 기준이에요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"같은","correct":true},{"t":"다른","mis":"SC3-1-u3-X09"},{"t":"예쁜","mis":"SC3-1-u3-X09"},{"t":"많은","mis":"SC3-1-u3-X10"}],"explanation":["누가 해도 어떤가요?","결과가 같아요.","「같은」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#2','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C7',2,'mc','auto','잎 관찰 기록에서 잎맥이 그물처럼 퍼진 잎은 무엇인가요?',ARRAY['SC3-1-u3-X07']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C7","difficulty":2,"kind":"mc","stem":"잎 관찰 기록에서 잎맥이 그물처럼 퍼진 잎은 무엇인가요?","options":[{"t":"단풍나무 잎","correct":true},{"t":"강아지풀 잎","mis":"SC3-1-u3-X07"},{"t":"소나무 잎","mis":"SC3-1-u3-X07"},{"t":"은행나무 잎","mis":"SC3-1-u3-X07"}],"explanation":["「그물처럼」을 찾아요.","첫 줄이에요.","단풍나무예요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#3','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C10',3,'error','auto','친구들이 잎을 나눌 기준을 정했어요. 알맞지 않은 기준을 정한 친구는 누구인가요?',ARRAY['SC3-1-u3-X09']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C10","difficulty":3,"kind":"error","stem":"친구들이 잎을 나눌 기준을 정했어요. 알맞지 않은 기준을 정한 친구는 누구인가요?","options":[{"t":"친구 다 — 「잎이 마음에 드는가?」","correct":true,"mis_target":"SC3-1-u3-X09"},{"t":"친구 가 — 「잎이 갈라져 있는가?」","mis":"SC3-1-u3-X09"},{"t":"친구 나 — 「잎이 길쭉한가?」","mis":"SC3-1-u3-X09"}],"explanation":["마음은 사람마다 달라요.","느낌 기준이에요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#4','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C11',3,'mc','auto','잎 관찰 기록을 「잎이 갈라져 있는가?」로 나눌 때 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u3-X07','SC3-1-u3-X10']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C11","difficulty":3,"kind":"mc","stem":"잎 관찰 기록을 「잎이 갈라져 있는가?」로 나눌 때 「그렇다」 무리는 무엇인가요?","options":[{"t":"단풍나무, 민들레","correct":true},{"t":"단풍나무, 토끼풀","mis":"SC3-1-u3-X07"},{"t":"강아지풀, 소나무","mis":"SC3-1-u3-X10"},{"t":"은행나무, 민들레","mis":"SC3-1-u3-X07"}],"explanation":["「갈라짐」을 찾아요.","두 잎이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#5','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C7',3,'mc','auto','잎 관찰 기록에서 가장자리가 매끈한 잎끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X07']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C7","difficulty":3,"kind":"mc","stem":"잎 관찰 기록에서 가장자리가 매끈한 잎끼리 모은 것은 무엇인가요?","options":[{"t":"은행나무, 강아지풀, 소나무","correct":true},{"t":"단풍나무, 토끼풀, 민들레","mis":"SC3-1-u3-X07"},{"t":"은행나무, 토끼풀, 민들레","mis":"SC3-1-u3-X07"},{"t":"단풍나무, 강아지풀, 소나무","mis":"SC3-1-u3-X07"}],"explanation":["「매끈」을 찾아요.","세 잎이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#6','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C11',3,'ox','auto','같은 잎들이라도 분류 기준을 바꾸면 무리가 달라질 수 있어요.',ARRAY['SC3-1-u3-X10']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C11","difficulty":3,"kind":"ox","stem":"같은 잎들이라도 분류 기준을 바꾸면 무리가 달라질 수 있어요.","answer":"O","reason_options":[{"t":"톱니 기준에서는 토끼풀이 단풍나무와 같은 무리였지만 갈라짐 기준에서는 다른 무리가 되기 때문에","correct":true},{"t":"한 잎은 어떤 기준으로 나누어도 늘 같은 무리에 들기 때문에","mis":"SC3-1-u3-X10"}],"mis":"SC3-1-u3-X10","explanation":["토끼풀을 따라가 봐요.","무리가 바뀌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#7','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C6',3,'mc','auto','잎의 부분과 그 설명을 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u3-X06']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C6","difficulty":3,"kind":"mc","stem":"잎의 부분과 그 설명을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"잎자루 — 잎몸을 줄기에 이어요, 잎맥 — 물과 양분이 지나는 줄이에요","correct":true},{"t":"잎몸 — 잎을 줄기에 이어요, 잎자루 — 물이 지나는 줄이에요","mis":"SC3-1-u3-X06"},{"t":"잎맥 — 넓고 납작한 부분이에요, 잎몸 — 줄기에 잇는 자루예요","mis":"SC3-1-u3-X06"},{"t":"잎자루 — 넓고 납작한 부분이에요, 잎맥 — 잎을 줄기에 이어요","mis":"SC3-1-u3-X06"}],"explanation":["세 부분을 떠올려요.","자루와 줄이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#8','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C9',4,'mc','auto','친구가 「‘잎이 예쁜가?’로 나누자. 내가 보기에 예쁘면 그렇다야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X09','SC3-1-u3-X10','SC3-1-u3-X08']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C9","difficulty":4,"kind":"mc","stem":"친구가 「‘잎이 예쁜가?’로 나누자. 내가 보기에 예쁘면 그렇다야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「예쁜 정도는 사람마다 달라서, ‘가장자리가 톱니 모양인가?’처럼 누가 나누어도 같은 기준을 쓰자.」","correct":true},{"t":"「좋아, 내 느낌대로 나누면 돼.」","mis":"SC3-1-u3-X09"},{"t":"「기준은 한 번 정하면 절대 바꿀 수 없어.」","mis":"SC3-1-u3-X10"},{"t":"「관찰하지 말고 이름 순서대로 나누자.」","mis":"SC3-1-u3-X08"}],"explanation":["누가 해도 같을까요?","아니에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#9','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C11',4,'mc','auto','친구가 「토끼풀은 단풍나무와 늘 같은 무리야.」라고 했어요. 잎 관찰 기록을 보고 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X10','SC3-1-u3-X07','SC3-1-u3-X08']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C11","difficulty":4,"kind":"mc","stem":"친구가 「토끼풀은 단풍나무와 늘 같은 무리야.」라고 했어요. 잎 관찰 기록을 보고 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「톱니 기준으로는 같은 무리지만 ‘잎이 갈라져 있는가?’로 나누면 서로 다른 무리야.」","correct":true},{"t":"「맞아, 어떤 기준이든 늘 같은 무리야.」","mis":"SC3-1-u3-X10"},{"t":"「토끼풀은 잎몸이 여러 갈래로 갈라져 있어.」","mis":"SC3-1-u3-X07"},{"t":"「잎은 관찰하지 않고 나누어도 돼.」","mis":"SC3-1-u3-X08"}],"explanation":["갈라짐 줄을 읽어요.","토끼풀은 갈라지지 않아요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L02_challenge#10','sci',3,1,'u3','L02','g3_1_sci_u3_L02_challenge','lesson_challenge','SC3-1-u3-C9',4,'essay','teacher','잎 관찰 기록의 잎 가운데 네 가지를 골라, 누가 나누어도 결과가 같은 기준을 하나 정해 두 무리로 나누어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u3-C9","difficulty":4,"kind":"essay","stem":"잎 관찰 기록의 잎 가운데 네 가지를 골라, 누가 나누어도 결과가 같은 기준을 하나 정해 두 무리로 나누어 쓰세요.","answer_guide":{"answer":"예: 단풍나무, 은행나무, 강아지풀, 민들레를 골라 「잎이 갈라져 있는가?」로 나누면, 그렇다 = 단풍나무·민들레, 그렇지 않다 = 은행나무·강아지풀이다.","scoring_points":["그렇다·그렇지 않다로 나뉘는 분명한 기준을 정했는가","기준에 맞게 두 무리로 나누었는가","고른 잎이 관찰 기록과 맞게 들어갔는가"]},"explanation":["기록을 읽어요.","분명한 기준이에요.","두 무리로 써요."],"asset":{"type":"passage","lines":["단풍나무 — 가장자리 톱니 · 잎몸이 여러 갈래로 갈라짐 · 잎맥이 그물처럼","은행나무 — 가장자리 매끈 · 부채 모양 · 갈라지지 않음","강아지풀 — 가장자리 매끈 · 잎이 길쭉함 · 잎맥이 나란히 뻗음","토끼풀 — 가장자리 톱니 · 갈라지지 않음","민들레 — 가장자리 톱니 · 잎몸이 갈라짐","소나무 — 가장자리 매끈 · 잎이 바늘처럼 길쭉함"],"title":"잎 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_basic#1','sci',3,1,'u3','L03','g3_1_sci_u3_L03_basic','lesson_basic','SC3-1-u3-C12',1,'mc','auto','들과 산에 사는 식물에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X11']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C12","difficulty":1,"kind":"mc","stem":"들과 산에 사는 식물에 대해 알맞은 것은 무엇인가요?","options":[{"t":"풀도 살고 나무도 살아요","correct":true},{"t":"풀만 살아요","mis":"SC3-1-u3-X11"},{"t":"나무만 살아요","mis":"SC3-1-u3-X11"},{"t":"식물이 살지 않아요","mis":"SC3-1-u3-X11"}],"explanation":["민들레와 소나무를 떠올려요.","둘 다 살아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_basic#2','sci',3,1,'u3','L03','g3_1_sci_u3_L03_basic','lesson_basic','SC3-1-u3-C13',1,'mc','auto','풀끼리 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u3-X12']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C13","difficulty":1,"kind":"mc","stem":"풀끼리 짝 지은 것은 무엇인가요?","options":[{"t":"민들레, 강아지풀","correct":true},{"t":"소나무, 단풍나무","mis":"SC3-1-u3-X12"},{"t":"밤나무, 소나무","mis":"SC3-1-u3-X12"},{"t":"단풍나무, 민들레","mis":"SC3-1-u3-X12"}],"explanation":["줄기가 가늘고 연해요.","키가 작아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_basic#3','sci',3,1,'u3','L03','g3_1_sci_u3_L03_basic','lesson_basic','SC3-1-u3-C14',1,'ox','auto','나무는 줄기가 굵고 단단해요.',ARRAY['SC3-1-u3-X12']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C14","difficulty":1,"kind":"ox","stem":"나무는 줄기가 굵고 단단해요.","answer":"O","reason_options":[{"t":"소나무와 단풍나무처럼 나무는 줄기가 굵고 단단하기 때문에","correct":true},{"t":"나무의 줄기는 풀보다 가늘고 연하기 때문에","mis":"SC3-1-u3-X12"}],"mis":"SC3-1-u3-X12","explanation":["소나무 줄기를 떠올려요.","굵고 단단해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_basic#4','sci',3,1,'u3','L03','g3_1_sci_u3_L03_basic','lesson_basic','SC3-1-u3-C15',1,'sa','auto','풀과 나무는 모두 땅에 무엇을 내리고 살아가나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u3-C15","difficulty":1,"kind":"sa","stem":"풀과 나무는 모두 땅에 무엇을 내리고 살아가나요? 두 글자로 쓰세요.","answer":["뿌리"],"explanation":["땅속으로 뻗어요.","두 글자예요.","「뿌리」예요."],"mis":"SC3-1-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_basic#5','sci',3,1,'u3','L03','g3_1_sci_u3_L03_basic','lesson_basic','SC3-1-u3-C13',2,'match','auto','관찰표를 보고 식물과 줄기의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u3-C13","difficulty":2,"kind":"match","stem":"관찰표를 보고 식물과 줄기의 특징을 알맞게 이으세요.","pairs":[{"l":"강아지풀","r":"줄기가 가늘고 연함"},{"l":"소나무","r":"줄기가 굵고 단단함"},{"l":"진달래","r":"나무지만 키가 작은 편"}],"mis":"SC3-1-u3-X12","explanation":["줄기 칸을 읽어요.","풀과 나무예요.","하나씩 이어요."],"asset":{"type":"passage","lines":["민들레 — 풀 · 줄기가 가늘고 연함 · 키가 작음","강아지풀 — 풀 · 줄기가 가늘고 연함 · 키가 작음","토끼풀 — 풀 · 줄기가 가늘고 연함 · 땅을 따라 낮게 퍼짐","소나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","단풍나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","진달래 — 나무 · 줄기가 단단함 · 키가 작은 편","모두 뿌리·줄기·잎이 있고 땅에 뿌리를 내림"],"title":"들과 산 식물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_basic#6','sci',3,1,'u3','L03','g3_1_sci_u3_L03_basic','lesson_basic','SC3-1-u3-C14',2,'mc','auto','관찰표에서 나무끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X12','SC3-1-u3-X13']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C14","difficulty":2,"kind":"mc","stem":"관찰표에서 나무끼리 모은 것은 무엇인가요?","options":[{"t":"소나무, 단풍나무, 진달래","correct":true},{"t":"민들레, 강아지풀, 토끼풀","mis":"SC3-1-u3-X12"},{"t":"소나무, 단풍나무, 민들레","mis":"SC3-1-u3-X13"},{"t":"강아지풀, 진달래, 토끼풀","mis":"SC3-1-u3-X13"}],"explanation":["「나무」를 찾아요.","세 가지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["민들레 — 풀 · 줄기가 가늘고 연함 · 키가 작음","강아지풀 — 풀 · 줄기가 가늘고 연함 · 키가 작음","토끼풀 — 풀 · 줄기가 가늘고 연함 · 땅을 따라 낮게 퍼짐","소나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","단풍나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","진달래 — 나무 · 줄기가 단단함 · 키가 작은 편","모두 뿌리·줄기·잎이 있고 땅에 뿌리를 내림"],"title":"들과 산 식물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_basic#7','sci',3,1,'u3','L03','g3_1_sci_u3_L03_basic','lesson_basic','SC3-1-u3-C15',2,'ox','auto','관찰표를 보면 풀과 나무는 모두 뿌리, 줄기, 잎이 있어요.',ARRAY['SC3-1-u3-X14']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C15","difficulty":2,"kind":"ox","stem":"관찰표를 보면 풀과 나무는 모두 뿌리, 줄기, 잎이 있어요.","answer":"O","reason_options":[{"t":"관찰표 마지막 줄에 모두 뿌리·줄기·잎이 있다고 적혀 있기 때문에","correct":true},{"t":"풀은 뿌리가 없고 잎만 있기 때문에","mis":"SC3-1-u3-X14"}],"mis":"SC3-1-u3-X14","explanation":["마지막 줄을 읽어요.","모두 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["민들레 — 풀 · 줄기가 가늘고 연함 · 키가 작음","강아지풀 — 풀 · 줄기가 가늘고 연함 · 키가 작음","토끼풀 — 풀 · 줄기가 가늘고 연함 · 땅을 따라 낮게 퍼짐","소나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","단풍나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","진달래 — 나무 · 줄기가 단단함 · 키가 작은 편","모두 뿌리·줄기·잎이 있고 땅에 뿌리를 내림"],"title":"들과 산 식물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
