INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_challenge#6','sci',3,1,'u3','L03','g3_1_sci_u3_L03_challenge','lesson_challenge','SC3-1-u3-C13',3,'ox','auto','풀 가운데에는 한 해만 살고 시드는 것이 많아요.',ARRAY['SC3-1-u3-X12']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C13","difficulty":3,"kind":"ox","stem":"풀 가운데에는 한 해만 살고 시드는 것이 많아요.","answer":"O","reason_options":[{"t":"민들레처럼 여러 해 사는 풀도 있지만 한 해만 살고 시드는 풀이 많기 때문에","correct":true},{"t":"풀은 모두 나무처럼 해마다 줄기가 굵어지기 때문에","mis":"SC3-1-u3-X12"}],"mis":"SC3-1-u3-X12","explanation":["풀의 한살이를 떠올려요.","한 해만 사는 풀이 많아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_challenge#7','sci',3,1,'u3','L03','g3_1_sci_u3_L03_challenge','lesson_challenge','SC3-1-u3-C14',3,'mc','auto','들에서 밤나무를 보았어요. 어느 무리에 넣으면 알맞을까요?',ARRAY['SC3-1-u3-X11','SC3-1-u3-X14','SC3-1-u3-X13']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C14","difficulty":3,"kind":"mc","stem":"들에서 밤나무를 보았어요. 어느 무리에 넣으면 알맞을까요?","options":[{"t":"나무 — 줄기가 굵고 단단해서","correct":true},{"t":"풀 — 들에서 자라서","mis":"SC3-1-u3-X11"},{"t":"풀 — 잎이 초록색이라서","mis":"SC3-1-u3-X14"},{"t":"나무 — 꽃이 피어서","mis":"SC3-1-u3-X13"}],"explanation":["사는 곳 말고 줄기를 봐요.","굵고 단단해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_challenge#8','sci',3,1,'u3','L03','g3_1_sci_u3_L03_challenge','lesson_challenge','SC3-1-u3-C16',4,'mc','auto','친구가 「키가 작은 식물은 모두 풀이고, 나무는 모두 키가 아주 커.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X13','SC3-1-u3-X11','SC3-1-u3-X14']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C16","difficulty":4,"kind":"mc","stem":"친구가 「키가 작은 식물은 모두 풀이고, 나무는 모두 키가 아주 커.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「진달래는 키가 작은 편이지만 줄기가 단단한 나무야. 키보다 줄기를 보고 나눠야 해.」","correct":true},{"t":"「맞아, 키만 보면 알 수 있어.」","mis":"SC3-1-u3-X13"},{"t":"「풀과 나무는 들과 산에 함께 살지 않아.」","mis":"SC3-1-u3-X11"},{"t":"「나무는 뿌리가 없어서 키가 커.」","mis":"SC3-1-u3-X14"}],"explanation":["진달래를 떠올려요.","줄기가 단단해요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["민들레 — 풀 · 줄기가 가늘고 연함 · 키가 작음","강아지풀 — 풀 · 줄기가 가늘고 연함 · 키가 작음","토끼풀 — 풀 · 줄기가 가늘고 연함 · 땅을 따라 낮게 퍼짐","소나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","단풍나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","진달래 — 나무 · 줄기가 단단함 · 키가 작은 편","모두 뿌리·줄기·잎이 있고 땅에 뿌리를 내림"],"title":"들과 산 식물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_challenge#9','sci',3,1,'u3','L03','g3_1_sci_u3_L03_challenge','lesson_challenge','SC3-1-u3-C12',4,'mc','auto','친구가 「산에는 나무만 살고 풀은 살지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X11','SC3-1-u3-X12']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C12","difficulty":4,"kind":"mc","stem":"친구가 「산에는 나무만 살고 풀은 살지 않아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「산에도 들에도 풀과 나무가 함께 살아.」","correct":true},{"t":"「맞아, 산에는 나무만 살아.」","mis":"SC3-1-u3-X11"},{"t":"「산에는 식물이 하나도 없어.」","mis":"SC3-1-u3-X11"},{"t":"「풀은 줄기가 굵어서 산에 못 살아.」","mis":"SC3-1-u3-X12"}],"explanation":["산길을 떠올려요.","풀도 있어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L03_challenge#10','sci',3,1,'u3','L03','g3_1_sci_u3_L03_challenge','lesson_challenge','SC3-1-u3-C16',4,'essay','teacher','관찰표에서 풀 하나와 나무 하나를 골라 줄기를 견주어 쓰고, 둘의 공통점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u3-C16","difficulty":4,"kind":"essay","stem":"관찰표에서 풀 하나와 나무 하나를 골라 줄기를 견주어 쓰고, 둘의 공통점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 강아지풀은 줄기가 가늘고 연한 풀이고, 소나무는 줄기가 굵고 단단한 나무이다. 둘 다 뿌리, 줄기, 잎이 있고 땅에 뿌리를 내리고 산다.","scoring_points":["풀의 줄기 특징을 썼는가","나무의 줄기 특징을 썼는가","공통점을 바르게 썼는가"]},"explanation":["관찰표를 읽어요.","줄기를 견줘요.","공통점도 써요."],"asset":{"type":"passage","lines":["민들레 — 풀 · 줄기가 가늘고 연함 · 키가 작음","강아지풀 — 풀 · 줄기가 가늘고 연함 · 키가 작음","토끼풀 — 풀 · 줄기가 가늘고 연함 · 땅을 따라 낮게 퍼짐","소나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","단풍나무 — 나무 · 줄기가 굵고 단단함 · 키가 큼","진달래 — 나무 · 줄기가 단단함 · 키가 작은 편","모두 뿌리·줄기·잎이 있고 땅에 뿌리를 내림"],"title":"들과 산 식물 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_basic#1','sci',3,1,'u3','L04','g3_1_sci_u3_L04_basic','lesson_basic','SC3-1-u3-C18',1,'mc','auto','물 위에 떠서 사는 식물끼리 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u3-X16','SC3-1-u3-X15']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C18","difficulty":1,"kind":"mc","stem":"물 위에 떠서 사는 식물끼리 짝 지은 것은 무엇인가요?","options":[{"t":"부레옥잠, 개구리밥","correct":true},{"t":"검정말, 나사말","mis":"SC3-1-u3-X16"},{"t":"소나무, 단풍나무","mis":"SC3-1-u3-X15"},{"t":"부들, 수련","mis":"SC3-1-u3-X16"}],"explanation":["물 위를 떠다녀요.","뿌리가 땅에 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_basic#2','sci',3,1,'u3','L04','g3_1_sci_u3_L04_basic','lesson_basic','SC3-1-u3-C19',1,'mc','auto','부레옥잠이 물에 뜨는 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X17']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C19","difficulty":1,"kind":"mc","stem":"부레옥잠이 물에 뜨는 까닭은 무엇인가요?","options":[{"t":"잎자루에 공기주머니가 있어서","correct":true},{"t":"뿌리가 매우 무거워서","mis":"SC3-1-u3-X17"},{"t":"줄기가 굵고 단단해서","mis":"SC3-1-u3-X17"},{"t":"잎이 빨간색이어서","mis":"SC3-1-u3-X17"}],"explanation":["볼록한 잎자루예요.","속에 공기가 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_basic#3','sci',3,1,'u3','L04','g3_1_sci_u3_L04_basic','lesson_basic','SC3-1-u3-C17',1,'ox','auto','강이나 연못 같은 물에도 식물이 살아요.',ARRAY['SC3-1-u3-X15']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C17","difficulty":1,"kind":"ox","stem":"강이나 연못 같은 물에도 식물이 살아요.","answer":"O","reason_options":[{"t":"부레옥잠, 수련, 검정말처럼 물에 사는 식물이 있기 때문에","correct":true},{"t":"식물은 땅에서만 살 수 있기 때문에","mis":"SC3-1-u3-X15"}],"mis":"SC3-1-u3-X15","explanation":["연못을 떠올려요.","식물이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_basic#4','sci',3,1,'u3','L04','g3_1_sci_u3_L04_basic','lesson_basic','SC3-1-u3-C19',1,'sa','auto','부레옥잠의 볼록한 잎자루 속에는 무엇이 들어 있나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u3-C19","difficulty":1,"kind":"sa","stem":"부레옥잠의 볼록한 잎자루 속에는 무엇이 들어 있나요? 두 글자로 쓰세요.","answer":["공기"],"explanation":["풍선 속에도 있어요.","두 글자예요.","「공기」예요."],"mis":"SC3-1-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_basic#5','sci',3,1,'u3','L04','g3_1_sci_u3_L04_basic','lesson_basic','SC3-1-u3-C17',2,'match','auto','관찰 기록을 보고 식물과 사는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u3-C17","difficulty":2,"kind":"match","stem":"관찰 기록을 보고 식물과 사는 모습을 알맞게 이으세요.","pairs":[{"l":"개구리밥","r":"물 위에 떠서 삶"},{"l":"검정말","r":"물속에 잠겨 삶"},{"l":"부들","r":"물가에 곧게 솟아 삶"}],"mis":"SC3-1-u3-X16","explanation":["사는 모습을 읽어요.","세 가지예요.","하나씩 이어요."],"asset":{"type":"passage","lines":["부레옥잠 — 물에 떠서 삶 · 잎자루가 볼록하고 속에 공기가 있음","개구리밥 — 물에 떠서 삶 · 작은 잎이 물 위에 떠 있음","수련 — 둥글고 넓은 잎이 물 위에 뜸 · 뿌리는 물속 땅에 내림","검정말 — 물속에 잠겨 삶 · 줄기와 잎이 가늘고 부드러움 · 뿌리는 물속 땅","부들 — 물가에 삶 · 줄기가 단단하고 곧게 솟음 · 뿌리는 물속 땅"],"title":"연못 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_basic#6','sci',3,1,'u3','L04','g3_1_sci_u3_L04_basic','lesson_basic','SC3-1-u3-C20',2,'mc','auto','관찰 기록에서 물속에 잠겨 사는 식물은 무엇인가요?',ARRAY['SC3-1-u3-X16']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C20","difficulty":2,"kind":"mc","stem":"관찰 기록에서 물속에 잠겨 사는 식물은 무엇인가요?","options":[{"t":"검정말","correct":true},{"t":"부레옥잠","mis":"SC3-1-u3-X16"},{"t":"개구리밥","mis":"SC3-1-u3-X16"},{"t":"부들","mis":"SC3-1-u3-X16"}],"explanation":["「잠겨」를 찾아요.","줄기가 가늘어요.","검정말이에요."],"asset":{"type":"passage","lines":["부레옥잠 — 물에 떠서 삶 · 잎자루가 볼록하고 속에 공기가 있음","개구리밥 — 물에 떠서 삶 · 작은 잎이 물 위에 떠 있음","수련 — 둥글고 넓은 잎이 물 위에 뜸 · 뿌리는 물속 땅에 내림","검정말 — 물속에 잠겨 삶 · 줄기와 잎이 가늘고 부드러움 · 뿌리는 물속 땅","부들 — 물가에 삶 · 줄기가 단단하고 곧게 솟음 · 뿌리는 물속 땅"],"title":"연못 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_basic#7','sci',3,1,'u3','L04','g3_1_sci_u3_L04_basic','lesson_basic','SC3-1-u3-C22',2,'ox','auto','물에 사는 식물은 뿌리가 없어요.',ARRAY['SC3-1-u3-X19']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C22","difficulty":2,"kind":"ox","stem":"물에 사는 식물은 뿌리가 없어요.","answer":"X","reason_options":[{"t":"부레옥잠은 뿌리를 물속에 늘어뜨리고 수련과 부들은 물속 땅에 뿌리를 내리기 때문에","correct":true},{"t":"물에 사는 식물은 잎만으로 살기 때문에","mis":"SC3-1-u3-X19"}],"mis":"SC3-1-u3-X19","explanation":["「뿌리」를 찾아요.","뿌리가 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["부레옥잠 — 물에 떠서 삶 · 잎자루가 볼록하고 속에 공기가 있음","개구리밥 — 물에 떠서 삶 · 작은 잎이 물 위에 떠 있음","수련 — 둥글고 넓은 잎이 물 위에 뜸 · 뿌리는 물속 땅에 내림","검정말 — 물속에 잠겨 삶 · 줄기와 잎이 가늘고 부드러움 · 뿌리는 물속 땅","부들 — 물가에 삶 · 줄기가 단단하고 곧게 솟음 · 뿌리는 물속 땅"],"title":"연못 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
