INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_basic#10','sci',3,1,'u3','L04','g3_1_sci_u3_L04_basic','lesson_basic','SC3-1-u3-C20',3,'mc','auto','검정말의 줄기와 잎이 가늘고 부드러운 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X18','SC3-1-u3-X17']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C20","difficulty":3,"kind":"mc","stem":"검정말의 줄기와 잎이 가늘고 부드러운 까닭은 무엇인가요?","options":[{"t":"물의 흐름에 따라 잘 휘어지기 위해서","correct":true},{"t":"물 위로 높이 자라기 위해서","mis":"SC3-1-u3-X18"},{"t":"공기를 담아 물에 뜨기 위해서","mis":"SC3-1-u3-X17"},{"t":"햇빛을 막기 위해서","mis":"SC3-1-u3-X18"}],"explanation":["물속은 물이 흘러요.","휘어져야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
