INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_challenge#3','sci',3,1,'u3','L04','g3_1_sci_u3_L04_challenge','lesson_challenge','SC3-1-u3-C18',3,'error','auto','친구들이 연못 식물 관찰 기록을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u3-X16']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C18","difficulty":3,"kind":"error","stem":"친구들이 연못 식물 관찰 기록을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「검정말은 물 위에 떠서 살아.」","correct":true,"mis_target":"SC3-1-u3-X16"},{"t":"친구 가 — 「개구리밥은 물 위에 떠서 살아.」","mis":"SC3-1-u3-X16"},{"t":"친구 다 — 「부들은 물가에 곧게 솟아 살아.」","mis":"SC3-1-u3-X16"}],"explanation":["검정말 줄을 읽어요.","잠겨 살아요.","친구 나예요."],"asset":{"type":"passage","lines":["부레옥잠 — 물에 떠서 삶 · 잎자루가 볼록하고 속에 공기가 있음","개구리밥 — 물에 떠서 삶 · 작은 잎이 물 위에 떠 있음","수련 — 둥글고 넓은 잎이 물 위에 뜸 · 뿌리는 물속 땅에 내림","검정말 — 물속에 잠겨 삶 · 줄기와 잎이 가늘고 부드러움 · 뿌리는 물속 땅","부들 — 물가에 삶 · 줄기가 단단하고 곧게 솟음 · 뿌리는 물속 땅"],"title":"연못 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_challenge#4','sci',3,1,'u3','L04','g3_1_sci_u3_L04_challenge','lesson_challenge','SC3-1-u3-C17',3,'mc','auto','관찰 기록의 식물을 「뿌리가 물속 땅에 있나?」로 나눌 때 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u3-X16']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C17","difficulty":3,"kind":"mc","stem":"관찰 기록의 식물을 「뿌리가 물속 땅에 있나?」로 나눌 때 「그렇다」 무리는 무엇인가요?","options":[{"t":"수련, 검정말, 부들","correct":true},{"t":"부레옥잠, 개구리밥","mis":"SC3-1-u3-X16"},{"t":"부레옥잠, 수련, 부들","mis":"SC3-1-u3-X16"},{"t":"개구리밥, 검정말","mis":"SC3-1-u3-X16"}],"explanation":["「물속 땅」을 찾아요.","세 가지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["부레옥잠 — 물에 떠서 삶 · 잎자루가 볼록하고 속에 공기가 있음","개구리밥 — 물에 떠서 삶 · 작은 잎이 물 위에 떠 있음","수련 — 둥글고 넓은 잎이 물 위에 뜸 · 뿌리는 물속 땅에 내림","검정말 — 물속에 잠겨 삶 · 줄기와 잎이 가늘고 부드러움 · 뿌리는 물속 땅","부들 — 물가에 삶 · 줄기가 단단하고 곧게 솟음 · 뿌리는 물속 땅"],"title":"연못 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_challenge#5','sci',3,1,'u3','L04','g3_1_sci_u3_L04_challenge','lesson_challenge','SC3-1-u3-C19',3,'mc','auto','공기를 넣은 풍선이 물에 뜨는 것과 닮은 부레옥잠의 생김새는 무엇인가요?',ARRAY['SC3-1-u3-X17','SC3-1-u3-X18']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C19","difficulty":3,"kind":"mc","stem":"공기를 넣은 풍선이 물에 뜨는 것과 닮은 부레옥잠의 생김새는 무엇인가요?","options":[{"t":"공기주머니가 있는 볼록한 잎자루","correct":true},{"t":"물속에 늘어뜨린 뿌리","mis":"SC3-1-u3-X17"},{"t":"작고 둥근 꽃","mis":"SC3-1-u3-X17"},{"t":"가늘고 부드러운 줄기","mis":"SC3-1-u3-X18"}],"explanation":["풍선 속에는 공기가 있어요.","잎자루예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_challenge#6','sci',3,1,'u3','L04','g3_1_sci_u3_L04_challenge','lesson_challenge','SC3-1-u3-C20',3,'ox','auto','검정말이 굵고 단단한 줄기를 가졌다면 물의 흐름에 더 잘 견딜 거예요.',ARRAY['SC3-1-u3-X18']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C20","difficulty":3,"kind":"ox","stem":"검정말이 굵고 단단한 줄기를 가졌다면 물의 흐름에 더 잘 견딜 거예요.","answer":"X","reason_options":[{"t":"물속 식물은 가늘고 부드러워야 물이 흐를 때 꺾이지 않고 휘어지기 때문에","correct":true},{"t":"굵고 단단한 줄기는 물살에 휘지 않아 더 좋기 때문에","mis":"SC3-1-u3-X18"}],"mis":"SC3-1-u3-X18","explanation":["물살을 떠올려요.","휘어져야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_challenge#7','sci',3,1,'u3','L04','g3_1_sci_u3_L04_challenge','lesson_challenge','SC3-1-u3-C22',3,'mc','auto','물에 사는 식물의 생김새에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X19','SC3-1-u3-X15']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C22","difficulty":3,"kind":"mc","stem":"물에 사는 식물의 생김새에 대해 알맞은 것은 무엇인가요?","options":[{"t":"사는 모습에 따라 물에서 살기 알맞은 생김새를 가졌어요","correct":true},{"t":"모두 줄기가 굵고 단단해요","mis":"SC3-1-u3-X19"},{"t":"모두 물 위에 떠서 살아요","mis":"SC3-1-u3-X15"},{"t":"사는 곳과 생김새는 아무 관계가 없어요","mis":"SC3-1-u3-X19"}],"explanation":["부레옥잠과 검정말을 견줘요.","알맞게 생겼어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_challenge#8','sci',3,1,'u3','L04','g3_1_sci_u3_L04_challenge','lesson_challenge','SC3-1-u3-C19',4,'mc','auto','친구가 「부레옥잠은 뿌리가 무거워서 물에 떠.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X17','SC3-1-u3-X16','SC3-1-u3-X19']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C19","difficulty":4,"kind":"mc","stem":"친구가 「부레옥잠은 뿌리가 무거워서 물에 떠.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「무거우면 오히려 가라앉아. 잎자루 속 공기주머니 덕분에 떠.」","correct":true},{"t":"「맞아, 뿌리가 무거워서 떠.」","mis":"SC3-1-u3-X17"},{"t":"「부레옥잠은 물속에 잠겨 살아.」","mis":"SC3-1-u3-X16"},{"t":"「부레옥잠은 뿌리가 없어.」","mis":"SC3-1-u3-X19"}],"explanation":["무거운 돌을 떠올려요.","가라앉아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_challenge#9','sci',3,1,'u3','L04','g3_1_sci_u3_L04_challenge','lesson_challenge','SC3-1-u3-C17',4,'mc','auto','친구가 「물에 사는 식물은 모두 물 위에 떠서 살아.」라고 했어요. 관찰 기록을 보고 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X15','SC3-1-u3-X16']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C17","difficulty":4,"kind":"mc","stem":"친구가 「물에 사는 식물은 모두 물 위에 떠서 살아.」라고 했어요. 관찰 기록을 보고 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「검정말은 물속에 잠겨 살고, 부들은 물가에 솟아 살아. 사는 모습이 여러 가지야.」","correct":true},{"t":"「맞아, 모두 떠서 살아.」","mis":"SC3-1-u3-X15"},{"t":"「물에는 식물이 살지 않아.」","mis":"SC3-1-u3-X15"},{"t":"「부들은 물 위를 떠다녀.」","mis":"SC3-1-u3-X16"}],"explanation":["검정말과 부들을 봐요.","떠 있지 않아요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["부레옥잠 — 물에 떠서 삶 · 잎자루가 볼록하고 속에 공기가 있음","개구리밥 — 물에 떠서 삶 · 작은 잎이 물 위에 떠 있음","수련 — 둥글고 넓은 잎이 물 위에 뜸 · 뿌리는 물속 땅에 내림","검정말 — 물속에 잠겨 삶 · 줄기와 잎이 가늘고 부드러움 · 뿌리는 물속 땅","부들 — 물가에 삶 · 줄기가 단단하고 곧게 솟음 · 뿌리는 물속 땅"],"title":"연못 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L04_challenge#10','sci',3,1,'u3','L04','g3_1_sci_u3_L04_challenge','lesson_challenge','SC3-1-u3-C22',4,'essay','teacher','관찰 기록에서 부레옥잠과 검정말을 골라 사는 모습과 그에 알맞은 생김새를 각각 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u3-C22","difficulty":4,"kind":"essay","stem":"관찰 기록에서 부레옥잠과 검정말을 골라 사는 모습과 그에 알맞은 생김새를 각각 쓰세요.","answer_guide":{"answer":"예: 부레옥잠은 물 위에 떠서 사는데, 잎자루가 볼록하고 속에 공기가 있어 물에 잘 뜬다. 검정말은 물속에 잠겨 사는데, 줄기와 잎이 가늘고 부드러워 물의 흐름에 잘 휘어진다.","scoring_points":["부레옥잠의 사는 모습과 생김새를 이어 썼는가","검정말의 사는 모습과 생김새를 이어 썼는가","생김새가 사는 곳에 알맞다는 생각이 드러나는가"]},"explanation":["두 줄을 읽어요.","떠서 · 잠겨서예요.","생김새와 이어 써요."],"asset":{"type":"passage","lines":["부레옥잠 — 물에 떠서 삶 · 잎자루가 볼록하고 속에 공기가 있음","개구리밥 — 물에 떠서 삶 · 작은 잎이 물 위에 떠 있음","수련 — 둥글고 넓은 잎이 물 위에 뜸 · 뿌리는 물속 땅에 내림","검정말 — 물속에 잠겨 삶 · 줄기와 잎이 가늘고 부드러움 · 뿌리는 물속 땅","부들 — 물가에 삶 · 줄기가 단단하고 곧게 솟음 · 뿌리는 물속 땅"],"title":"연못 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#1','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C23',1,'mc','auto','사막에 사는 식물끼리 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u3-X20']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C23","difficulty":1,"kind":"mc","stem":"사막에 사는 식물끼리 짝 지은 것은 무엇인가요?","options":[{"t":"선인장, 용설란","correct":true},{"t":"부레옥잠, 개구리밥","mis":"SC3-1-u3-X20"},{"t":"수련, 부들","mis":"SC3-1-u3-X20"},{"t":"검정말, 나사말","mis":"SC3-1-u3-X20"}],"explanation":["물이 부족한 곳이에요.","가시와 두꺼운 잎이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#2','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C26',1,'mc','auto','선인장의 잎이 가시로 변한 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X22']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C26","difficulty":1,"kind":"mc","stem":"선인장의 잎이 가시로 변한 까닭은 무엇인가요?","options":[{"t":"물이 빠져나가는 것을 막기 위해서","correct":true},{"t":"더 빨리 자라기 위해서","mis":"SC3-1-u3-X22"},{"t":"꽃을 많이 피우기 위해서","mis":"SC3-1-u3-X22"},{"t":"물에 잘 뜨기 위해서","mis":"SC3-1-u3-X22"}],"explanation":["사막은 물이 귀해요.","물을 지켜요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#3','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C23',1,'ox','auto','사막처럼 물이 매우 부족한 곳에도 식물이 살아요.',ARRAY['SC3-1-u3-X20']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C23","difficulty":1,"kind":"ox","stem":"사막처럼 물이 매우 부족한 곳에도 식물이 살아요.","answer":"O","reason_options":[{"t":"선인장, 용설란, 알로에처럼 사막에 사는 식물이 있기 때문에","correct":true},{"t":"물이 부족한 곳에는 식물이 하나도 살 수 없기 때문에","mis":"SC3-1-u3-X20"}],"mis":"SC3-1-u3-X20","explanation":["선인장을 떠올려요.","사막에 살아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#4','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C24',1,'sa','auto','선인장은 몸의 어느 부분에 물을 저장하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u3-C24","difficulty":1,"kind":"sa","stem":"선인장은 몸의 어느 부분에 물을 저장하나요? 두 글자로 쓰세요.","answer":["줄기"],"explanation":["굵은 부분이에요.","두 글자예요.","「줄기」예요."],"mis":"SC3-1-u3-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#5','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C24',2,'match','auto','관찰 기록을 보고 식물과 생김새를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u3-C24","difficulty":2,"kind":"match","stem":"관찰 기록을 보고 식물과 생김새를 알맞게 이으세요.","pairs":[{"l":"선인장","r":"잎이 가시로 변함"},{"l":"알로에","r":"잎 속에 물기가 많음"},{"l":"바오바브나무","r":"줄기가 매우 굵음"}],"mis":"SC3-1-u3-X21","explanation":["기록을 한 줄씩 읽어요.","생김새를 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["선인장 — 굵은 줄기에 물을 저장함 · 잎이 가시로 변함 · 뿌리가 넓게 뻗음","바오바브나무 — 줄기가 매우 굵어 많은 물을 저장함","용설란 — 두껍고 큰 잎에 물을 저장함 · 잎 끝이 뾰족함","알로에 — 두툼한 잎에 물을 저장함 · 잎 속에 물기가 많음","사는 곳 — 비가 적게 오고 물이 매우 부족한 사막"],"title":"사막 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#6','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C25',2,'mc','auto','관찰 기록에서 잎에 물을 저장하는 식물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X21','SC3-1-u3-X20']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C25","difficulty":2,"kind":"mc","stem":"관찰 기록에서 잎에 물을 저장하는 식물끼리 모은 것은 무엇인가요?","options":[{"t":"용설란, 알로에","correct":true},{"t":"선인장, 바오바브나무","mis":"SC3-1-u3-X21"},{"t":"선인장, 용설란","mis":"SC3-1-u3-X21"},{"t":"부레옥잠, 검정말","mis":"SC3-1-u3-X20"}],"explanation":["「잎에 물을 저장」을 찾아요.","두 가지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["선인장 — 굵은 줄기에 물을 저장함 · 잎이 가시로 변함 · 뿌리가 넓게 뻗음","바오바브나무 — 줄기가 매우 굵어 많은 물을 저장함","용설란 — 두껍고 큰 잎에 물을 저장함 · 잎 끝이 뾰족함","알로에 — 두툼한 잎에 물을 저장함 · 잎 속에 물기가 많음","사는 곳 — 비가 적게 오고 물이 매우 부족한 사막"],"title":"사막 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#7','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C27',2,'ox','auto','선인장의 뿌리는 넓게 뻗어 있어 적은 물도 잘 빨아들여요.',ARRAY['SC3-1-u3-X23']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C27","difficulty":2,"kind":"ox","stem":"선인장의 뿌리는 넓게 뻗어 있어 적은 물도 잘 빨아들여요.","answer":"O","reason_options":[{"t":"비가 조금 와도 넓은 곳의 물을 모을 수 있기 때문에","correct":true},{"t":"선인장은 뿌리가 없어 물을 빨아들이지 않기 때문에","mis":"SC3-1-u3-X23"}],"mis":"SC3-1-u3-X23","explanation":["선인장 줄을 읽어요.","넓게 뻗어요.","그래서 O예요."],"asset":{"type":"passage","lines":["선인장 — 굵은 줄기에 물을 저장함 · 잎이 가시로 변함 · 뿌리가 넓게 뻗음","바오바브나무 — 줄기가 매우 굵어 많은 물을 저장함","용설란 — 두껍고 큰 잎에 물을 저장함 · 잎 끝이 뾰족함","알로에 — 두툼한 잎에 물을 저장함 · 잎 속에 물기가 많음","사는 곳 — 비가 적게 오고 물이 매우 부족한 사막"],"title":"사막 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#8','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C24',2,'mc','auto','선인장의 줄기가 굵은 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X21']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C24","difficulty":2,"kind":"mc","stem":"선인장의 줄기가 굵은 까닭은 무엇인가요?","options":[{"t":"많은 물을 저장하기 위해서","correct":true},{"t":"물 위로 높이 자라기 위해서","mis":"SC3-1-u3-X21"},{"t":"햇빛을 막기 위해서","mis":"SC3-1-u3-X21"},{"t":"물에 둥둥 뜨기 위해서","mis":"SC3-1-u3-X21"}],"explanation":["줄기 속을 떠올려요.","물이 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#9','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C28',2,'mc','auto','사막에 사는 식물의 생김새로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X24']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C28","difficulty":2,"kind":"mc","stem":"사막에 사는 식물의 생김새로 알맞은 것은 무엇인가요?","options":[{"t":"굵은 줄기나 두꺼운 잎에 물을 저장해요","correct":true},{"t":"잎이 넓고 얇아 물을 많이 내보내요","mis":"SC3-1-u3-X24"},{"t":"잎자루에 공기주머니가 있어요","mis":"SC3-1-u3-X24"},{"t":"줄기와 잎이 가늘고 부드러워요","mis":"SC3-1-u3-X24"}],"explanation":["물을 아껴야 해요.","저장해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_basic#10','sci',3,1,'u3','L05','g3_1_sci_u3_L05_basic','lesson_basic','SC3-1-u3-C26',3,'mc','auto','선인장의 잎이 가시가 아니라 넓고 얇았다면 어떻게 될까요?',ARRAY['SC3-1-u3-X22','SC3-1-u3-X24']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C26","difficulty":3,"kind":"mc","stem":"선인장의 잎이 가시가 아니라 넓고 얇았다면 어떻게 될까요?","options":[{"t":"물이 많이 빠져나가 사막에서 살기 어려워요","correct":true},{"t":"물이 더 잘 저장되어요","mis":"SC3-1-u3-X22"},{"t":"물에 더 잘 떠요","mis":"SC3-1-u3-X24"},{"t":"아무 차이도 없어요","mis":"SC3-1-u3-X24"}],"explanation":["넓은 잎은 물이 잘 빠져요.","사막에서는 힘들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#1','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C28',2,'blank','auto','「사막에 사는 식물은 물을 (      ) 물이 빠져나가는 것을 막는 모습이에요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u3-X24']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C28","difficulty":2,"kind":"blank","stem":"「사막에 사는 식물은 물을 (      ) 물이 빠져나가는 것을 막는 모습이에요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"저장하고","correct":true},{"t":"모두 내보내고","mis":"SC3-1-u3-X24"},{"t":"버리고","mis":"SC3-1-u3-X24"},{"t":"잎으로 날려 보내고","mis":"SC3-1-u3-X24"}],"explanation":["물이 귀해요.","모아 둬요.","「저장하고」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#2','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C27',2,'mc','auto','선인장의 뿌리는 어떻게 생겼나요?',ARRAY['SC3-1-u3-X23']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C27","difficulty":2,"kind":"mc","stem":"선인장의 뿌리는 어떻게 생겼나요?","options":[{"t":"넓게 뻗어 있어요","correct":true},{"t":"뿌리가 아예 없어요","mis":"SC3-1-u3-X23"},{"t":"물속에 늘어뜨려요","mis":"SC3-1-u3-X23"},{"t":"잎자루처럼 볼록해요","mis":"SC3-1-u3-X23"}],"explanation":["적은 물도 모아요.","넓어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#3','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C25',3,'error','auto','친구들이 사막 식물 관찰 기록을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u3-X21']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C25","difficulty":3,"kind":"error","stem":"친구들이 사막 식물 관찰 기록을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「알로에는 가는 줄기에 물을 저장해.」","correct":true,"mis_target":"SC3-1-u3-X21"},{"t":"친구 가 — 「선인장은 굵은 줄기에 물을 저장해.」","mis":"SC3-1-u3-X21"},{"t":"친구 나 — 「용설란은 두껍고 큰 잎에 물을 저장해.」","mis":"SC3-1-u3-X21"}],"explanation":["알로에 줄을 읽어요.","잎이에요.","친구 다예요."],"asset":{"type":"passage","lines":["선인장 — 굵은 줄기에 물을 저장함 · 잎이 가시로 변함 · 뿌리가 넓게 뻗음","바오바브나무 — 줄기가 매우 굵어 많은 물을 저장함","용설란 — 두껍고 큰 잎에 물을 저장함 · 잎 끝이 뾰족함","알로에 — 두툼한 잎에 물을 저장함 · 잎 속에 물기가 많음","사는 곳 — 비가 적게 오고 물이 매우 부족한 사막"],"title":"사막 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#4','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C25',3,'mc','auto','채송화는 도톰한 잎에 물을 저장해요. 채송화와 같은 무리로 묶을 수 있는 식물은 무엇인가요?',ARRAY['SC3-1-u3-X21','SC3-1-u3-X20']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C25","difficulty":3,"kind":"mc","stem":"채송화는 도톰한 잎에 물을 저장해요. 채송화와 같은 무리로 묶을 수 있는 식물은 무엇인가요?","options":[{"t":"알로에","correct":true},{"t":"선인장","mis":"SC3-1-u3-X21"},{"t":"바오바브나무","mis":"SC3-1-u3-X21"},{"t":"부레옥잠","mis":"SC3-1-u3-X20"}],"explanation":["잎에 저장해요.","두툼한 잎이에요.","알로에예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#5','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C23',3,'mc','auto','관찰 기록을 보면 사막은 어떤 곳인가요?',ARRAY['SC3-1-u3-X20']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C23","difficulty":3,"kind":"mc","stem":"관찰 기록을 보면 사막은 어떤 곳인가요?","options":[{"t":"비가 적게 오고 물이 매우 부족한 곳","correct":true},{"t":"물이 많아 식물이 물에 떠서 사는 곳","mis":"SC3-1-u3-X20"},{"t":"얼음과 눈으로 덮인 곳","mis":"SC3-1-u3-X20"},{"t":"식물이 하나도 살 수 없는 곳","mis":"SC3-1-u3-X20"}],"explanation":["마지막 줄을 읽어요.","물이 부족해요.","첫 번째예요."],"asset":{"type":"passage","lines":["선인장 — 굵은 줄기에 물을 저장함 · 잎이 가시로 변함 · 뿌리가 넓게 뻗음","바오바브나무 — 줄기가 매우 굵어 많은 물을 저장함","용설란 — 두껍고 큰 잎에 물을 저장함 · 잎 끝이 뾰족함","알로에 — 두툼한 잎에 물을 저장함 · 잎 속에 물기가 많음","사는 곳 — 비가 적게 오고 물이 매우 부족한 사막"],"title":"사막 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#6','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C28',3,'ox','auto','사는 곳이 다르면 식물의 생김새도 그곳에 알맞게 달라요.',ARRAY['SC3-1-u3-X24']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C28","difficulty":3,"kind":"ox","stem":"사는 곳이 다르면 식물의 생김새도 그곳에 알맞게 달라요.","answer":"O","reason_options":[{"t":"물에 사는 부레옥잠은 공기주머니가, 사막에 사는 선인장은 물을 저장하는 굵은 줄기가 있기 때문에","correct":true},{"t":"사는 곳과 식물의 생김새는 관계가 없기 때문에","mis":"SC3-1-u3-X24"}],"mis":"SC3-1-u3-X24","explanation":["부레옥잠과 선인장을 견줘요.","생김새가 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#7','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C24',3,'mc','auto','바오바브나무가 비가 오지 않는 마른 철에도 잘 견디는 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X24','SC3-1-u3-X23','SC3-1-u3-X20']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C24","difficulty":3,"kind":"mc","stem":"바오바브나무가 비가 오지 않는 마른 철에도 잘 견디는 까닭은 무엇인가요?","options":[{"t":"매우 굵은 줄기에 많은 물을 저장해 두어서","correct":true},{"t":"잎이 넓고 얇아서","mis":"SC3-1-u3-X24"},{"t":"뿌리가 없어서","mis":"SC3-1-u3-X23"},{"t":"물 위에 떠서 살아서","mis":"SC3-1-u3-X20"}],"explanation":["바오바브나무 줄을 읽어요.","줄기가 굵어요.","첫 번째예요."],"asset":{"type":"passage","lines":["선인장 — 굵은 줄기에 물을 저장함 · 잎이 가시로 변함 · 뿌리가 넓게 뻗음","바오바브나무 — 줄기가 매우 굵어 많은 물을 저장함","용설란 — 두껍고 큰 잎에 물을 저장함 · 잎 끝이 뾰족함","알로에 — 두툼한 잎에 물을 저장함 · 잎 속에 물기가 많음","사는 곳 — 비가 적게 오고 물이 매우 부족한 사막"],"title":"사막 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#8','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C26',4,'mc','auto','친구가 「선인장의 가시는 그냥 뾰족한 장식이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X22','SC3-1-u3-X21']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C26","difficulty":4,"kind":"mc","stem":"친구가 「선인장의 가시는 그냥 뾰족한 장식이야.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「가시는 잎이 변한 거라 넓은 잎보다 물이 덜 빠져나가.」","correct":true},{"t":"「맞아, 아무 쓸모 없는 장식이야.」","mis":"SC3-1-u3-X22"},{"t":"「가시 속에 물을 가득 저장해.」","mis":"SC3-1-u3-X21"},{"t":"「가시는 빨리 자라려고 생겼어.」","mis":"SC3-1-u3-X22"}],"explanation":["가시는 무엇이 변했나요?","잎이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#9','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C23',4,'mc','auto','친구가 「사막에는 물이 없으니 식물이 하나도 못 살아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X20','SC3-1-u3-X24','SC3-1-u3-X23']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C23","difficulty":4,"kind":"mc","stem":"친구가 「사막에는 물이 없으니 식물이 하나도 못 살아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「선인장처럼 물을 저장하고 지키는 생김새를 가진 식물은 사막에서도 살아.」","correct":true},{"t":"「맞아, 사막에는 식물이 없어.」","mis":"SC3-1-u3-X20"},{"t":"「사막 식물은 잎이 넓고 얇아.」","mis":"SC3-1-u3-X24"},{"t":"「사막 식물은 뿌리가 없어.」","mis":"SC3-1-u3-X23"}],"explanation":["선인장을 떠올려요.","사막에 살아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L05_challenge#10','sci',3,1,'u3','L05','g3_1_sci_u3_L05_challenge','lesson_challenge','SC3-1-u3-C28',4,'essay','teacher','선인장의 줄기, 잎, 뿌리 가운데 두 가지를 골라 그 생김새가 사막에서 살기에 어떻게 알맞은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u3-C28","difficulty":4,"kind":"essay","stem":"선인장의 줄기, 잎, 뿌리 가운데 두 가지를 골라 그 생김새가 사막에서 살기에 어떻게 알맞은지 쓰세요.","answer_guide":{"answer":"예: 선인장은 줄기가 굵어 물을 많이 저장해 둘 수 있다. 잎이 가시로 변해 물이 빠져나가는 것을 막는다. 그래서 물이 부족한 사막에서도 살 수 있다.","scoring_points":["두 부분의 생김새를 바르게 썼는가","생김새를 물 저장·물 지키기와 이어 썼는가","사막 환경과 관련지어 썼는가"]},"explanation":["선인장 줄을 읽어요.","두 부분을 골라요.","사막과 이어 써요."],"asset":{"type":"passage","lines":["선인장 — 굵은 줄기에 물을 저장함 · 잎이 가시로 변함 · 뿌리가 넓게 뻗음","바오바브나무 — 줄기가 매우 굵어 많은 물을 저장함","용설란 — 두껍고 큰 잎에 물을 저장함 · 잎 끝이 뾰족함","알로에 — 두툼한 잎에 물을 저장함 · 잎 속에 물기가 많음","사는 곳 — 비가 적게 오고 물이 매우 부족한 사막"],"title":"사막 식물 관찰 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#1','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C30',1,'mc','auto','도꼬마리 열매를 본떠 만든 물건은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C30","difficulty":1,"kind":"mc","stem":"도꼬마리 열매를 본떠 만든 물건은 무엇인가요?","options":[{"t":"붙였다 떼는 찍찍이","correct":true},{"t":"투명한 유리컵","mis":"SC3-1-u3-X26"},{"t":"비에 젖지 않는 방수 옷","mis":"SC3-1-u3-X26"},{"t":"천천히 내려오는 낙하산","mis":"SC3-1-u3-X26"}],"explanation":["열매가 옷에 붙어요.","갈고리예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#2','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C31',1,'mc','auto','단풍나무 씨앗을 본떠 만든 것은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C31","difficulty":1,"kind":"mc","stem":"단풍나무 씨앗을 본떠 만든 것은 무엇인가요?","options":[{"t":"빙글빙글 도는 헬리콥터 날개","correct":true},{"t":"두꺼운 겨울 옷","mis":"SC3-1-u3-X26"},{"t":"붙였다 떼는 찍찍이","mis":"SC3-1-u3-X26"},{"t":"단단한 벽돌","mis":"SC3-1-u3-X26"}],"explanation":["씨앗에 날개가 있어요.","빙글빙글 돌아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#3','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C29',1,'ox','auto','사람들은 식물의 특징을 본떠 생활에 도움이 되는 물건을 만들어요.',ARRAY['SC3-1-u3-X25']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C29","difficulty":1,"kind":"ox","stem":"사람들은 식물의 특징을 본떠 생활에 도움이 되는 물건을 만들어요.","answer":"O","reason_options":[{"t":"찍찍이, 방수 옷, 낙하산처럼 식물을 본떠 만든 물건이 생활에 쓰이기 때문에","correct":true},{"t":"식물은 우리 생활과 아무 관계가 없기 때문에","mis":"SC3-1-u3-X25"}],"mis":"SC3-1-u3-X25","explanation":["찍찍이를 떠올려요.","식물을 본떴어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#4','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C32',1,'sa','auto','물이 스미지 않아 물방울이 또르르 굴러떨어지는 잎으로, 방수 옷을 만들 때 본뜬 잎은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u3-C32","difficulty":1,"kind":"sa","stem":"물이 스미지 않아 물방울이 또르르 굴러떨어지는 잎으로, 방수 옷을 만들 때 본뜬 잎은 무엇인가요? 두 글자로 쓰세요.","answer":["연잎"],"explanation":["연못에 사는 식물의 잎이에요.","두 글자예요.","「연잎」이에요."],"mis":"SC3-1-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#5','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C33',2,'match','auto','조사 기록을 보고 식물과 본떠 만든 물건을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u3-C33","difficulty":2,"kind":"match","stem":"조사 기록을 보고 식물과 본떠 만든 물건을 알맞게 이으세요.","pairs":[{"l":"도꼬마리 열매","r":"찍찍이"},{"l":"연잎","r":"방수 옷"},{"l":"민들레 씨앗","r":"낙하산"}],"mis":"SC3-1-u3-X26","explanation":["화살표 뒤를 읽어요.","물건이 있어요.","하나씩 이어요."],"asset":{"type":"passage","lines":["도꼬마리 열매 — 갈고리 모양 가시가 털이나 옷에 잘 붙음 → 찍찍이","단풍나무 씨앗 — 날개가 달려 빙글빙글 돌며 떨어짐 → 헬리콥터 날개","연잎 — 물이 스미지 않고 물방울이 또르르 굴러떨어짐 → 방수 옷","민들레 씨앗 — 가벼운 솜털로 바람을 타고 천천히 내려옴 → 낙하산"],"title":"식물을 본뜬 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#6','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C33',2,'mc','auto','민들레 씨앗의 어떤 특징을 본떠 낙하산을 만들었나요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C33","difficulty":2,"kind":"mc","stem":"민들레 씨앗의 어떤 특징을 본떠 낙하산을 만들었나요?","options":[{"t":"가벼운 솜털로 바람을 타고 천천히 내려오는 점","correct":true},{"t":"갈고리가 옷에 잘 붙는 점","mis":"SC3-1-u3-X26"},{"t":"물이 스미지 않는 점","mis":"SC3-1-u3-X26"},{"t":"노란 꽃이 피는 점","mis":"SC3-1-u3-X26"}],"explanation":["민들레 줄을 읽어요.","솜털이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["도꼬마리 열매 — 갈고리 모양 가시가 털이나 옷에 잘 붙음 → 찍찍이","단풍나무 씨앗 — 날개가 달려 빙글빙글 돌며 떨어짐 → 헬리콥터 날개","연잎 — 물이 스미지 않고 물방울이 또르르 굴러떨어짐 → 방수 옷","민들레 씨앗 — 가벼운 솜털로 바람을 타고 천천히 내려옴 → 낙하산"],"title":"식물을 본뜬 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#7','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C34',2,'ox','auto','단풍나무 씨앗과 민들레 씨앗은 하늘을 날거나 천천히 내려오게 하는 물건에 도움을 주었어요.',ARRAY['SC3-1-u3-X27']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C34","difficulty":2,"kind":"ox","stem":"단풍나무 씨앗과 민들레 씨앗은 하늘을 날거나 천천히 내려오게 하는 물건에 도움을 주었어요.","answer":"O","reason_options":[{"t":"헬리콥터 날개와 낙하산은 씨앗이 바람을 타고 날아가는 특징을 본떴기 때문에","correct":true},{"t":"두 씨앗은 물건을 붙이거나 물을 막는 데에만 쓰였기 때문에","mis":"SC3-1-u3-X27"}],"mis":"SC3-1-u3-X27","explanation":["씨앗은 바람을 타요.","날기에 도움을 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#8','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C34',2,'mc','auto','조사 기록에서 찍찍이와 방수 옷은 식물의 어느 부분을 본떴나요?',ARRAY['SC3-1-u3-X27']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C34","difficulty":2,"kind":"mc","stem":"조사 기록에서 찍찍이와 방수 옷은 식물의 어느 부분을 본떴나요?","options":[{"t":"열매와 잎","correct":true},{"t":"씨앗과 씨앗","mis":"SC3-1-u3-X27"},{"t":"뿌리와 줄기","mis":"SC3-1-u3-X27"},{"t":"꽃과 뿌리","mis":"SC3-1-u3-X27"}],"explanation":["도꼬마리와 연잎이에요.","열매와 잎이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["도꼬마리 열매 — 갈고리 모양 가시가 털이나 옷에 잘 붙음 → 찍찍이","단풍나무 씨앗 — 날개가 달려 빙글빙글 돌며 떨어짐 → 헬리콥터 날개","연잎 — 물이 스미지 않고 물방울이 또르르 굴러떨어짐 → 방수 옷","민들레 씨앗 — 가벼운 솜털로 바람을 타고 천천히 내려옴 → 낙하산"],"title":"식물을 본뜬 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#9','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C35',2,'mc','auto','식물을 본떠 물건을 만드는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X28']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C35","difficulty":2,"kind":"mc","stem":"식물을 본떠 물건을 만드는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"자세히 관찰하기 → 도움이 되는 특징 찾기 → 본떠 물건 만들기","correct":true},{"t":"물건 만들기 → 관찰하기 → 특징 찾기","mis":"SC3-1-u3-X28"},{"t":"특징 찾기 → 물건 만들기 → 관찰하기","mis":"SC3-1-u3-X28"},{"t":"관찰하지 않고 아무 식물이나 따라 만들기","mis":"SC3-1-u3-X28"}],"explanation":["먼저 무엇을 할까요?","관찰이 먼저예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_basic#10','sci',3,1,'u3','L06','g3_1_sci_u3_L06_basic','lesson_basic','SC3-1-u3-C35',3,'mc','auto','식물을 본뜨면 좋은 물건을 만들 수 있는 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X25','SC3-1-u3-X28']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C35","difficulty":3,"kind":"mc","stem":"식물을 본뜨면 좋은 물건을 만들 수 있는 까닭은 무엇인가요?","options":[{"t":"식물의 특징에는 환경에 알맞게 살아온 지혜가 담겨 있어서","correct":true},{"t":"식물은 모양이 모두 똑같아서","mis":"SC3-1-u3-X25"},{"t":"식물은 생활과 관계가 없어서","mis":"SC3-1-u3-X25"},{"t":"아무 식물이나 따라 만들면 되어서","mis":"SC3-1-u3-X28"}],"explanation":["식물은 사는 곳에 알맞게 살아요.","그 속에 지혜가 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#1','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C29',2,'blank','auto','「사람들은 식물의 (      ) 본떠 생활에 도움이 되는 물건을 만들어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u3-X25']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C29","difficulty":2,"kind":"blank","stem":"「사람들은 식물의 (      ) 본떠 생활에 도움이 되는 물건을 만들어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"특징을","correct":true},{"t":"이름을","mis":"SC3-1-u3-X25"},{"t":"나이를","mis":"SC3-1-u3-X25"},{"t":"주인을","mis":"SC3-1-u3-X25"}],"explanation":["갈고리·날개·솜털이에요.","특징이에요.","「특징을」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#2','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C32',2,'mc','auto','비에 젖지 않는 옷을 만들려면 무엇을 본뜨면 좋을까요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C32","difficulty":2,"kind":"mc","stem":"비에 젖지 않는 옷을 만들려면 무엇을 본뜨면 좋을까요?","options":[{"t":"물이 스미지 않는 연잎","correct":true},{"t":"가시가 있는 선인장","mis":"SC3-1-u3-X26"},{"t":"솜털이 달린 민들레 씨앗","mis":"SC3-1-u3-X26"},{"t":"갈고리가 있는 도꼬마리 열매","mis":"SC3-1-u3-X26"}],"explanation":["물을 막아야 해요.","또르르 굴러요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#3','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C30',3,'error','auto','친구들이 조사 기록을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C30","difficulty":3,"kind":"error","stem":"친구들이 조사 기록을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「찍찍이는 연잎을 본떠 만들었어.」","correct":true,"mis_target":"SC3-1-u3-X26"},{"t":"친구 가 — 「낙하산은 민들레 씨앗을 본떴어.」","mis":"SC3-1-u3-X26"},{"t":"친구 다 — 「헬리콥터 날개는 단풍나무 씨앗을 본떴어.」","mis":"SC3-1-u3-X26"}],"explanation":["찍찍이 줄을 찾아요.","도꼬마리예요.","친구 나예요."],"asset":{"type":"passage","lines":["도꼬마리 열매 — 갈고리 모양 가시가 털이나 옷에 잘 붙음 → 찍찍이","단풍나무 씨앗 — 날개가 달려 빙글빙글 돌며 떨어짐 → 헬리콥터 날개","연잎 — 물이 스미지 않고 물방울이 또르르 굴러떨어짐 → 방수 옷","민들레 씨앗 — 가벼운 솜털로 바람을 타고 천천히 내려옴 → 낙하산"],"title":"식물을 본뜬 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#4','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C31',3,'mc','auto','조사 기록에서 단풍나무 씨앗이 떨어지는 모습을 바르게 말한 것은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C31","difficulty":3,"kind":"mc","stem":"조사 기록에서 단풍나무 씨앗이 떨어지는 모습을 바르게 말한 것은 무엇인가요?","options":[{"t":"날개가 달려 빙글빙글 돌며 떨어져요","correct":true},{"t":"갈고리로 옷에 붙어요","mis":"SC3-1-u3-X26"},{"t":"물방울을 또르르 굴려요","mis":"SC3-1-u3-X26"},{"t":"곧장 돌처럼 툭 떨어져요","mis":"SC3-1-u3-X26"}],"explanation":["단풍나무 줄을 읽어요.","빙글빙글이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["도꼬마리 열매 — 갈고리 모양 가시가 털이나 옷에 잘 붙음 → 찍찍이","단풍나무 씨앗 — 날개가 달려 빙글빙글 돌며 떨어짐 → 헬리콥터 날개","연잎 — 물이 스미지 않고 물방울이 또르르 굴러떨어짐 → 방수 옷","민들레 씨앗 — 가벼운 솜털로 바람을 타고 천천히 내려옴 → 낙하산"],"title":"식물을 본뜬 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#5','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C34',3,'mc','auto','조사 기록의 네 식물을 쓰임에 따라 나눌 때 「붙이거나 물을 막는 데 도움」 무리는 무엇인가요?',ARRAY['SC3-1-u3-X27']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C34","difficulty":3,"kind":"mc","stem":"조사 기록의 네 식물을 쓰임에 따라 나눌 때 「붙이거나 물을 막는 데 도움」 무리는 무엇인가요?","options":[{"t":"도꼬마리 열매, 연잎","correct":true},{"t":"단풍나무 씨앗, 민들레 씨앗","mis":"SC3-1-u3-X27"},{"t":"도꼬마리 열매, 민들레 씨앗","mis":"SC3-1-u3-X27"},{"t":"연잎, 단풍나무 씨앗","mis":"SC3-1-u3-X27"}],"explanation":["붙이기와 물 막기예요.","찍찍이와 방수 옷이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["도꼬마리 열매 — 갈고리 모양 가시가 털이나 옷에 잘 붙음 → 찍찍이","단풍나무 씨앗 — 날개가 달려 빙글빙글 돌며 떨어짐 → 헬리콥터 날개","연잎 — 물이 스미지 않고 물방울이 또르르 굴러떨어짐 → 방수 옷","민들레 씨앗 — 가벼운 솜털로 바람을 타고 천천히 내려옴 → 낙하산"],"title":"식물을 본뜬 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#6','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C35',3,'ox','auto','식물을 본뜰 때는 아무 식물이나 생김새를 그대로 똑같이 따라 만들면 돼요.',ARRAY['SC3-1-u3-X28']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C35","difficulty":3,"kind":"ox","stem":"식물을 본뜰 때는 아무 식물이나 생김새를 그대로 똑같이 따라 만들면 돼요.","answer":"X","reason_options":[{"t":"먼저 자세히 관찰하고 생활에 도움이 되는 특징을 찾아 본떠야 하기 때문에","correct":true},{"t":"식물은 어떤 것이든 모두 쓸모가 같기 때문에","mis":"SC3-1-u3-X28"}],"mis":"SC3-1-u3-X28","explanation":["차례를 떠올려요.","특징을 찾아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#7','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C30',3,'mc','auto','도꼬마리 열매가 강아지 털에 잘 붙는 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C30","difficulty":3,"kind":"mc","stem":"도꼬마리 열매가 강아지 털에 잘 붙는 까닭은 무엇인가요?","options":[{"t":"열매에 갈고리 모양 가시가 있어서","correct":true},{"t":"열매에 날개가 달려 있어서","mis":"SC3-1-u3-X26"},{"t":"열매에 솜털이 달려 있어서","mis":"SC3-1-u3-X26"},{"t":"열매가 매우 무거워서","mis":"SC3-1-u3-X26"}],"explanation":["도꼬마리 줄을 읽어요.","갈고리예요.","첫 번째예요."],"asset":{"type":"passage","lines":["도꼬마리 열매 — 갈고리 모양 가시가 털이나 옷에 잘 붙음 → 찍찍이","단풍나무 씨앗 — 날개가 달려 빙글빙글 돌며 떨어짐 → 헬리콥터 날개","연잎 — 물이 스미지 않고 물방울이 또르르 굴러떨어짐 → 방수 옷","민들레 씨앗 — 가벼운 솜털로 바람을 타고 천천히 내려옴 → 낙하산"],"title":"식물을 본뜬 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#8','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C29',4,'mc','auto','친구가 「식물은 그냥 보기만 하는 거지, 우리 생활에는 도움이 안 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X25','SC3-1-u3-X26','SC3-1-u3-X28']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C29","difficulty":4,"kind":"mc","stem":"친구가 「식물은 그냥 보기만 하는 거지, 우리 생활에는 도움이 안 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「도꼬마리를 본뜬 찍찍이, 연잎을 본뜬 방수 옷처럼 식물의 특징이 생활을 편리하게 해 줘.」","correct":true},{"t":"「맞아, 식물은 생활과 관계가 없어.」","mis":"SC3-1-u3-X25"},{"t":"「찍찍이는 민들레 씨앗을 본떴어.」","mis":"SC3-1-u3-X26"},{"t":"「식물은 아무거나 따라 만들면 돼.」","mis":"SC3-1-u3-X28"}],"explanation":["찍찍이를 떠올려요.","편리해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#9','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C35',4,'mc','auto','친구가 「연잎을 본뜨려면 연잎 모양 그대로 옷을 만들면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X28','SC3-1-u3-X26','SC3-1-u3-X25']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C35","difficulty":4,"kind":"mc","stem":"친구가 「연잎을 본뜨려면 연잎 모양 그대로 옷을 만들면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「모양을 그대로 따라 하는 게 아니라, 물이 스미지 않는 특징을 찾아 옷감에 본떠야 해.」","correct":true},{"t":"「맞아, 모양만 똑같으면 돼.」","mis":"SC3-1-u3-X28"},{"t":"「방수 옷은 도꼬마리를 본떴어.」","mis":"SC3-1-u3-X26"},{"t":"「연잎은 생활에 쓸모가 없어.」","mis":"SC3-1-u3-X25"}],"explanation":["무엇이 도움이 되나요?","물을 막는 특징이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L06_challenge#10','sci',3,1,'u3','L06','g3_1_sci_u3_L06_challenge','lesson_challenge','SC3-1-u3-C35',4,'essay','teacher','조사 기록에서 식물 하나를 골라 어떤 특징을 본떠 무엇을 만들었는지 쓰고, 그 물건이 생활에 어떤 도움을 주는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u3-C35","difficulty":4,"kind":"essay","stem":"조사 기록에서 식물 하나를 골라 어떤 특징을 본떠 무엇을 만들었는지 쓰고, 그 물건이 생활에 어떤 도움을 주는지 쓰세요.","answer_guide":{"answer":"예: 연잎은 물이 스미지 않고 물방울이 또르르 굴러떨어진다. 이 특징을 본떠 방수 옷을 만들었다. 비가 와도 옷이 젖지 않아 편리하다.","scoring_points":["식물의 특징을 바르게 썼는가","본떠 만든 물건을 바르게 썼는가","생활에 주는 도움을 썼는가"]},"explanation":["조사 기록을 읽어요.","특징 → 물건이에요.","도움도 써요."],"asset":{"type":"passage","lines":["도꼬마리 열매 — 갈고리 모양 가시가 털이나 옷에 잘 붙음 → 찍찍이","단풍나무 씨앗 — 날개가 달려 빙글빙글 돌며 떨어짐 → 헬리콥터 날개","연잎 — 물이 스미지 않고 물방울이 또르르 굴러떨어짐 → 방수 옷","민들레 씨앗 — 가벼운 솜털로 바람을 타고 천천히 내려옴 → 낙하산"],"title":"식물을 본뜬 물건 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#1','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C36',1,'mc','auto','비가 와도 안 젖는 우산을 만들려면 무엇을 본뜨면 좋을까요?',ARRAY['SC3-1-u3-X31','SC3-1-u3-X29']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C36","difficulty":1,"kind":"mc","stem":"비가 와도 안 젖는 우산을 만들려면 무엇을 본뜨면 좋을까요?","options":[{"t":"물방울이 또르르 굴러떨어지는 연잎","correct":true},{"t":"물을 빨아들이는 스펀지","mis":"SC3-1-u3-X31"},{"t":"빙글빙글 도는 단풍나무 씨앗","mis":"SC3-1-u3-X29"},{"t":"잘 붙는 도꼬마리 갈고리","mis":"SC3-1-u3-X29"}],"explanation":["물을 막아야 해요.","또르르 굴러요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#2','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C37',1,'mc','auto','식물을 본떠 발명할 때 가장 먼저 할 일은 무엇인가요?',ARRAY['SC3-1-u3-X30','SC3-1-u3-X32']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C37","difficulty":1,"kind":"mc","stem":"식물을 본떠 발명할 때 가장 먼저 할 일은 무엇인가요?","options":[{"t":"식물을 자세히 관찰하기","correct":true},{"t":"색칠부터 하기","mis":"SC3-1-u3-X30"},{"t":"아무거나 따라 만들기","mis":"SC3-1-u3-X30"},{"t":"친구와 다투기","mis":"SC3-1-u3-X32"}],"explanation":["발명 순서 ①이에요.","자세히 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#3','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C39',1,'ox','auto','친구의 발명 아이디어가 내 생각과 달라도 존중하며 들어요.',ARRAY['SC3-1-u3-X32']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C39","difficulty":1,"kind":"ox","stem":"친구의 발명 아이디어가 내 생각과 달라도 존중하며 들어요.","answer":"O","reason_options":[{"t":"친구 생각을 듣고 좋은 점을 찾으면 더 좋은 생각이 떠오르기 때문에","correct":true},{"t":"내 생각과 다르면 틀린 생각이기 때문에","mis":"SC3-1-u3-X32"}],"mis":"SC3-1-u3-X32","explanation":["생각은 다를 수 있어요.","존중해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#4','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C37',1,'sa','auto','발명 순서 「관찰하기 → 좋은 점 찾기 → ○○ 만들기」에서 ○○에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u3-C37","difficulty":1,"kind":"sa","stem":"발명 순서 「관찰하기 → 좋은 점 찾기 → ○○ 만들기」에서 ○○에 알맞은 말을 쓰세요.","answer":["본떠","본떠서"],"explanation":["좋은 점을 따라 해요.","두 글자예요.","「본떠」예요."],"mis":"SC3-1-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#5','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C36',2,'match','auto','발명 아이디어 카드와 본뜰 식물의 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u3-C36","difficulty":2,"kind":"match","stem":"발명 아이디어 카드와 본뜰 식물의 특징을 알맞게 이으세요.","pairs":[{"l":"카드 1 우산","r":"연잎 표면"},{"l":"카드 2 등산 장갑","r":"도꼬마리 갈고리"},{"l":"카드 3 장난감","r":"단풍나무 씨앗 날개"}],"mis":"SC3-1-u3-X29","explanation":["카드를 읽어요.","쓰임에 맞는 특징이에요.","하나씩 이어요."],"asset":{"type":"passage","lines":["카드 1 — 만들고 싶은 것: 비가 와도 안 젖는 우산","카드 2 — 만들고 싶은 것: 산에서 잘 붙는 등산 장갑","카드 3 — 만들고 싶은 것: 공중에서 빙글빙글 돌며 떨어지는 장난감","카드 4 — 만들고 싶은 것: 높은 곳에서 천천히 내려오는 인형","발명 순서 — ① 관찰하기 ② 좋은 점 찾기 ③ 본떠 만들기"],"title":"발명 아이디어 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#6','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C36',2,'mc','auto','발명 아이디어 카드 4의 인형에 본뜨면 좋은 식물의 특징은 무엇인가요?',ARRAY['SC3-1-u3-X31','SC3-1-u3-X29']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C36","difficulty":2,"kind":"mc","stem":"발명 아이디어 카드 4의 인형에 본뜨면 좋은 식물의 특징은 무엇인가요?","options":[{"t":"바람을 타는 민들레 씨앗 솜털","correct":true},{"t":"무거운 돌 매달기","mis":"SC3-1-u3-X31"},{"t":"물을 막는 연잎 표면","mis":"SC3-1-u3-X29"},{"t":"잘 붙는 도꼬마리 갈고리","mis":"SC3-1-u3-X29"}],"explanation":["천천히 내려와야 해요.","솜털이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["카드 1 — 만들고 싶은 것: 비가 와도 안 젖는 우산","카드 2 — 만들고 싶은 것: 산에서 잘 붙는 등산 장갑","카드 3 — 만들고 싶은 것: 공중에서 빙글빙글 돌며 떨어지는 장난감","카드 4 — 만들고 싶은 것: 높은 곳에서 천천히 내려오는 인형","발명 순서 — ① 관찰하기 ② 좋은 점 찾기 ③ 본떠 만들기"],"title":"발명 아이디어 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#7','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C38',2,'ox','auto','안 젖는 옷을 만들 때 물을 빨아들이는 스펀지를 본뜨면 좋아요.',ARRAY['SC3-1-u3-X31']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C38","difficulty":2,"kind":"ox","stem":"안 젖는 옷을 만들 때 물을 빨아들이는 스펀지를 본뜨면 좋아요.","answer":"X","reason_options":[{"t":"스펀지는 물을 빨아들여 오히려 흠뻑 젖고, 식물의 특징도 아니기 때문에","correct":true},{"t":"스펀지가 물을 많이 빨아들일수록 옷이 덜 젖기 때문에","mis":"SC3-1-u3-X31"}],"mis":"SC3-1-u3-X31","explanation":["스펀지에 물을 부어 봐요.","흠뻑 젖어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#8','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C37',2,'mc','auto','발명 아이디어 카드의 발명 순서를 바르게 늘어놓은 것은 무엇인가요?',ARRAY['SC3-1-u3-X30']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C37","difficulty":2,"kind":"mc","stem":"발명 아이디어 카드의 발명 순서를 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"관찰하기 → 좋은 점 찾기 → 본떠 만들기","correct":true},{"t":"본떠 만들기 → 관찰하기 → 좋은 점 찾기","mis":"SC3-1-u3-X30"},{"t":"좋은 점 찾기 → 본떠 만들기 → 관찰하기","mis":"SC3-1-u3-X30"},{"t":"색칠하기 → 만들기 → 관찰하기","mis":"SC3-1-u3-X30"}],"explanation":["마지막 줄을 읽어요.","① ② ③이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["카드 1 — 만들고 싶은 것: 비가 와도 안 젖는 우산","카드 2 — 만들고 싶은 것: 산에서 잘 붙는 등산 장갑","카드 3 — 만들고 싶은 것: 공중에서 빙글빙글 돌며 떨어지는 장난감","카드 4 — 만들고 싶은 것: 높은 곳에서 천천히 내려오는 인형","발명 순서 — ① 관찰하기 ② 좋은 점 찾기 ③ 본떠 만들기"],"title":"발명 아이디어 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#9','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C39',2,'mc','auto','내 발명 아이디어를 친구와 나누는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X32']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C39","difficulty":2,"kind":"mc","stem":"내 발명 아이디어를 친구와 나누는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"그림과 글로 적어 어떤 식물을 본떴는지 소개해요","correct":true},{"t":"친구 아이디어를 놀려요","mis":"SC3-1-u3-X32"},{"t":"아무 말 없이 숨겨 둬요","mis":"SC3-1-u3-X32"},{"t":"친구 아이디어를 몰래 지워요","mis":"SC3-1-u3-X32"}],"explanation":["나누어요.","소개해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_basic#10','sci',3,1,'u3','L07','g3_1_sci_u3_L07_basic','lesson_basic','SC3-1-u3-C40',3,'mc','auto','도꼬마리 갈고리를 본떠 새로 만들 수 있는 물건으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X29']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C40","difficulty":3,"kind":"mc","stem":"도꼬마리 갈고리를 본떠 새로 만들 수 있는 물건으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"끈 없이 붙였다 떼는 신발 여밈","correct":true},{"t":"물이 스미지 않는 우산","mis":"SC3-1-u3-X29"},{"t":"천천히 내려오는 낙하산","mis":"SC3-1-u3-X29"},{"t":"빙글빙글 도는 바람개비","mis":"SC3-1-u3-X29"}],"explanation":["갈고리는 잘 붙어요.","붙였다 떼요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#1','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C36',2,'blank','auto','「공중에서 빙글빙글 돌며 천천히 떨어지는 장난감을 만들려면 (      ) 본떠요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u3-X29']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C36","difficulty":2,"kind":"blank","stem":"「공중에서 빙글빙글 돌며 천천히 떨어지는 장난감을 만들려면 (      ) 본떠요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"단풍나무 씨앗 날개를","correct":true},{"t":"도꼬마리 갈고리를","mis":"SC3-1-u3-X29"},{"t":"연잎 표면을","mis":"SC3-1-u3-X29"},{"t":"향기로운 장미꽃을","mis":"SC3-1-u3-X29"}],"explanation":["빙글빙글 도는 씨앗이에요.","날개가 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#2','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C38',2,'mc','auto','다음 가운데 발명에 본뜰 식물의 특징이 아닌 것은 무엇인가요?',ARRAY['SC3-1-u3-X31']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C38","difficulty":2,"kind":"mc","stem":"다음 가운데 발명에 본뜰 식물의 특징이 아닌 것은 무엇인가요?","options":[{"t":"매끈한 비닐","correct":true},{"t":"도꼬마리 갈고리","mis":"SC3-1-u3-X31"},{"t":"연잎 표면","mis":"SC3-1-u3-X31"},{"t":"민들레 솜털","mis":"SC3-1-u3-X31"}],"explanation":["식물인지 살펴봐요.","비닐은 식물이 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#3','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C37',3,'error','auto','친구들이 발명을 어떻게 했는지 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u3-X30']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C37","difficulty":3,"kind":"error","stem":"친구들이 발명을 어떻게 했는지 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「관찰은 건너뛰고 색칠부터 했어.」","correct":true,"mis_target":"SC3-1-u3-X30"},{"t":"친구 가 — 「먼저 연잎을 자세히 관찰했어.」","mis":"SC3-1-u3-X30"},{"t":"친구 나 — 「물방울이 굴러떨어지는 좋은 점을 찾았어.」","mis":"SC3-1-u3-X30"}],"explanation":["발명 순서를 떠올려요.","관찰이 먼저예요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#4','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C36',3,'mc','auto','단추 없이 쉽게 붙였다 떼는 가방을 만들고 싶어요. 무엇을 본뜨면 좋을까요?',ARRAY['SC3-1-u3-X31','SC3-1-u3-X29']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C36","difficulty":3,"kind":"mc","stem":"단추 없이 쉽게 붙였다 떼는 가방을 만들고 싶어요. 무엇을 본뜨면 좋을까요?","options":[{"t":"도꼬마리 갈고리","correct":true},{"t":"매끈한 비닐","mis":"SC3-1-u3-X31"},{"t":"빙글빙글 도는 단풍나무 씨앗","mis":"SC3-1-u3-X29"},{"t":"바람을 타는 민들레 솜털","mis":"SC3-1-u3-X29"}],"explanation":["붙여야 해요.","갈고리예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#5','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C40',3,'mc','auto','연잎의 특징을 본떠 새로 만들 수 있는 물건으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X29']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C40","difficulty":3,"kind":"mc","stem":"연잎의 특징을 본떠 새로 만들 수 있는 물건으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"비가 와도 젖지 않는 운동화","correct":true},{"t":"잘 붙는 등산 장갑","mis":"SC3-1-u3-X29"},{"t":"천천히 내려오는 낙하산","mis":"SC3-1-u3-X29"},{"t":"빙글빙글 도는 팽이","mis":"SC3-1-u3-X29"}],"explanation":["연잎은 물을 막아요.","안 젖어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#6','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C39',3,'ox','auto','친구 발명 아이디어를 들으면 좋은 점을 칭찬하고 더 좋게 할 방법을 함께 이야기해요.',ARRAY['SC3-1-u3-X32']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C39","difficulty":3,"kind":"ox","stem":"친구 발명 아이디어를 들으면 좋은 점을 칭찬하고 더 좋게 할 방법을 함께 이야기해요.","answer":"O","reason_options":[{"t":"서로의 생각을 존중하며 나누면 더 좋은 발명 아이디어가 떠오르기 때문에","correct":true},{"t":"친구 생각보다 내 생각이 늘 더 좋기 때문에","mis":"SC3-1-u3-X32"}],"mis":"SC3-1-u3-X32","explanation":["함께 나눠요.","더 좋아져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#7','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C38',3,'mc','auto','친구가 무거운 돌을 매달아 천천히 내려오는 인형을 만들겠다고 해요. 무엇이 문제인가요?',ARRAY['SC3-1-u3-X31','SC3-1-u3-X29']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C38","difficulty":3,"kind":"mc","stem":"친구가 무거운 돌을 매달아 천천히 내려오는 인형을 만들겠다고 해요. 무엇이 문제인가요?","options":[{"t":"돌은 식물의 특징이 아니고, 무거우면 오히려 빨리 떨어져요","correct":true},{"t":"돌을 더 많이 매달면 돼요","mis":"SC3-1-u3-X31"},{"t":"돌은 연잎처럼 물을 막아요","mis":"SC3-1-u3-X29"},{"t":"문제가 하나도 없어요","mis":"SC3-1-u3-X31"}],"explanation":["무거우면 어떻게 떨어지나요?","빨리 떨어져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#8','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C37',4,'mc','auto','친구가 「발명은 생각나는 대로 아무거나 따라 만들면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X30','SC3-1-u3-X31']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C37","difficulty":4,"kind":"mc","stem":"친구가 「발명은 생각나는 대로 아무거나 따라 만들면 돼.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「먼저 식물을 관찰하고 좋은 점을 찾은 뒤에 그 점을 본떠 만들어야 해.」","correct":true},{"t":"「맞아, 아무거나 만들면 돼.」","mis":"SC3-1-u3-X30"},{"t":"「색칠부터 하면 발명이 돼.」","mis":"SC3-1-u3-X30"},{"t":"「식물보다 스펀지를 본뜨는 게 좋아.」","mis":"SC3-1-u3-X31"}],"explanation":["발명 순서를 떠올려요.","관찰이 먼저예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#9','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C39',4,'mc','auto','친구가 「도꼬마리 신발이라니 이상해. 하하.」라며 다른 친구 아이디어를 놀렸어요. 가장 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-1-u3-X32','SC3-1-u3-X30','SC3-1-u3-X29']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C39","difficulty":4,"kind":"mc","stem":"친구가 「도꼬마리 신발이라니 이상해. 하하.」라며 다른 친구 아이디어를 놀렸어요. 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"「잘 붙는 특징을 신발에 쓴 점이 좋아. 끈을 안 묶어도 되겠다!」","correct":true},{"t":"「맞아, 이상한 생각이야.」","mis":"SC3-1-u3-X32"},{"t":"「발명은 관찰하지 않아도 돼.」","mis":"SC3-1-u3-X30"},{"t":"「도꼬마리는 물을 막는 식물이야.」","mis":"SC3-1-u3-X29"}],"explanation":["좋은 점을 찾아요.","칭찬해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L07_challenge#10','sci',3,1,'u3','L07','g3_1_sci_u3_L07_challenge','lesson_challenge','SC3-1-u3-C40',4,'essay','teacher','식물 하나를 골라 그 특징을 본뜬 나만의 발명 아이디어를 쓰세요. 무엇을 관찰했는지, 어떤 좋은 점을 찾았는지, 무엇을 만들지 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u3-C40","difficulty":4,"kind":"essay","stem":"식물 하나를 골라 그 특징을 본뜬 나만의 발명 아이디어를 쓰세요. 무엇을 관찰했는지, 어떤 좋은 점을 찾았는지, 무엇을 만들지 차례대로 쓰세요.","answer_guide":{"answer":"예: 단풍나무 씨앗을 관찰했다. 날개가 있어 빙글빙글 돌며 천천히 떨어지는 좋은 점을 찾았다. 이것을 본떠 높은 곳에서 떨어뜨리면 빙글빙글 돌며 내려오는 종이 장난감을 만들겠다.","scoring_points":["관찰한 식물을 썼는가","식물 특징의 좋은 점을 썼는가","그 특징을 본뜬 물건을 썼는가"]},"explanation":["식물을 골라요.","좋은 점을 찾아요.","차례대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#1','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C42',1,'mc','auto','파리지옥은 벌레를 어떻게 잡나요?',ARRAY['SC3-1-u3-X34','SC3-1-u3-X33']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C42","difficulty":1,"kind":"mc","stem":"파리지옥은 벌레를 어떻게 잡나요?","options":[{"t":"조개처럼 생긴 잎을 탁 닫아 가둬요","correct":true},{"t":"뾰족한 가시로 벌레를 찔러요","mis":"SC3-1-u3-X34"},{"t":"빠르게 날아가 벌레를 잡아요","mis":"SC3-1-u3-X33"},{"t":"뿌리를 뻗어 벌레를 잡아요","mis":"SC3-1-u3-X34"}],"explanation":["조개 모양 잎이에요.","닫혀요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#2','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C43',1,'mc','auto','벌레잡이 식물이 벌레를 잡는 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X35']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C43","difficulty":1,"kind":"mc","stem":"벌레잡이 식물이 벌레를 잡는 까닭은 무엇인가요?","options":[{"t":"양분이 적은 곳에 살아 부족한 양분을 얻으려고","correct":true},{"t":"햇빛이 싫어서","mis":"SC3-1-u3-X35"},{"t":"다른 식물과 싸우려고","mis":"SC3-1-u3-X35"},{"t":"물을 마시지 못해서","mis":"SC3-1-u3-X35"}],"explanation":["사는 땅을 떠올려요.","양분이 적어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#3','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C44',1,'ox','auto','벌레잡이 식물도 다른 식물처럼 햇빛을 받아 살아가요.',ARRAY['SC3-1-u3-X36']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C44","difficulty":1,"kind":"ox","stem":"벌레잡이 식물도 다른 식물처럼 햇빛을 받아 살아가요.","answer":"O","reason_options":[{"t":"벌레는 부족한 양분을 보태 줄 뿐이고 벌레잡이 식물도 햇빛을 받아 살기 때문에","correct":true},{"t":"벌레잡이 식물은 벌레만 먹고 살기 때문에","mis":"SC3-1-u3-X36"}],"mis":"SC3-1-u3-X36","explanation":["식물은 햇빛이 필요해요.","벌레잡이 식물도요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#4','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C42',1,'sa','auto','물속에 살며 작은 주머니로 벌레를 빨아들이는 식물은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u3-C42","difficulty":1,"kind":"sa","stem":"물속에 살며 작은 주머니로 벌레를 빨아들이는 식물은 무엇인가요? 두 글자로 쓰세요.","answer":["통발"],"explanation":["물속 식물이에요.","두 글자예요.","「통발」이에요."],"mis":"SC3-1-u3-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#5','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C42',2,'match','auto','관찰 카드를 보고 식물과 벌레 잡는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u3-C42","difficulty":2,"kind":"match","stem":"관찰 카드를 보고 식물과 벌레 잡는 방법을 알맞게 이으세요.","pairs":[{"l":"끈끈이주걱","r":"끈끈한 액으로 붙잡음"},{"l":"벌레잡이통풀","r":"미끄러운 통에 빠뜨림"},{"l":"파리지옥","r":"잎을 닫아 가둠"}],"mis":"SC3-1-u3-X34","explanation":["카드를 읽어요.","방법이 달라요.","하나씩 이어요."],"asset":{"type":"passage","lines":["파리지옥 — 조개처럼 생긴 잎 두 장 · 벌레가 잎 안의 털을 건드리면 잎이 닫힘","끈끈이주걱 — 잎에 이슬처럼 끈끈한 액이 맺힘 · 벌레가 달라붙음","벌레잡이통풀 — 잎이 길쭉한 통 모양 · 안쪽이 미끄러워 벌레가 빠짐","통발 — 물속에 삶 · 작은 주머니로 작은 벌레를 빨아들임","사는 곳 — 양분이 적은 땅이나 물 · 모두 햇빛을 받아 살아감"],"title":"신기한 식물 관찰 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#6','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C41',2,'mc','auto','벌레를 잡는 식물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X33']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C41","difficulty":2,"kind":"mc","stem":"벌레를 잡는 식물끼리 모은 것은 무엇인가요?","options":[{"t":"파리지옥, 끈끈이주걱","correct":true},{"t":"선인장, 알로에","mis":"SC3-1-u3-X33"},{"t":"부레옥잠, 수련","mis":"SC3-1-u3-X33"},{"t":"민들레, 강아지풀","mis":"SC3-1-u3-X33"}],"explanation":["벌레를 잡는 식물이에요.","두 가지예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#7','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C45',2,'ox','auto','파리지옥이 신기하다고 잎을 자꾸 건드려 닫히게 해도 괜찮아요.',ARRAY['SC3-1-u3-X37']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C45","difficulty":2,"kind":"ox","stem":"파리지옥이 신기하다고 잎을 자꾸 건드려 닫히게 해도 괜찮아요.","answer":"X","reason_options":[{"t":"잎을 건드릴수록 식물이 힘들어하니 가만히 관찰하며 소중히 대해야 하기 때문에","correct":true},{"t":"파리지옥은 잎을 많이 닫을수록 튼튼해지기 때문에","mis":"SC3-1-u3-X37"}],"mis":"SC3-1-u3-X37","explanation":["식물도 힘들어해요.","가만히 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#8','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C43',2,'mc','auto','관찰 카드에서 벌레잡이 식물이 사는 곳은 어떤 곳인가요?',ARRAY['SC3-1-u3-X35','SC3-1-u3-X36']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C43","difficulty":2,"kind":"mc","stem":"관찰 카드에서 벌레잡이 식물이 사는 곳은 어떤 곳인가요?","options":[{"t":"양분이 적은 땅이나 물","correct":true},{"t":"양분이 아주 많은 밭","mis":"SC3-1-u3-X35"},{"t":"햇빛이 하나도 없는 동굴","mis":"SC3-1-u3-X36"},{"t":"물 한 방울 없는 사막 한가운데","mis":"SC3-1-u3-X35"}],"explanation":["마지막 줄을 읽어요.","양분이 적어요.","첫 번째예요."],"asset":{"type":"passage","lines":["파리지옥 — 조개처럼 생긴 잎 두 장 · 벌레가 잎 안의 털을 건드리면 잎이 닫힘","끈끈이주걱 — 잎에 이슬처럼 끈끈한 액이 맺힘 · 벌레가 달라붙음","벌레잡이통풀 — 잎이 길쭉한 통 모양 · 안쪽이 미끄러워 벌레가 빠짐","통발 — 물속에 삶 · 작은 주머니로 작은 벌레를 빨아들임","사는 곳 — 양분이 적은 땅이나 물 · 모두 햇빛을 받아 살아감"],"title":"신기한 식물 관찰 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#9','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C45',2,'mc','auto','벌레잡이 식물을 대하는 행동으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X37','SC3-1-u3-X36']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C45","difficulty":2,"kind":"mc","stem":"벌레잡이 식물을 대하는 행동으로 알맞은 것은 무엇인가요?","options":[{"t":"신기해도 가만히 관찰하고 햇빛과 물을 알맞게 줘요","correct":true},{"t":"잎을 함부로 떼어 내요","mis":"SC3-1-u3-X37"},{"t":"잎을 자꾸 건드려 닫히게 해요","mis":"SC3-1-u3-X37"},{"t":"벌레만 많이 주고 햇빛은 가려요","mis":"SC3-1-u3-X36"}],"explanation":["소중히 대해요.","가만히 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_basic#10','sci',3,1,'u3','L08','g3_1_sci_u3_L08_basic','lesson_basic','SC3-1-u3-C44',3,'mc','auto','벌레잡이 식물에 대해 바르게 말한 것은 무엇인가요?',ARRAY['SC3-1-u3-X33','SC3-1-u3-X36','SC3-1-u3-X34']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C44","difficulty":3,"kind":"mc","stem":"벌레잡이 식물에 대해 바르게 말한 것은 무엇인가요?","options":[{"t":"벌레를 잡는 식물이지만 햇빛을 받아 살아가는 소중한 식물이에요","correct":true},{"t":"벌레를 잡으니 식물이 아니라 동물이에요","mis":"SC3-1-u3-X33"},{"t":"벌레만 먹어야 살 수 있어요","mis":"SC3-1-u3-X36"},{"t":"모두 같은 방법으로 벌레를 잡아요","mis":"SC3-1-u3-X34"}],"explanation":["식물인가요?","햇빛을 받아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#1','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C42',2,'blank','auto','「벌레잡이통풀은 안쪽이 (      ) 통 속에 벌레를 빠뜨려요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u3-X34']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C42","difficulty":2,"kind":"blank","stem":"「벌레잡이통풀은 안쪽이 (      ) 통 속에 벌레를 빠뜨려요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"미끄러운","correct":true},{"t":"끈끈한","mis":"SC3-1-u3-X34"},{"t":"뾰족한","mis":"SC3-1-u3-X34"},{"t":"딱딱하게 닫히는","mis":"SC3-1-u3-X34"}],"explanation":["통 안이 어떤가요?","미끄러워요.","「미끄러운」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#2','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C41',2,'mc','auto','벌레를 잡는 식물에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X33']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C41","difficulty":2,"kind":"mc","stem":"벌레를 잡는 식물에 대해 알맞은 것은 무엇인가요?","options":[{"t":"식물 가운데에는 벌레를 잡아 양분을 얻는 것도 있어요","correct":true},{"t":"벌레를 잡는 식물은 세상에 없어요","mis":"SC3-1-u3-X33"},{"t":"벌레를 잡으면 동물이에요","mis":"SC3-1-u3-X33"},{"t":"모든 식물이 벌레를 잡아요","mis":"SC3-1-u3-X33"}],"explanation":["파리지옥을 떠올려요.","그런 식물도 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#3','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C42',3,'error','auto','친구들이 관찰 카드를 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u3-X34']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C42","difficulty":3,"kind":"error","stem":"친구들이 관찰 카드를 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「끈끈이주걱은 잎을 탁 닫아 벌레를 가둬.」","correct":true,"mis_target":"SC3-1-u3-X34"},{"t":"친구 나 — 「통발은 물속에서 주머니로 벌레를 빨아들여.」","mis":"SC3-1-u3-X34"},{"t":"친구 다 — 「벌레잡이통풀은 미끄러운 통에 벌레를 빠뜨려.」","mis":"SC3-1-u3-X34"}],"explanation":["끈끈이주걱 줄을 읽어요.","끈끈한 액이에요.","친구 가예요."],"asset":{"type":"passage","lines":["파리지옥 — 조개처럼 생긴 잎 두 장 · 벌레가 잎 안의 털을 건드리면 잎이 닫힘","끈끈이주걱 — 잎에 이슬처럼 끈끈한 액이 맺힘 · 벌레가 달라붙음","벌레잡이통풀 — 잎이 길쭉한 통 모양 · 안쪽이 미끄러워 벌레가 빠짐","통발 — 물속에 삶 · 작은 주머니로 작은 벌레를 빨아들임","사는 곳 — 양분이 적은 땅이나 물 · 모두 햇빛을 받아 살아감"],"title":"신기한 식물 관찰 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
