INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#5','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C43',3,'mc','auto','벌레잡이 식물에게 벌레는 어떤 도움을 주나요?',ARRAY['SC3-1-u3-X36','SC3-1-u3-X35']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C43","difficulty":3,"kind":"mc","stem":"벌레잡이 식물에게 벌레는 어떤 도움을 주나요?","options":[{"t":"땅에서 부족한 양분을 보태 줘요","correct":true},{"t":"햇빛을 대신 만들어 줘요","mis":"SC3-1-u3-X36"},{"t":"물을 가득 채워 줘요","mis":"SC3-1-u3-X35"},{"t":"다른 식물을 물리쳐 줘요","mis":"SC3-1-u3-X35"}],"explanation":["양분이 적은 땅이에요.","보태 줘요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#6','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C41',3,'ox','auto','벌레를 잡는다는 까닭으로 벌레잡이 식물을 동물이라고 할 수 있어요.',ARRAY['SC3-1-u3-X33']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C41","difficulty":3,"kind":"ox","stem":"벌레를 잡는다는 까닭으로 벌레잡이 식물을 동물이라고 할 수 있어요.","answer":"X","reason_options":[{"t":"벌레잡이 식물도 다른 식물처럼 햇빛을 받아 살아가는 식물이기 때문에","correct":true},{"t":"벌레를 잡는 것은 모두 동물이기 때문에","mis":"SC3-1-u3-X33"}],"mis":"SC3-1-u3-X33","explanation":["햇빛을 받아 살아요.","식물이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#7','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C45',3,'mc','auto','식물원에서 끈끈이주걱을 만났어요. 가장 알맞은 행동은 무엇인가요?',ARRAY['SC3-1-u3-X37','SC3-1-u3-X33']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C45","difficulty":3,"kind":"mc","stem":"식물원에서 끈끈이주걱을 만났어요. 가장 알맞은 행동은 무엇인가요?","options":[{"t":"손대지 않고 끈끈한 액이 맺힌 모습을 가만히 관찰해요","correct":true},{"t":"잎을 떼어 집에 가져가요","mis":"SC3-1-u3-X37"},{"t":"잎에 손가락을 대 끈끈한지 자꾸 만져 봐요","mis":"SC3-1-u3-X37"},{"t":"벌레잡이 식물은 식물이 아니니 그냥 지나쳐요","mis":"SC3-1-u3-X33"}],"explanation":["소중히 대해요.","눈으로 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#8','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C44',4,'mc','auto','친구가 「벌레잡이 식물은 벌레만 먹으면 햇빛이 없어도 잘 살아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X36','SC3-1-u3-X33','SC3-1-u3-X34']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C44","difficulty":4,"kind":"mc","stem":"친구가 「벌레잡이 식물은 벌레만 먹으면 햇빛이 없어도 잘 살아.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「벌레는 부족한 양분을 보태 줄 뿐이고, 벌레잡이 식물도 햇빛을 받아야 살아.」","correct":true},{"t":"「맞아, 벌레만 있으면 돼.」","mis":"SC3-1-u3-X36"},{"t":"「벌레잡이 식물은 동물이야.」","mis":"SC3-1-u3-X33"},{"t":"「벌레를 잡는 방법은 모두 같아.」","mis":"SC3-1-u3-X34"}],"explanation":["식물은 햇빛이 필요해요.","벌레는 보탤 뿐이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#9','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C42',4,'mc','auto','친구가 「벌레를 잡는 식물은 모두 잎을 닫아서 잡아.」라고 했어요. 관찰 카드를 보고 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X34','SC3-1-u3-X33']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C42","difficulty":4,"kind":"mc","stem":"친구가 「벌레를 잡는 식물은 모두 잎을 닫아서 잡아.」라고 했어요. 관찰 카드를 보고 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「잎을 닫는 건 파리지옥이고, 끈끈이주걱은 끈끈한 액, 통발은 주머니로 잡아. 식물마다 방법이 달라.」","correct":true},{"t":"「맞아, 모두 잎을 닫아.」","mis":"SC3-1-u3-X34"},{"t":"「벌레잡이 식물은 벌레를 안 잡아.」","mis":"SC3-1-u3-X33"},{"t":"「모두 가시로 찔러서 잡아.」","mis":"SC3-1-u3-X34"}],"explanation":["카드 네 줄을 견줘요.","방법이 달라요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["파리지옥 — 조개처럼 생긴 잎 두 장 · 벌레가 잎 안의 털을 건드리면 잎이 닫힘","끈끈이주걱 — 잎에 이슬처럼 끈끈한 액이 맺힘 · 벌레가 달라붙음","벌레잡이통풀 — 잎이 길쭉한 통 모양 · 안쪽이 미끄러워 벌레가 빠짐","통발 — 물속에 삶 · 작은 주머니로 작은 벌레를 빨아들임","사는 곳 — 양분이 적은 땅이나 물 · 모두 햇빛을 받아 살아감"],"title":"신기한 식물 관찰 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_L08_challenge#10','sci',3,1,'u3','L08','g3_1_sci_u3_L08_challenge','lesson_challenge','SC3-1-u3-C43',4,'essay','teacher','관찰 카드의 식물 하나를 골라 벌레를 잡는 방법을 쓰고, 벌레를 잡는 까닭과 이 식물을 대하는 바른 태도를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u3-C43","difficulty":4,"kind":"essay","stem":"관찰 카드의 식물 하나를 골라 벌레를 잡는 방법을 쓰고, 벌레를 잡는 까닭과 이 식물을 대하는 바른 태도를 쓰세요.","answer_guide":{"answer":"예: 파리지옥은 벌레가 잎 안의 털을 건드리면 조개처럼 생긴 잎을 닫아 가둔다. 양분이 적은 땅에 살아 부족한 양분을 얻으려고 벌레를 잡는다. 신기하다고 잎을 자꾸 건드리지 않고 가만히 관찰한다.","scoring_points":["벌레를 잡는 방법을 바르게 썼는가","부족한 양분을 얻으려는 까닭을 썼는가","소중히 대하는 태도를 썼는가"]},"explanation":["카드를 읽어요.","방법과 까닭이에요.","태도도 써요."],"asset":{"type":"passage","lines":["파리지옥 — 조개처럼 생긴 잎 두 장 · 벌레가 잎 안의 털을 건드리면 잎이 닫힘","끈끈이주걱 — 잎에 이슬처럼 끈끈한 액이 맺힘 · 벌레가 달라붙음","벌레잡이통풀 — 잎이 길쭉한 통 모양 · 안쪽이 미끄러워 벌레가 빠짐","통발 — 물속에 삶 · 작은 주머니로 작은 벌레를 빨아들임","사는 곳 — 양분이 적은 땅이나 물 · 모두 햇빛을 받아 살아감"],"title":"신기한 식물 관찰 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#1','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C1',1,'mc','auto','새싹반 일지 ①에서 튤립이 자란 곳은 어디인가요?',ARRAY['SC3-1-u3-X04','SC3-1-u3-X01']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C1","difficulty":1,"kind":"mc","stem":"새싹반 일지 ①에서 튤립이 자란 곳은 어디인가요?","options":[{"t":"화단","correct":true},{"t":"길가","mis":"SC3-1-u3-X04"},{"t":"산꼭대기","mis":"SC3-1-u3-X01"},{"t":"연못 가운데","mis":"SC3-1-u3-X01"}],"explanation":["둘째 줄을 읽어요.","심어 기르는 곳이에요.","화단이에요."],"asset":{"type":"passage","lines":["학교 둘레를 걸으며 식물을 찾았다.","화단에는 튤립이, 길가에는 민들레가 자랐다.","민들레는 노란 꽃이 지고 하얀 솜털 씨앗이 생겼다.","소나무는 잎이 바늘 모양이었다.","친구 가 — 「식물은 다 초록색이니까 생김새가 모두 같아.」"],"title":"새싹반 일지 ① 주변의 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#2','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C11',1,'mc','auto','새싹반 일지 ②에서 「가장자리가 톱니 모양인가?」의 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u3-X10','SC3-1-u3-X07']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C11","difficulty":1,"kind":"mc","stem":"새싹반 일지 ②에서 「가장자리가 톱니 모양인가?」의 「그렇다」 무리는 무엇인가요?","options":[{"t":"단풍나무, 민들레","correct":true},{"t":"은행나무, 강아지풀","mis":"SC3-1-u3-X10"},{"t":"단풍나무, 은행나무","mis":"SC3-1-u3-X07"},{"t":"강아지풀, 민들레","mis":"SC3-1-u3-X07"}],"explanation":["둘째 줄을 읽어요.","두 잎이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["단풍나무, 은행나무, 강아지풀, 민들레 잎을 관찰했다.","「가장자리가 톱니 모양인가?」로 나누니 단풍나무, 민들레가 「그렇다」였다.","「잎이 길쭉한가?」로 나누니 강아지풀만 「그렇다」였다.","친구 나 — 「‘잎이 예쁜가?’도 알맞은 기준이야.」"],"title":"새싹반 일지 ② 잎 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#3','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C13',1,'mc','auto','새싹반 일지 ③에서 줄기가 가늘고 연한 식물은 무엇인가요?',ARRAY['SC3-1-u3-X12']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C13","difficulty":1,"kind":"mc","stem":"새싹반 일지 ③에서 줄기가 가늘고 연한 식물은 무엇인가요?","options":[{"t":"강아지풀","correct":true},{"t":"소나무","mis":"SC3-1-u3-X12"},{"t":"단풍나무","mis":"SC3-1-u3-X12"},{"t":"진달래","mis":"SC3-1-u3-X12"}],"explanation":["첫째 줄을 읽어요.","들에서 보았어요.","강아지풀이에요."],"asset":{"type":"passage","lines":["들에서 민들레, 강아지풀을 보았다. 줄기가 가늘고 연했다.","산에서 소나무, 단풍나무를 보았다. 줄기가 굵고 단단했다.","산길에서 키가 작은 진달래도 보았다. 줄기가 단단했다.","친구 다 — 「진달래는 키가 작으니까 풀이야.」"],"title":"새싹반 일지 ③ 들과 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#4','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C18',1,'mc','auto','새싹반 일지 ④에서 물 위에 떠 있던 식물은 무엇인가요?',ARRAY['SC3-1-u3-X16','SC3-1-u3-X15']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C18","difficulty":1,"kind":"mc","stem":"새싹반 일지 ④에서 물 위에 떠 있던 식물은 무엇인가요?","options":[{"t":"부레옥잠","correct":true},{"t":"검정말","mis":"SC3-1-u3-X16"},{"t":"부들","mis":"SC3-1-u3-X16"},{"t":"소나무","mis":"SC3-1-u3-X15"}],"explanation":["첫째 줄을 읽어요.","떠 있었어요.","부레옥잠이에요."],"asset":{"type":"passage","lines":["연못에 부레옥잠이 떠 있었다. 잎자루가 볼록했다.","검정말은 물속에 잠겨 물결에 따라 흔들렸다.","수련 잎은 물 위에 떠 있고 뿌리는 물속 땅에 있었다.","부들은 물가에 곧게 솟아 있었다.","친구 가 — 「물에 사는 식물은 모두 물 위에 떠서 살아.」"],"title":"새싹반 일지 ④ 연못"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#5','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C24',1,'mc','auto','새싹반 일지 ⑤에서 줄기가 굵은 식물은 무엇인가요?',ARRAY['SC3-1-u3-X21','SC3-1-u3-X20']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C24","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑤에서 줄기가 굵은 식물은 무엇인가요?","options":[{"t":"선인장","correct":true},{"t":"용설란","mis":"SC3-1-u3-X21"},{"t":"알로에","mis":"SC3-1-u3-X21"},{"t":"부레옥잠","mis":"SC3-1-u3-X20"}],"explanation":["둘째 줄을 읽어요.","줄기가 굵어요.","선인장이에요."],"asset":{"type":"passage","lines":["식물원 사막 방에서 선인장, 용설란, 알로에를 보았다.","선인장은 줄기가 굵고 잎이 가시로 되어 있었다.","용설란과 알로에는 잎이 두툼했다.","친구 나 — 「선인장의 가시는 그냥 멋으로 달린 장식이야.」"],"title":"새싹반 일지 ⑤ 사막 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#6','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C30',1,'mc','auto','새싹반 일지 ⑥의 도꼬마리 열매를 본떠 만든 물건은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C30","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑥의 도꼬마리 열매를 본떠 만든 물건은 무엇인가요?","options":[{"t":"찍찍이","correct":true},{"t":"방수 옷","mis":"SC3-1-u3-X26"},{"t":"헬리콥터 날개","mis":"SC3-1-u3-X26"},{"t":"낙하산","mis":"SC3-1-u3-X26"}],"explanation":["옷에 붙었어요.","붙였다 떼요.","찍찍이예요."],"asset":{"type":"passage","lines":["옷에 붙은 도꼬마리 열매를 보았다. 갈고리 모양 가시가 있었다.","연잎에 물을 떨어뜨리니 물방울이 또르르 굴러떨어졌다.","단풍나무 씨앗을 떨어뜨리니 빙글빙글 돌며 내려왔다.","친구 다 — 「식물은 우리 생활에 아무 도움이 안 돼.」"],"title":"새싹반 일지 ⑥ 식물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#7','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C36',1,'mc','auto','새싹반 일지 ⑦에서 천천히 내려오는 인형은 무엇을 본떴나요?',ARRAY['SC3-1-u3-X29','SC3-1-u3-X31']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C36","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑦에서 천천히 내려오는 인형은 무엇을 본떴나요?","options":[{"t":"민들레 솜털","correct":true},{"t":"도꼬마리 갈고리","mis":"SC3-1-u3-X29"},{"t":"연잎 표면","mis":"SC3-1-u3-X29"},{"t":"스펀지","mis":"SC3-1-u3-X31"}],"explanation":["모둠 1을 읽어요.","솜털이에요.","민들레 솜털이에요."],"asset":{"type":"passage","lines":["모둠별로 식물을 본뜬 발명 아이디어를 냈다.","모둠 1 — 민들레 솜털을 본떠 천천히 내려오는 인형","모둠 2 — 도꼬마리 갈고리를 본떠 끈 없는 신발","모둠 3 — 물을 빨아들이는 스펀지로 안 젖는 우비","친구 가 — 「모둠 2 아이디어는 이상해. 하하.」"],"title":"새싹반 일지 ⑦ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#8','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C42',1,'mc','auto','새싹반 일지 ⑧에서 잎을 닫아 벌레를 잡은 식물은 무엇인가요?',ARRAY['SC3-1-u3-X34','SC3-1-u3-X33']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C42","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑧에서 잎을 닫아 벌레를 잡은 식물은 무엇인가요?","options":[{"t":"파리지옥","correct":true},{"t":"끈끈이주걱","mis":"SC3-1-u3-X34"},{"t":"벌레잡이통풀","mis":"SC3-1-u3-X34"},{"t":"선인장","mis":"SC3-1-u3-X33"}],"explanation":["둘째 줄을 읽어요.","잎을 닫았어요.","파리지옥이에요."],"asset":{"type":"passage","lines":["식물원에서 파리지옥, 끈끈이주걱, 벌레잡이통풀을 보았다.","파리지옥은 잎을 닫아, 끈끈이주걱은 끈끈한 액으로 벌레를 잡았다.","벌레잡이통풀은 미끄러운 통 속에 벌레를 빠뜨렸다.","이 식물들은 양분이 적은 땅에서 자란다고 한다.","친구 나 — 「벌레잡이 식물은 벌레만 먹고 사니 햇빛은 필요 없어.」"],"title":"새싹반 일지 ⑧ 신기한 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#9','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C4',2,'mc','auto','다음 가운데 사람이 화단에 심어 기르는 식물로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X04']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C4","difficulty":2,"kind":"mc","stem":"다음 가운데 사람이 화단에 심어 기르는 식물로 가장 알맞은 것은 무엇인가요?","options":[{"t":"봉숭아","correct":true},{"t":"길가의 강아지풀","mis":"SC3-1-u3-X04"},{"t":"풀밭의 토끼풀","mis":"SC3-1-u3-X04"},{"t":"길가의 민들레","mis":"SC3-1-u3-X04"}],"explanation":["화단에 핀 꽃이에요.","심어 길러요.","봉숭아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
