INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#16','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C42',2,'mc','auto','통발은 어디에서 벌레를 잡나요?',ARRAY['SC3-1-u3-X34']::text[],false,'{"seq":16,"concept":"SC3-1-u3-C42","difficulty":2,"kind":"mc","stem":"통발은 어디에서 벌레를 잡나요?","options":[{"t":"물속","correct":true},{"t":"사막","mis":"SC3-1-u3-X34"},{"t":"나무 꼭대기","mis":"SC3-1-u3-X34"},{"t":"땅속 깊은 곳","mis":"SC3-1-u3-X34"}],"explanation":["주머니로 빨아들여요.","물속에 살아요.","물속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#17','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C10',3,'mc','auto','다음 가운데 잎을 분류하는 기준으로 알맞지 않은 것은 무엇인가요?',ARRAY['SC3-1-u3-X09']::text[],false,'{"seq":17,"concept":"SC3-1-u3-C10","difficulty":3,"kind":"mc","stem":"다음 가운데 잎을 분류하는 기준으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"잎의 색이 보기 좋은가?","correct":true},{"t":"잎이 갈라져 있는가?","mis":"SC3-1-u3-X09"},{"t":"잎맥이 나란히 뻗어 있는가?","mis":"SC3-1-u3-X09"},{"t":"잎이 길쭉한가?","mis":"SC3-1-u3-X09"}],"explanation":["사람마다 다를 기준을 찾아요.","보기 좋음은 느낌이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#18','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C16',3,'mc','auto','풀과 나무를 줄기로 나눌 때, 나무 무리에 들어갈 것끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X13','SC3-1-u3-X12']::text[],false,'{"seq":18,"concept":"SC3-1-u3-C16","difficulty":3,"kind":"mc","stem":"풀과 나무를 줄기로 나눌 때, 나무 무리에 들어갈 것끼리 모은 것은 무엇인가요?","options":[{"t":"밤나무, 진달래","correct":true},{"t":"밤나무, 강아지풀","mis":"SC3-1-u3-X13"},{"t":"토끼풀, 진달래","mis":"SC3-1-u3-X13"},{"t":"민들레, 토끼풀","mis":"SC3-1-u3-X12"}],"explanation":["줄기가 단단한 것이에요.","진달래도 나무예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#19','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C28',3,'mc','auto','사막과 연못에 사는 식물의 생김새를 바르게 견준 것은 무엇인가요?',ARRAY['SC3-1-u3-X24']::text[],false,'{"seq":19,"concept":"SC3-1-u3-C28","difficulty":3,"kind":"mc","stem":"사막과 연못에 사는 식물의 생김새를 바르게 견준 것은 무엇인가요?","options":[{"t":"사막 식물은 물을 저장하고, 연못 식물은 물에 뜨거나 물살에 휘어지기 알맞아요","correct":true},{"t":"둘 다 물을 저장하는 굵은 줄기가 있어요","mis":"SC3-1-u3-X24"},{"t":"둘 다 잎이 넓고 얇아요","mis":"SC3-1-u3-X24"},{"t":"사는 곳이 달라도 생김새는 모두 같아요","mis":"SC3-1-u3-X24"}],"explanation":["사는 곳을 견줘요.","알맞게 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#20','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C34',3,'mc','auto','단풍나무 씨앗과 민들레 씨앗을 본뜬 물건의 공통점은 무엇인가요?',ARRAY['SC3-1-u3-X27']::text[],false,'{"seq":20,"concept":"SC3-1-u3-C34","difficulty":3,"kind":"mc","stem":"단풍나무 씨앗과 민들레 씨앗을 본뜬 물건의 공통점은 무엇인가요?","options":[{"t":"하늘에서 날거나 천천히 내려오는 데 도움을 줘요","correct":true},{"t":"물건을 붙였다 떼는 데 도움을 줘요","mis":"SC3-1-u3-X27"},{"t":"비에 젖지 않게 해 줘요","mis":"SC3-1-u3-X27"},{"t":"둘 다 잎을 본떴어요","mis":"SC3-1-u3-X27"}],"explanation":["헬리콥터 날개와 낙하산이에요.","하늘이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#21','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C36',3,'mc','auto','높은 곳에서 떨어뜨려도 천천히 내려오는 종이 인형을 만들려 해요. 가장 알맞은 아이디어는 무엇인가요?',ARRAY['SC3-1-u3-X31','SC3-1-u3-X29']::text[],false,'{"seq":21,"concept":"SC3-1-u3-C36","difficulty":3,"kind":"mc","stem":"높은 곳에서 떨어뜨려도 천천히 내려오는 종이 인형을 만들려 해요. 가장 알맞은 아이디어는 무엇인가요?","options":[{"t":"민들레 솜털처럼 가볍고 넓게 펼친 털을 달아요","correct":true},{"t":"무거운 돌을 매달아요","mis":"SC3-1-u3-X31"},{"t":"연잎처럼 물을 막는 겉면을 붙여요","mis":"SC3-1-u3-X29"},{"t":"도꼬마리처럼 갈고리를 달아요","mis":"SC3-1-u3-X29"}],"explanation":["천천히 내려와야 해요.","솜털이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#22','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C42',3,'mc','auto','파리지옥 잎이 닫히는 때는 언제인가요?',ARRAY['SC3-1-u3-X34']::text[],false,'{"seq":22,"concept":"SC3-1-u3-C42","difficulty":3,"kind":"mc","stem":"파리지옥 잎이 닫히는 때는 언제인가요?","options":[{"t":"벌레가 잎 안의 털을 건드렸을 때","correct":true},{"t":"햇빛이 비칠 때마다","mis":"SC3-1-u3-X34"},{"t":"비가 올 때만","mis":"SC3-1-u3-X34"},{"t":"사람이 박수를 칠 때","mis":"SC3-1-u3-X34"}],"explanation":["잎 안에 털이 있어요.","벌레가 건드려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#23','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C2',4,'mc','auto','새싹반 일지 ①의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X02','SC3-1-u3-X01','SC3-1-u3-X03']::text[],false,'{"seq":23,"concept":"SC3-1-u3-C2","difficulty":4,"kind":"mc","stem":"새싹반 일지 ①의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「민들레는 노란 꽃과 솜털 씨앗이, 소나무는 바늘 모양 잎이 있듯이 식물마다 생김새가 달라.」","correct":true},{"t":"「맞아, 식물은 생김새가 모두 같아.」","mis":"SC3-1-u3-X02"},{"t":"「식물은 산에만 살아.」","mis":"SC3-1-u3-X01"},{"t":"「민들레는 잎이 바늘 모양이야.」","mis":"SC3-1-u3-X03"}],"explanation":["민들레와 소나무를 견줘요.","달라요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["학교 둘레를 걸으며 식물을 찾았다.","화단에는 튤립이, 길가에는 민들레가 자랐다.","민들레는 노란 꽃이 지고 하얀 솜털 씨앗이 생겼다.","소나무는 잎이 바늘 모양이었다.","친구 가 — 「식물은 다 초록색이니까 생김새가 모두 같아.」"],"title":"새싹반 일지 ① 주변의 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#24','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C26',4,'mc','auto','새싹반 일지 ⑤의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X22','SC3-1-u3-X21','SC3-1-u3-X24']::text[],false,'{"seq":24,"concept":"SC3-1-u3-C26","difficulty":4,"kind":"mc","stem":"새싹반 일지 ⑤의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「가시는 잎이 변한 거야. 넓은 잎보다 물이 덜 빠져나가 사막에서 물을 지켜 줘.」","correct":true},{"t":"「맞아, 그냥 멋으로 달렸어.」","mis":"SC3-1-u3-X22"},{"t":"「가시 속에 물을 저장해.」","mis":"SC3-1-u3-X21"},{"t":"「사막 식물은 잎이 넓고 얇아.」","mis":"SC3-1-u3-X24"}],"explanation":["가시는 무엇이 변했나요?","잎이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["식물원 사막 방에서 선인장, 용설란, 알로에를 보았다.","선인장은 줄기가 굵고 잎이 가시로 되어 있었다.","용설란과 알로에는 잎이 두툼했다.","친구 나 — 「선인장의 가시는 그냥 멋으로 달린 장식이야.」"],"title":"새싹반 일지 ⑤ 사막 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_a#25','sci',3,1,'u3','','g3_1_sci_u3_review_a','unit_review','SC3-1-u3-C9',4,'essay','teacher','새싹반 일지 ②를 보고 「가장자리가 톱니 모양인가?」로 나눈 두 무리를 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u3-C9","difficulty":4,"kind":"essay","stem":"새싹반 일지 ②를 보고 「가장자리가 톱니 모양인가?」로 나눈 두 무리를 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 그렇다 = 단풍나무, 민들레 / 그렇지 않다 = 은행나무, 강아지풀. 「잎이 예쁜가?」는 사람마다 생각이 달라 결과가 달라지므로, 누가 나누어도 같은 결과가 나오는 기준을 써야 한다.","scoring_points":["톱니인 무리를 썼는가","톱니가 아닌 무리를 썼는가","사람마다 다른 기준은 알맞지 않다고 고쳤는가"]},"explanation":["일지를 읽어요.","두 무리예요.","고쳐 써요."],"asset":{"type":"passage","lines":["단풍나무, 은행나무, 강아지풀, 민들레 잎을 관찰했다.","「가장자리가 톱니 모양인가?」로 나누니 단풍나무, 민들레가 「그렇다」였다.","「잎이 길쭉한가?」로 나누니 강아지풀만 「그렇다」였다.","친구 나 — 「‘잎이 예쁜가?’도 알맞은 기준이야.」"],"title":"새싹반 일지 ② 잎 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#1','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C3',1,'mc','auto','새싹반 일지 ①에서 노란 꽃이 지고 하얀 솜털 씨앗이 생긴 식물은 무엇인가요?',ARRAY['SC3-1-u3-X03']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C3","difficulty":1,"kind":"mc","stem":"새싹반 일지 ①에서 노란 꽃이 지고 하얀 솜털 씨앗이 생긴 식물은 무엇인가요?","options":[{"t":"민들레","correct":true},{"t":"튤립","mis":"SC3-1-u3-X03"},{"t":"소나무","mis":"SC3-1-u3-X03"},{"t":"강아지풀","mis":"SC3-1-u3-X03"}],"explanation":["셋째 줄을 읽어요.","솜털 씨앗이에요.","민들레예요."],"asset":{"type":"passage","lines":["학교 둘레를 걸으며 식물을 찾았다.","화단에는 튤립이, 길가에는 민들레가 자랐다.","민들레는 노란 꽃이 지고 하얀 솜털 씨앗이 생겼다.","소나무는 잎이 바늘 모양이었다.","친구 가 — 「식물은 다 초록색이니까 생김새가 모두 같아.」"],"title":"새싹반 일지 ① 주변의 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#2','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C10',1,'ox','auto','새싹반 일지 ②의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u3-X09']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C10","difficulty":1,"kind":"ox","stem":"새싹반 일지 ②의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"예쁜지는 사람마다 달라 분류 결과가 달라지기 때문에","correct":true},{"t":"예쁜 잎은 누가 보아도 똑같기 때문에","mis":"SC3-1-u3-X09"}],"mis":"SC3-1-u3-X09","explanation":["누가 해도 같을까요?","아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["단풍나무, 은행나무, 강아지풀, 민들레 잎을 관찰했다.","「가장자리가 톱니 모양인가?」로 나누니 단풍나무, 민들레가 「그렇다」였다.","「잎이 길쭉한가?」로 나누니 강아지풀만 「그렇다」였다.","친구 나 — 「‘잎이 예쁜가?’도 알맞은 기준이야.」"],"title":"새싹반 일지 ② 잎 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#3','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C16',1,'ox','auto','새싹반 일지 ③의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u3-X13']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C16","difficulty":1,"kind":"ox","stem":"새싹반 일지 ③의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"진달래는 키가 작아도 줄기가 단단한 나무이기 때문에","correct":true},{"t":"키가 작은 식물은 모두 풀이기 때문에","mis":"SC3-1-u3-X13"}],"mis":"SC3-1-u3-X13","explanation":["셋째 줄을 읽어요.","줄기가 단단해요.","그래서 X예요."],"asset":{"type":"passage","lines":["들에서 민들레, 강아지풀을 보았다. 줄기가 가늘고 연했다.","산에서 소나무, 단풍나무를 보았다. 줄기가 굵고 단단했다.","산길에서 키가 작은 진달래도 보았다. 줄기가 단단했다.","친구 다 — 「진달래는 키가 작으니까 풀이야.」"],"title":"새싹반 일지 ③ 들과 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#4','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C17',1,'ox','auto','새싹반 일지 ④의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u3-X15']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C17","difficulty":1,"kind":"ox","stem":"새싹반 일지 ④의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"검정말은 물속에 잠겨 살고 부들은 물가에 솟아 살기 때문에","correct":true},{"t":"물에 사는 식물은 모두 물 위에 떠 있기 때문에","mis":"SC3-1-u3-X15"}],"mis":"SC3-1-u3-X15","explanation":["검정말과 부들을 봐요.","떠 있지 않아요.","그래서 X예요."],"asset":{"type":"passage","lines":["연못에 부레옥잠이 떠 있었다. 잎자루가 볼록했다.","검정말은 물속에 잠겨 물결에 따라 흔들렸다.","수련 잎은 물 위에 떠 있고 뿌리는 물속 땅에 있었다.","부들은 물가에 곧게 솟아 있었다.","친구 가 — 「물에 사는 식물은 모두 물 위에 떠서 살아.」"],"title":"새싹반 일지 ④ 연못"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#5','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C26',1,'ox','auto','새싹반 일지 ⑤의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u3-X22']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C26","difficulty":1,"kind":"ox","stem":"새싹반 일지 ⑤의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"선인장의 가시는 잎이 변한 것으로 물이 빠져나가는 것을 막기 때문에","correct":true},{"t":"가시는 아무 쓸모 없이 꾸미려고 달렸기 때문에","mis":"SC3-1-u3-X22"}],"mis":"SC3-1-u3-X22","explanation":["가시는 잎이 변했어요.","물을 지켜요.","그래서 X예요."],"asset":{"type":"passage","lines":["식물원 사막 방에서 선인장, 용설란, 알로에를 보았다.","선인장은 줄기가 굵고 잎이 가시로 되어 있었다.","용설란과 알로에는 잎이 두툼했다.","친구 나 — 「선인장의 가시는 그냥 멋으로 달린 장식이야.」"],"title":"새싹반 일지 ⑤ 사막 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#6','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C29',1,'ox','auto','새싹반 일지 ⑥의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u3-X25']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C29","difficulty":1,"kind":"ox","stem":"새싹반 일지 ⑥의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"도꼬마리를 본뜬 찍찍이, 연잎을 본뜬 방수 옷처럼 식물이 생활에 도움을 주기 때문에","correct":true},{"t":"식물은 생활과 관계가 없기 때문에","mis":"SC3-1-u3-X25"}],"mis":"SC3-1-u3-X25","explanation":["찍찍이를 떠올려요.","도움을 줘요.","그래서 X예요."],"asset":{"type":"passage","lines":["옷에 붙은 도꼬마리 열매를 보았다. 갈고리 모양 가시가 있었다.","연잎에 물을 떨어뜨리니 물방울이 또르르 굴러떨어졌다.","단풍나무 씨앗을 떨어뜨리니 빙글빙글 돌며 내려왔다.","친구 다 — 「식물은 우리 생활에 아무 도움이 안 돼.」"],"title":"새싹반 일지 ⑥ 식물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#7','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C39',1,'ox','auto','새싹반 일지 ⑦의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u3-X32']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C39","difficulty":1,"kind":"ox","stem":"새싹반 일지 ⑦의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"친구 아이디어를 놀리지 않고 좋은 점을 찾아 존중해야 하기 때문에","correct":true},{"t":"내 마음에 들지 않으면 놀려도 되기 때문에","mis":"SC3-1-u3-X32"}],"mis":"SC3-1-u3-X32","explanation":["친구 생각을 존중해요.","놀리면 안 돼요.","그래서 X예요."],"asset":{"type":"passage","lines":["모둠별로 식물을 본뜬 발명 아이디어를 냈다.","모둠 1 — 민들레 솜털을 본떠 천천히 내려오는 인형","모둠 2 — 도꼬마리 갈고리를 본떠 끈 없는 신발","모둠 3 — 물을 빨아들이는 스펀지로 안 젖는 우비","친구 가 — 「모둠 2 아이디어는 이상해. 하하.」"],"title":"새싹반 일지 ⑦ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#8','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C44',1,'ox','auto','새싹반 일지 ⑧의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u3-X36']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C44","difficulty":1,"kind":"ox","stem":"새싹반 일지 ⑧의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"벌레잡이 식물도 햇빛을 받아 살아가고 벌레는 양분을 보태 줄 뿐이기 때문에","correct":true},{"t":"벌레잡이 식물은 벌레만 먹고 살기 때문에","mis":"SC3-1-u3-X36"}],"mis":"SC3-1-u3-X36","explanation":["식물은 햇빛이 필요해요.","벌레잡이 식물도요.","그래서 X예요."],"asset":{"type":"passage","lines":["식물원에서 파리지옥, 끈끈이주걱, 벌레잡이통풀을 보았다.","파리지옥은 잎을 닫아, 끈끈이주걱은 끈끈한 액으로 벌레를 잡았다.","벌레잡이통풀은 미끄러운 통 속에 벌레를 빠뜨렸다.","이 식물들은 양분이 적은 땅에서 자란다고 한다.","친구 나 — 「벌레잡이 식물은 벌레만 먹고 사니 햇빛은 필요 없어.」"],"title":"새싹반 일지 ⑧ 신기한 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#9','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C2',2,'mc','auto','토끼풀과 강아지풀의 잎을 바르게 견준 것은 무엇인가요?',ARRAY['SC3-1-u3-X02','SC3-1-u3-X03']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C2","difficulty":2,"kind":"mc","stem":"토끼풀과 강아지풀의 잎을 바르게 견준 것은 무엇인가요?","options":[{"t":"토끼풀은 잎이 세 장처럼 보이고, 강아지풀은 잎이 가늘고 길어요","correct":true},{"t":"둘 다 잎이 바늘 모양이에요","mis":"SC3-1-u3-X02"},{"t":"토끼풀은 잎이 가늘고 길고, 강아지풀은 잎이 세 장처럼 보여요","mis":"SC3-1-u3-X03"},{"t":"둘 다 잎이 넓적한 손바닥 모양이에요","mis":"SC3-1-u3-X02"}],"explanation":["두 풀을 떠올려요.","잎이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
