INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#12','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C18',2,'mc','auto','부레옥잠의 뿌리는 어떻게 되어 있나요?',ARRAY['SC3-1-u3-X19','SC3-1-u3-X16','SC3-1-u3-X17']::text[],false,'{"seq":12,"concept":"SC3-1-u3-C18","difficulty":2,"kind":"mc","stem":"부레옥잠의 뿌리는 어떻게 되어 있나요?","options":[{"t":"물속에 늘어뜨려져 있어요","correct":true},{"t":"뿌리가 아예 없어요","mis":"SC3-1-u3-X19"},{"t":"물속 땅에 깊이 박혀 있어요","mis":"SC3-1-u3-X16"},{"t":"잎자루 속에 숨어 있어요","mis":"SC3-1-u3-X17"}],"explanation":["떠서 사는 식물이에요.","뿌리가 물속에 늘어져요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#13','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C28',2,'mc','auto','부레옥잠과 선인장의 생김새가 다른 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X24','SC3-1-u3-X20']::text[],false,'{"seq":13,"concept":"SC3-1-u3-C28","difficulty":2,"kind":"mc","stem":"부레옥잠과 선인장의 생김새가 다른 까닭은 무엇인가요?","options":[{"t":"사는 곳이 달라 그곳에 알맞은 생김새를 가졌기 때문에","correct":true},{"t":"사는 곳과 생김새는 관계가 없기 때문에","mis":"SC3-1-u3-X24"},{"t":"두 식물 모두 사막에 살기 때문에","mis":"SC3-1-u3-X20"},{"t":"두 식물 모두 물에 떠서 살기 때문에","mis":"SC3-1-u3-X20"}],"explanation":["물과 사막이에요.","사는 곳이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
