INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#17','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C11',3,'mc','auto','은행나무 잎과 단풍나무 잎을 「잎이 갈라져 있는가?」로 나누면 어떻게 되나요?',ARRAY['SC3-1-u3-X07']::text[],false,'{"seq":17,"concept":"SC3-1-u3-C11","difficulty":3,"kind":"mc","stem":"은행나무 잎과 단풍나무 잎을 「잎이 갈라져 있는가?」로 나누면 어떻게 되나요?","options":[{"t":"단풍나무는 「그렇다」, 은행나무는 「그렇지 않다」예요","correct":true},{"t":"둘 다 「그렇다」예요","mis":"SC3-1-u3-X07"},{"t":"둘 다 「그렇지 않다」예요","mis":"SC3-1-u3-X07"},{"t":"은행나무는 「그렇다」, 단풍나무는 「그렇지 않다」예요","mis":"SC3-1-u3-X07"}],"explanation":["단풍나무 잎을 떠올려요.","여러 갈래예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#18','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C17',3,'mc','auto','물에 사는 식물을 사는 모습에 따라 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u3-X16','SC3-1-u3-X15']::text[],false,'{"seq":18,"concept":"SC3-1-u3-C17","difficulty":3,"kind":"mc","stem":"물에 사는 식물을 사는 모습에 따라 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"개구리밥 — 떠서 살아요, 나사말 — 잠겨 살아요","correct":true},{"t":"개구리밥 — 잠겨 살아요, 나사말 — 떠서 살아요","mis":"SC3-1-u3-X16"},{"t":"개구리밥 — 물가에 솟아요, 나사말 — 떠서 살아요","mis":"SC3-1-u3-X16"},{"t":"둘 다 땅에서만 살아요","mis":"SC3-1-u3-X15"}],"explanation":["개구리밥은 작은 잎이 떠요.","나사말은 검정말처럼 잠겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#19','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C26',3,'mc','auto','선인장의 잎이 가시가 아니라 넓고 큰 잎이라면 사막에서 무엇이 어려울까요?',ARRAY['SC3-1-u3-X24','SC3-1-u3-X21','SC3-1-u3-X22']::text[],false,'{"seq":19,"concept":"SC3-1-u3-C26","difficulty":3,"kind":"mc","stem":"선인장의 잎이 가시가 아니라 넓고 큰 잎이라면 사막에서 무엇이 어려울까요?","options":[{"t":"잎으로 물이 많이 빠져나가 물이 모자라요","correct":true},{"t":"물에 너무 잘 떠요","mis":"SC3-1-u3-X24"},{"t":"줄기에 물을 너무 많이 저장해요","mis":"SC3-1-u3-X21"},{"t":"아무 어려움이 없어요","mis":"SC3-1-u3-X22"}],"explanation":["넓은 잎은 물이 빠져요.","물이 모자라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#20','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C30',3,'mc','auto','산에 다녀오니 옷에 열매가 잔뜩 붙어 있었어요. 이런 열매의 특징을 본뜬 물건은 무엇일까요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":20,"concept":"SC3-1-u3-C30","difficulty":3,"kind":"mc","stem":"산에 다녀오니 옷에 열매가 잔뜩 붙어 있었어요. 이런 열매의 특징을 본뜬 물건은 무엇일까요?","options":[{"t":"붙였다 떼는 찍찍이","correct":true},{"t":"빙글빙글 도는 헬리콥터 날개","mis":"SC3-1-u3-X26"},{"t":"비에 젖지 않는 방수 옷","mis":"SC3-1-u3-X26"},{"t":"천천히 내려오는 낙하산","mis":"SC3-1-u3-X26"}],"explanation":["옷에 붙었어요.","갈고리예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#21','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C37',3,'mc','auto','발명 3단계를 바르게 따른 것은 무엇인가요?',ARRAY['SC3-1-u3-X30','SC3-1-u3-X31']::text[],false,'{"seq":21,"concept":"SC3-1-u3-C37","difficulty":3,"kind":"mc","stem":"발명 3단계를 바르게 따른 것은 무엇인가요?","options":[{"t":"연잎 관찰 → 물이 스미지 않는 점 찾기 → 물 안 젖는 신발 만들기","correct":true},{"t":"신발 만들기 → 연잎 관찰 → 좋은 점 찾기","mis":"SC3-1-u3-X30"},{"t":"색칠 → 신발 만들기 → 끝","mis":"SC3-1-u3-X30"},{"t":"스펀지 관찰 → 물 빨아들이는 점 찾기 → 우산 만들기","mis":"SC3-1-u3-X31"}],"explanation":["관찰부터 해요.","좋은 점 → 본뜨기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#22','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C43',3,'mc','auto','벌레잡이 식물과 사는 땅의 관계로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X35','SC3-1-u3-X36']::text[],false,'{"seq":22,"concept":"SC3-1-u3-C43","difficulty":3,"kind":"mc","stem":"벌레잡이 식물과 사는 땅의 관계로 알맞은 것은 무엇인가요?","options":[{"t":"양분이 적은 땅에 살아 벌레로 양분을 보태요","correct":true},{"t":"양분이 많은 땅에서만 살아요","mis":"SC3-1-u3-X35"},{"t":"땅이 싫어 벌레를 잡아요","mis":"SC3-1-u3-X35"},{"t":"땅 없이 벌레만 먹고 살아요","mis":"SC3-1-u3-X36"}],"explanation":["양분이 적어요.","벌레로 보태요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#23','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C9',4,'mc','auto','새싹반 일지 ②의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X09','SC3-1-u3-X10','SC3-1-u3-X08']::text[],false,'{"seq":23,"concept":"SC3-1-u3-C9","difficulty":4,"kind":"mc","stem":"새싹반 일지 ②의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「예쁜지는 사람마다 달라서 ‘가장자리가 톱니 모양인가?’처럼 누가 나누어도 같은 기준을 써야 해.」","correct":true},{"t":"「맞아, 예쁜 잎끼리 나누면 돼.」","mis":"SC3-1-u3-X09"},{"t":"「기준은 한 번 정하면 바꾸면 안 돼.」","mis":"SC3-1-u3-X10"},{"t":"「관찰하지 말고 이름으로 나누자.」","mis":"SC3-1-u3-X08"}],"explanation":["누가 해도 같을까요?","아니에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["단풍나무, 은행나무, 강아지풀, 민들레 잎을 관찰했다.","「가장자리가 톱니 모양인가?」로 나누니 단풍나무, 민들레가 「그렇다」였다.","「잎이 길쭉한가?」로 나누니 강아지풀만 「그렇다」였다.","친구 나 — 「‘잎이 예쁜가?’도 알맞은 기준이야.」"],"title":"새싹반 일지 ② 잎 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#24','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C29',4,'mc','auto','새싹반 일지 ⑥의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X25','SC3-1-u3-X26','SC3-1-u3-X28']::text[],false,'{"seq":24,"concept":"SC3-1-u3-C29","difficulty":4,"kind":"mc","stem":"새싹반 일지 ⑥의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「도꼬마리를 본뜬 찍찍이, 연잎을 본뜬 방수 옷처럼 식물이 생활을 편리하게 해 줘.」","correct":true},{"t":"「맞아, 식물은 생활과 관계없어.」","mis":"SC3-1-u3-X25"},{"t":"「찍찍이는 단풍나무 씨앗을 본떴어.」","mis":"SC3-1-u3-X26"},{"t":"「식물은 그대로 잘라 써야 해.」","mis":"SC3-1-u3-X28"}],"explanation":["일지를 읽어요.","도움이 돼요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["옷에 붙은 도꼬마리 열매를 보았다. 갈고리 모양 가시가 있었다.","연잎에 물을 떨어뜨리니 물방울이 또르르 굴러떨어졌다.","단풍나무 씨앗을 떨어뜨리니 빙글빙글 돌며 내려왔다.","친구 다 — 「식물은 우리 생활에 아무 도움이 안 돼.」"],"title":"새싹반 일지 ⑥ 식물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_b#25','sci',3,1,'u3','','g3_1_sci_u3_review_b','unit_review','SC3-1-u3-C17',4,'essay','teacher','새싹반 일지 ④를 보고 부레옥잠과 검정말의 사는 모습과 생김새를 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u3-C17","difficulty":4,"kind":"essay","stem":"새싹반 일지 ④를 보고 부레옥잠과 검정말의 사는 모습과 생김새를 쓰고, 친구 가의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 부레옥잠은 잎자루가 볼록하고 속에 공기가 있어 물 위에 떠서 산다. 검정말은 줄기와 잎이 가늘고 부드러워 물속에 잠겨 산다. 물에 사는 식물은 떠서, 잠겨서, 물가에 솟아서 사는 등 사는 모습이 여러 가지이다.","scoring_points":["부레옥잠의 사는 모습과 생김새를 썼는가","검정말의 사는 모습과 생김새를 썼는가","사는 모습이 여러 가지라고 친구 가의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","떠서 · 잠겨서예요.","고쳐 써요."],"asset":{"type":"passage","lines":["연못에 부레옥잠이 떠 있었다. 잎자루가 볼록했다.","검정말은 물속에 잠겨 물결에 따라 흔들렸다.","수련 잎은 물 위에 떠 있고 뿌리는 물속 땅에 있었다.","부들은 물가에 곧게 솟아 있었다.","친구 가 — 「물에 사는 식물은 모두 물 위에 떠서 살아.」"],"title":"새싹반 일지 ④ 연못"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#1','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C2',1,'ox','auto','새싹반 일지 ①의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u3-X02']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C2","difficulty":1,"kind":"ox","stem":"새싹반 일지 ①의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"민들레는 노란 꽃이 피고 소나무는 잎이 바늘 모양이듯 식물마다 생김새가 다르기 때문에","correct":true},{"t":"초록색 식물은 생김새가 모두 같기 때문에","mis":"SC3-1-u3-X02"}],"mis":"SC3-1-u3-X02","explanation":["민들레와 소나무를 견줘요.","생김새가 달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["학교 둘레를 걸으며 식물을 찾았다.","화단에는 튤립이, 길가에는 민들레가 자랐다.","민들레는 노란 꽃이 지고 하얀 솜털 씨앗이 생겼다.","소나무는 잎이 바늘 모양이었다.","친구 가 — 「식물은 다 초록색이니까 생김새가 모두 같아.」"],"title":"새싹반 일지 ① 주변의 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#2','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C11',1,'mc','auto','새싹반 일지 ②에서 「잎이 길쭉한가?」의 「그렇다」 무리는 무엇인가요?',ARRAY['SC3-1-u3-X10','SC3-1-u3-X07']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C11","difficulty":1,"kind":"mc","stem":"새싹반 일지 ②에서 「잎이 길쭉한가?」의 「그렇다」 무리는 무엇인가요?","options":[{"t":"강아지풀","correct":true},{"t":"단풍나무","mis":"SC3-1-u3-X10"},{"t":"은행나무","mis":"SC3-1-u3-X07"},{"t":"민들레","mis":"SC3-1-u3-X07"}],"explanation":["셋째 줄을 읽어요.","하나뿐이에요.","강아지풀이에요."],"asset":{"type":"passage","lines":["단풍나무, 은행나무, 강아지풀, 민들레 잎을 관찰했다.","「가장자리가 톱니 모양인가?」로 나누니 단풍나무, 민들레가 「그렇다」였다.","「잎이 길쭉한가?」로 나누니 강아지풀만 「그렇다」였다.","친구 나 — 「‘잎이 예쁜가?’도 알맞은 기준이야.」"],"title":"새싹반 일지 ② 잎 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#3','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C14',1,'mc','auto','새싹반 일지 ③에서 줄기가 굵고 단단한 식물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X12']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C14","difficulty":1,"kind":"mc","stem":"새싹반 일지 ③에서 줄기가 굵고 단단한 식물끼리 모은 것은 무엇인가요?","options":[{"t":"소나무, 단풍나무","correct":true},{"t":"민들레, 강아지풀","mis":"SC3-1-u3-X12"},{"t":"민들레, 소나무","mis":"SC3-1-u3-X12"},{"t":"강아지풀, 단풍나무","mis":"SC3-1-u3-X12"}],"explanation":["둘째 줄을 읽어요.","산에서 보았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["들에서 민들레, 강아지풀을 보았다. 줄기가 가늘고 연했다.","산에서 소나무, 단풍나무를 보았다. 줄기가 굵고 단단했다.","산길에서 키가 작은 진달래도 보았다. 줄기가 단단했다.","친구 다 — 「진달래는 키가 작으니까 풀이야.」"],"title":"새싹반 일지 ③ 들과 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#4','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C20',1,'mc','auto','새싹반 일지 ④에서 물속에 잠겨 물결에 따라 흔들린 식물은 무엇인가요?',ARRAY['SC3-1-u3-X16']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C20","difficulty":1,"kind":"mc","stem":"새싹반 일지 ④에서 물속에 잠겨 물결에 따라 흔들린 식물은 무엇인가요?","options":[{"t":"검정말","correct":true},{"t":"부레옥잠","mis":"SC3-1-u3-X16"},{"t":"수련","mis":"SC3-1-u3-X16"},{"t":"부들","mis":"SC3-1-u3-X16"}],"explanation":["둘째 줄을 읽어요.","잠겨 있었어요.","검정말이에요."],"asset":{"type":"passage","lines":["연못에 부레옥잠이 떠 있었다. 잎자루가 볼록했다.","검정말은 물속에 잠겨 물결에 따라 흔들렸다.","수련 잎은 물 위에 떠 있고 뿌리는 물속 땅에 있었다.","부들은 물가에 곧게 솟아 있었다.","친구 가 — 「물에 사는 식물은 모두 물 위에 떠서 살아.」"],"title":"새싹반 일지 ④ 연못"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#5','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C25',1,'mc','auto','새싹반 일지 ⑤에서 잎이 두툼해 잎에 물을 저장하는 식물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X21','SC3-1-u3-X20']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C25","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑤에서 잎이 두툼해 잎에 물을 저장하는 식물끼리 모은 것은 무엇인가요?","options":[{"t":"용설란, 알로에","correct":true},{"t":"선인장, 용설란","mis":"SC3-1-u3-X21"},{"t":"선인장, 알로에","mis":"SC3-1-u3-X21"},{"t":"부레옥잠, 수련","mis":"SC3-1-u3-X20"}],"explanation":["셋째 줄을 읽어요.","잎이 두툼해요.","첫 번째예요."],"asset":{"type":"passage","lines":["식물원 사막 방에서 선인장, 용설란, 알로에를 보았다.","선인장은 줄기가 굵고 잎이 가시로 되어 있었다.","용설란과 알로에는 잎이 두툼했다.","친구 나 — 「선인장의 가시는 그냥 멋으로 달린 장식이야.」"],"title":"새싹반 일지 ⑤ 사막 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#6','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C32',1,'mc','auto','새싹반 일지 ⑥에서 물방울이 또르르 굴러떨어진 잎을 본떠 만든 물건은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C32","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑥에서 물방울이 또르르 굴러떨어진 잎을 본떠 만든 물건은 무엇인가요?","options":[{"t":"방수 옷","correct":true},{"t":"찍찍이","mis":"SC3-1-u3-X26"},{"t":"낙하산","mis":"SC3-1-u3-X26"},{"t":"헬리콥터 날개","mis":"SC3-1-u3-X26"}],"explanation":["연잎이에요.","물을 막아요.","방수 옷이에요."],"asset":{"type":"passage","lines":["옷에 붙은 도꼬마리 열매를 보았다. 갈고리 모양 가시가 있었다.","연잎에 물을 떨어뜨리니 물방울이 또르르 굴러떨어졌다.","단풍나무 씨앗을 떨어뜨리니 빙글빙글 돌며 내려왔다.","친구 다 — 「식물은 우리 생활에 아무 도움이 안 돼.」"],"title":"새싹반 일지 ⑥ 식물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#7','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C38',1,'mc','auto','새싹반 일지 ⑦에서 식물의 특징을 본뜨지 않은 모둠은 어디인가요?',ARRAY['SC3-1-u3-X31']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C38","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑦에서 식물의 특징을 본뜨지 않은 모둠은 어디인가요?","options":[{"t":"모둠 3","correct":true},{"t":"모둠 1","mis":"SC3-1-u3-X31"},{"t":"모둠 2","mis":"SC3-1-u3-X31"},{"t":"세 모둠 모두 식물을 본떴어요","mis":"SC3-1-u3-X31"}],"explanation":["스펀지는 식물인가요?","아니에요.","모둠 3이에요."],"asset":{"type":"passage","lines":["모둠별로 식물을 본뜬 발명 아이디어를 냈다.","모둠 1 — 민들레 솜털을 본떠 천천히 내려오는 인형","모둠 2 — 도꼬마리 갈고리를 본떠 끈 없는 신발","모둠 3 — 물을 빨아들이는 스펀지로 안 젖는 우비","친구 가 — 「모둠 2 아이디어는 이상해. 하하.」"],"title":"새싹반 일지 ⑦ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#8','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C42',1,'mc','auto','새싹반 일지 ⑧에서 미끄러운 통 속에 벌레를 빠뜨린 식물은 무엇인가요?',ARRAY['SC3-1-u3-X34','SC3-1-u3-X33']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C42","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑧에서 미끄러운 통 속에 벌레를 빠뜨린 식물은 무엇인가요?","options":[{"t":"벌레잡이통풀","correct":true},{"t":"파리지옥","mis":"SC3-1-u3-X34"},{"t":"끈끈이주걱","mis":"SC3-1-u3-X34"},{"t":"부레옥잠","mis":"SC3-1-u3-X33"}],"explanation":["셋째 줄을 읽어요.","통이에요.","벌레잡이통풀이에요."],"asset":{"type":"passage","lines":["식물원에서 파리지옥, 끈끈이주걱, 벌레잡이통풀을 보았다.","파리지옥은 잎을 닫아, 끈끈이주걱은 끈끈한 액으로 벌레를 잡았다.","벌레잡이통풀은 미끄러운 통 속에 벌레를 빠뜨렸다.","이 식물들은 양분이 적은 땅에서 자란다고 한다.","친구 나 — 「벌레잡이 식물은 벌레만 먹고 사니 햇빛은 필요 없어.」"],"title":"새싹반 일지 ⑧ 신기한 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#9','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C5',2,'ox','auto','식물을 관찰할 때는 꺾지 않고 그 자리에서 자세히 살펴봐요.',ARRAY['SC3-1-u3-X05']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C5","difficulty":2,"kind":"ox","stem":"식물을 관찰할 때는 꺾지 않고 그 자리에서 자세히 살펴봐요.","answer":"O","reason_options":[{"t":"식물도 살아 있으니 소중히 대하며 관찰해야 하기 때문에","correct":true},{"t":"관찰은 꺾어서 가져가야만 할 수 있기 때문에","mis":"SC3-1-u3-X05"}],"mis":"SC3-1-u3-X05","explanation":["식물도 살아 있어요.","그 자리에서 봐요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#10','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C7',2,'ox','auto','강아지풀 잎은 잎맥이 나란히 뻗어 있어요.',ARRAY['SC3-1-u3-X07']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C7","difficulty":2,"kind":"ox","stem":"강아지풀 잎은 잎맥이 나란히 뻗어 있어요.","answer":"O","reason_options":[{"t":"자세히 보면 강아지풀 잎맥은 그물처럼 퍼지지 않고 나란히 뻗어 있기 때문에","correct":true},{"t":"강아지풀 잎맥은 그물처럼 퍼져 있기 때문에","mis":"SC3-1-u3-X07"}],"mis":"SC3-1-u3-X07","explanation":["강아지풀 잎을 떠올려요.","줄이 나란해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#11','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C13',2,'ox','auto','풀은 모두 키가 아주 크고 줄기가 굵어요.',ARRAY['SC3-1-u3-X12']::text[],false,'{"seq":11,"concept":"SC3-1-u3-C13","difficulty":2,"kind":"ox","stem":"풀은 모두 키가 아주 크고 줄기가 굵어요.","answer":"X","reason_options":[{"t":"풀은 줄기가 가늘고 연하며 키가 작은 것이 많기 때문에","correct":true},{"t":"풀은 나무보다 줄기가 굵기 때문에","mis":"SC3-1-u3-X12"}],"mis":"SC3-1-u3-X12","explanation":["민들레를 떠올려요.","가늘고 작아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#12','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C21',2,'ox','auto','부들은 물가에서 단단한 줄기를 곧게 세우고 살아요.',ARRAY['SC3-1-u3-X16']::text[],false,'{"seq":12,"concept":"SC3-1-u3-C21","difficulty":2,"kind":"ox","stem":"부들은 물가에서 단단한 줄기를 곧게 세우고 살아요.","answer":"O","reason_options":[{"t":"부들은 물가에 살며 줄기가 단단하고 곧게 솟아 있기 때문에","correct":true},{"t":"부들은 물 위를 떠다니며 살기 때문에","mis":"SC3-1-u3-X16"}],"mis":"SC3-1-u3-X16","explanation":["부들을 떠올려요.","곧게 솟아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#13','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C24',2,'ox','auto','바오바브나무는 매우 굵은 줄기에 많은 물을 저장해요.',ARRAY['SC3-1-u3-X21']::text[],false,'{"seq":13,"concept":"SC3-1-u3-C24","difficulty":2,"kind":"ox","stem":"바오바브나무는 매우 굵은 줄기에 많은 물을 저장해요.","answer":"O","reason_options":[{"t":"비가 적은 곳에 살아 마른 철을 견디려고 줄기에 물을 저장하기 때문에","correct":true},{"t":"바오바브나무는 잎에만 물을 저장하기 때문에","mis":"SC3-1-u3-X21"}],"mis":"SC3-1-u3-X21","explanation":["줄기가 매우 굵어요.","물을 저장해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#14','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C35',2,'ox','auto','식물을 본뜨려면 먼저 식물을 자세히 관찰해 도움이 되는 특징을 찾아야 해요.',ARRAY['SC3-1-u3-X28']::text[],false,'{"seq":14,"concept":"SC3-1-u3-C35","difficulty":2,"kind":"ox","stem":"식물을 본뜨려면 먼저 식물을 자세히 관찰해 도움이 되는 특징을 찾아야 해요.","answer":"O","reason_options":[{"t":"관찰해야 생활에 도움이 되는 특징을 찾아 본뜰 수 있기 때문에","correct":true},{"t":"관찰하지 않고 아무 식물이나 따라 만들어도 되기 때문에","mis":"SC3-1-u3-X28"}],"mis":"SC3-1-u3-X28","explanation":["차례를 떠올려요.","관찰이 먼저예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#15','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C38',2,'ox','auto','발명에 본뜰 특징은 식물에서 찾아요.',ARRAY['SC3-1-u3-X31']::text[],false,'{"seq":15,"concept":"SC3-1-u3-C38","difficulty":2,"kind":"ox","stem":"발명에 본뜰 특징은 식물에서 찾아요.","answer":"O","reason_options":[{"t":"식물의 생김새에 사는 곳에 알맞게 살아온 좋은 점이 담겨 있기 때문에","correct":true},{"t":"스펀지나 비닐 같은 물건도 식물의 특징이기 때문에","mis":"SC3-1-u3-X31"}],"mis":"SC3-1-u3-X31","explanation":["식물을 관찰해요.","좋은 점이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#16','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C42',2,'ox','auto','벌레잡이 식물은 모두 같은 방법으로 벌레를 잡아요.',ARRAY['SC3-1-u3-X34']::text[],false,'{"seq":16,"concept":"SC3-1-u3-C42","difficulty":2,"kind":"ox","stem":"벌레잡이 식물은 모두 같은 방법으로 벌레를 잡아요.","answer":"X","reason_options":[{"t":"잎을 닫거나, 끈끈한 액으로 붙이거나, 통에 빠뜨리거나, 주머니로 빨아들이듯 방법이 다르기 때문에","correct":true},{"t":"벌레잡이 식물은 모두 잎을 닫아서 잡기 때문에","mis":"SC3-1-u3-X34"}],"mis":"SC3-1-u3-X34","explanation":["네 식물을 견줘요.","방법이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#17','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C3',3,'mc','auto','수수께끼예요. 「겨울에도 잎이 푸르고, 잎이 바늘 모양이며, 키가 큰 나무예요.」 어떤 식물일까요?',ARRAY['SC3-1-u3-X03']::text[],false,'{"seq":17,"concept":"SC3-1-u3-C3","difficulty":3,"kind":"mc","stem":"수수께끼예요. 「겨울에도 잎이 푸르고, 잎이 바늘 모양이며, 키가 큰 나무예요.」 어떤 식물일까요?","options":[{"t":"소나무","correct":true},{"t":"단풍나무","mis":"SC3-1-u3-X03"},{"t":"민들레","mis":"SC3-1-u3-X03"},{"t":"튤립","mis":"SC3-1-u3-X03"}],"explanation":["바늘 모양 잎이에요.","겨울에도 푸르러요.","소나무예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#18','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C19',3,'mc','auto','부레옥잠의 잎자루가 납작하고 속에 공기가 없다면 어떻게 될까요?',ARRAY['SC3-1-u3-X17']::text[],false,'{"seq":18,"concept":"SC3-1-u3-C19","difficulty":3,"kind":"mc","stem":"부레옥잠의 잎자루가 납작하고 속에 공기가 없다면 어떻게 될까요?","options":[{"t":"물 위에 잘 뜨지 못해요","correct":true},{"t":"물에 더 잘 떠요","mis":"SC3-1-u3-X17"},{"t":"줄기가 굵어져요","mis":"SC3-1-u3-X17"},{"t":"아무 차이도 없어요","mis":"SC3-1-u3-X17"}],"explanation":["공기가 있어 떠요.","없으면 어려워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#19','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C25',3,'mc','auto','채송화, 알로에, 용설란을 하나로 묶을 수 있는 기준은 무엇인가요?',ARRAY['SC3-1-u3-X21','SC3-1-u3-X20','SC3-1-u3-X22']::text[],false,'{"seq":19,"concept":"SC3-1-u3-C25","difficulty":3,"kind":"mc","stem":"채송화, 알로에, 용설란을 하나로 묶을 수 있는 기준은 무엇인가요?","options":[{"t":"잎에 물을 저장하는가?","correct":true},{"t":"줄기에 물을 저장하는가?","mis":"SC3-1-u3-X21"},{"t":"물에 떠서 사는가?","mis":"SC3-1-u3-X20"},{"t":"잎이 가시로 변했는가?","mis":"SC3-1-u3-X22"}],"explanation":["세 식물의 잎을 떠올려요.","두툼해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#20','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C35',3,'mc','auto','식물의 특징이 좋은 아이디어가 되는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X25','SC3-1-u3-X28']::text[],false,'{"seq":20,"concept":"SC3-1-u3-C35","difficulty":3,"kind":"mc","stem":"식물의 특징이 좋은 아이디어가 되는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"식물은 사는 곳에 알맞게 살아오며 좋은 특징을 가졌기 때문에","correct":true},{"t":"식물은 모두 생김새가 같기 때문에","mis":"SC3-1-u3-X25"},{"t":"식물은 생활과 관계가 없기 때문에","mis":"SC3-1-u3-X25"},{"t":"식물을 그대로 잘라 쓰면 되기 때문에","mis":"SC3-1-u3-X28"}],"explanation":["사는 곳에 알맞아요.","지혜가 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#21','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C39',3,'mc','auto','친구가 발명 아이디어를 소개했어요. 가장 알맞게 들은 것은 무엇인가요?',ARRAY['SC3-1-u3-X32']::text[],false,'{"seq":21,"concept":"SC3-1-u3-C39","difficulty":3,"kind":"mc","stem":"친구가 발명 아이디어를 소개했어요. 가장 알맞게 들은 것은 무엇인가요?","options":[{"t":"끝까지 듣고 좋은 점을 말한 뒤 궁금한 점을 물어요","correct":true},{"t":"중간에 끼어들어 틀렸다고 해요","mis":"SC3-1-u3-X32"},{"t":"웃으며 이상하다고 놀려요","mis":"SC3-1-u3-X32"},{"t":"듣지 않고 내 아이디어만 말해요","mis":"SC3-1-u3-X32"}],"explanation":["존중해요.","끝까지 들어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#22','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C41',3,'mc','auto','끈끈이주걱이 다른 많은 식물과 다른 점은 무엇인가요?',ARRAY['SC3-1-u3-X36','SC3-1-u3-X33','SC3-1-u3-X34']::text[],false,'{"seq":22,"concept":"SC3-1-u3-C41","difficulty":3,"kind":"mc","stem":"끈끈이주걱이 다른 많은 식물과 다른 점은 무엇인가요?","options":[{"t":"잎의 끈끈한 액으로 벌레를 붙잡아 양분을 얻어요","correct":true},{"t":"햇빛 없이도 살아요","mis":"SC3-1-u3-X36"},{"t":"식물이 아니라 동물이에요","mis":"SC3-1-u3-X33"},{"t":"잎을 닫아 벌레를 가둬요","mis":"SC3-1-u3-X34"}],"explanation":["끈끈한 액이에요.","벌레를 잡아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#23','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C16',4,'mc','auto','새싹반 일지 ③의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X13','SC3-1-u3-X14','SC3-1-u3-X11']::text[],false,'{"seq":23,"concept":"SC3-1-u3-C16","difficulty":4,"kind":"mc","stem":"새싹반 일지 ③의 친구 다의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「진달래는 키가 작아도 줄기가 단단해서 나무야. 키가 아니라 줄기를 봐야 해.」","correct":true},{"t":"「맞아, 키가 작으면 풀이야.」","mis":"SC3-1-u3-X13"},{"t":"「진달래는 뿌리가 없어.」","mis":"SC3-1-u3-X14"},{"t":"「산에는 풀이 살지 않아.」","mis":"SC3-1-u3-X11"}],"explanation":["셋째 줄을 읽어요.","줄기가 단단해요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["들에서 민들레, 강아지풀을 보았다. 줄기가 가늘고 연했다.","산에서 소나무, 단풍나무를 보았다. 줄기가 굵고 단단했다.","산길에서 키가 작은 진달래도 보았다. 줄기가 단단했다.","친구 다 — 「진달래는 키가 작으니까 풀이야.」"],"title":"새싹반 일지 ③ 들과 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#24','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C39',4,'mc','auto','새싹반 일지 ⑦의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X32','SC3-1-u3-X30','SC3-1-u3-X31']::text[],false,'{"seq":24,"concept":"SC3-1-u3-C39","difficulty":4,"kind":"mc","stem":"새싹반 일지 ⑦의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「끈을 안 묶어도 되니 편하겠다. 놀리지 말고 좋은 점을 찾아 주자.」","correct":true},{"t":"「맞아, 이상한 아이디어야.」","mis":"SC3-1-u3-X32"},{"t":"「발명은 관찰 없이 해도 돼.」","mis":"SC3-1-u3-X30"},{"t":"「스펀지 우비가 제일 좋아.」","mis":"SC3-1-u3-X31"}],"explanation":["모둠 2를 봐요.","좋은 점이 있어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["모둠별로 식물을 본뜬 발명 아이디어를 냈다.","모둠 1 — 민들레 솜털을 본떠 천천히 내려오는 인형","모둠 2 — 도꼬마리 갈고리를 본떠 끈 없는 신발","모둠 3 — 물을 빨아들이는 스펀지로 안 젖는 우비","친구 가 — 「모둠 2 아이디어는 이상해. 하하.」"],"title":"새싹반 일지 ⑦ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_c#25','sci',3,1,'u3','','g3_1_sci_u3_review_c','unit_review','SC3-1-u3-C26',4,'essay','teacher','새싹반 일지 ⑤를 보고 선인장의 줄기와 가시가 사막에서 어떻게 알맞은지 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u3-C26","difficulty":4,"kind":"essay","stem":"새싹반 일지 ⑤를 보고 선인장의 줄기와 가시가 사막에서 어떻게 알맞은지 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 선인장은 굵은 줄기에 물을 저장하고, 잎이 가시로 변해 물이 빠져나가는 것을 막는다. 그래서 물이 부족한 사막에서 살 수 있다. 가시는 그냥 장식이 아니라 잎이 변한 것으로 물을 지키는 데 도움이 된다.","scoring_points":["줄기의 물 저장을 썼는가","가시가 물이 빠져나가는 것을 막는다고 썼는가","가시는 장식이 아니라고 친구 나의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","줄기와 가시예요.","고쳐 써요."],"asset":{"type":"passage","lines":["식물원 사막 방에서 선인장, 용설란, 알로에를 보았다.","선인장은 줄기가 굵고 잎이 가시로 되어 있었다.","용설란과 알로에는 잎이 두툼했다.","친구 나 — 「선인장의 가시는 그냥 멋으로 달린 장식이야.」"],"title":"새싹반 일지 ⑤ 사막 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#1','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C3',1,'mc','auto','새싹반 일지 ①에서 잎이 바늘 모양인 식물은 무엇인가요?',ARRAY['SC3-1-u3-X03']::text[],false,'{"seq":1,"concept":"SC3-1-u3-C3","difficulty":1,"kind":"mc","stem":"새싹반 일지 ①에서 잎이 바늘 모양인 식물은 무엇인가요?","options":[{"t":"소나무","correct":true},{"t":"민들레","mis":"SC3-1-u3-X03"},{"t":"튤립","mis":"SC3-1-u3-X03"},{"t":"토끼풀","mis":"SC3-1-u3-X03"}],"explanation":["넷째 줄을 읽어요.","바늘 모양이에요.","소나무예요."],"asset":{"type":"passage","lines":["학교 둘레를 걸으며 식물을 찾았다.","화단에는 튤립이, 길가에는 민들레가 자랐다.","민들레는 노란 꽃이 지고 하얀 솜털 씨앗이 생겼다.","소나무는 잎이 바늘 모양이었다.","친구 가 — 「식물은 다 초록색이니까 생김새가 모두 같아.」"],"title":"새싹반 일지 ① 주변의 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#2','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C9',1,'mc','auto','새싹반 일지 ②에 나온 기준 가운데 알맞은 기준은 무엇인가요?',ARRAY['SC3-1-u3-X09']::text[],false,'{"seq":2,"concept":"SC3-1-u3-C9","difficulty":1,"kind":"mc","stem":"새싹반 일지 ②에 나온 기준 가운데 알맞은 기준은 무엇인가요?","options":[{"t":"가장자리가 톱니 모양인가?","correct":true},{"t":"잎이 예쁜가?","mis":"SC3-1-u3-X09"},{"t":"잎이 마음에 드는가?","mis":"SC3-1-u3-X09"},{"t":"잎이 귀여운가?","mis":"SC3-1-u3-X09"}],"explanation":["누가 해도 같은 기준이에요.","톱니예요.","첫 번째예요."],"asset":{"type":"passage","lines":["단풍나무, 은행나무, 강아지풀, 민들레 잎을 관찰했다.","「가장자리가 톱니 모양인가?」로 나누니 단풍나무, 민들레가 「그렇다」였다.","「잎이 길쭉한가?」로 나누니 강아지풀만 「그렇다」였다.","친구 나 — 「‘잎이 예쁜가?’도 알맞은 기준이야.」"],"title":"새싹반 일지 ② 잎 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#3','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C12',1,'mc','auto','새싹반 일지 ③을 보면 들과 산에는 어떤 식물이 사나요?',ARRAY['SC3-1-u3-X11']::text[],false,'{"seq":3,"concept":"SC3-1-u3-C12","difficulty":1,"kind":"mc","stem":"새싹반 일지 ③을 보면 들과 산에는 어떤 식물이 사나요?","options":[{"t":"풀과 나무가 함께 살아요","correct":true},{"t":"풀만 살아요","mis":"SC3-1-u3-X11"},{"t":"나무만 살아요","mis":"SC3-1-u3-X11"},{"t":"식물이 살지 않아요","mis":"SC3-1-u3-X11"}],"explanation":["세 줄을 모두 읽어요.","풀도 나무도 있어요.","첫 번째예요."],"asset":{"type":"passage","lines":["들에서 민들레, 강아지풀을 보았다. 줄기가 가늘고 연했다.","산에서 소나무, 단풍나무를 보았다. 줄기가 굵고 단단했다.","산길에서 키가 작은 진달래도 보았다. 줄기가 단단했다.","친구 다 — 「진달래는 키가 작으니까 풀이야.」"],"title":"새싹반 일지 ③ 들과 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#4','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C19',1,'mc','auto','새싹반 일지 ④에서 볼록했던 부레옥잠 잎자루 속에 든 것은 무엇인가요?',ARRAY['SC3-1-u3-X17']::text[],false,'{"seq":4,"concept":"SC3-1-u3-C19","difficulty":1,"kind":"mc","stem":"새싹반 일지 ④에서 볼록했던 부레옥잠 잎자루 속에 든 것은 무엇인가요?","options":[{"t":"공기","correct":true},{"t":"모래","mis":"SC3-1-u3-X17"},{"t":"돌","mis":"SC3-1-u3-X17"},{"t":"씨앗","mis":"SC3-1-u3-X17"}],"explanation":["공기주머니예요.","그래서 떠요.","공기예요."],"asset":{"type":"passage","lines":["연못에 부레옥잠이 떠 있었다. 잎자루가 볼록했다.","검정말은 물속에 잠겨 물결에 따라 흔들렸다.","수련 잎은 물 위에 떠 있고 뿌리는 물속 땅에 있었다.","부들은 물가에 곧게 솟아 있었다.","친구 가 — 「물에 사는 식물은 모두 물 위에 떠서 살아.」"],"title":"새싹반 일지 ④ 연못"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#5','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C23',1,'mc','auto','새싹반 일지 ⑤의 식물들이 원래 사는 곳은 어디인가요?',ARRAY['SC3-1-u3-X20']::text[],false,'{"seq":5,"concept":"SC3-1-u3-C23","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑤의 식물들이 원래 사는 곳은 어디인가요?","options":[{"t":"물이 매우 부족한 사막","correct":true},{"t":"물이 가득한 연못","mis":"SC3-1-u3-X20"},{"t":"얼음으로 덮인 곳","mis":"SC3-1-u3-X20"},{"t":"식물이 살 수 없는 곳","mis":"SC3-1-u3-X20"}],"explanation":["첫째 줄을 읽어요.","사막 방이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["식물원 사막 방에서 선인장, 용설란, 알로에를 보았다.","선인장은 줄기가 굵고 잎이 가시로 되어 있었다.","용설란과 알로에는 잎이 두툼했다.","친구 나 — 「선인장의 가시는 그냥 멋으로 달린 장식이야.」"],"title":"새싹반 일지 ⑤ 사막 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#6','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C31',1,'mc','auto','새싹반 일지 ⑥에서 빙글빙글 돌며 내려온 씨앗은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":6,"concept":"SC3-1-u3-C31","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑥에서 빙글빙글 돌며 내려온 씨앗은 무엇인가요?","options":[{"t":"단풍나무 씨앗","correct":true},{"t":"민들레 씨앗","mis":"SC3-1-u3-X26"},{"t":"도꼬마리 열매","mis":"SC3-1-u3-X26"},{"t":"연잎","mis":"SC3-1-u3-X26"}],"explanation":["셋째 줄을 읽어요.","날개가 있어요.","단풍나무 씨앗이에요."],"asset":{"type":"passage","lines":["옷에 붙은 도꼬마리 열매를 보았다. 갈고리 모양 가시가 있었다.","연잎에 물을 떨어뜨리니 물방울이 또르르 굴러떨어졌다.","단풍나무 씨앗을 떨어뜨리니 빙글빙글 돌며 내려왔다.","친구 다 — 「식물은 우리 생활에 아무 도움이 안 돼.」"],"title":"새싹반 일지 ⑥ 식물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#7','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C36',1,'mc','auto','새싹반 일지 ⑦에서 끈 없는 신발은 무엇을 본떴나요?',ARRAY['SC3-1-u3-X29']::text[],false,'{"seq":7,"concept":"SC3-1-u3-C36","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑦에서 끈 없는 신발은 무엇을 본떴나요?","options":[{"t":"도꼬마리 갈고리","correct":true},{"t":"민들레 솜털","mis":"SC3-1-u3-X29"},{"t":"연잎 표면","mis":"SC3-1-u3-X29"},{"t":"단풍나무 씨앗 날개","mis":"SC3-1-u3-X29"}],"explanation":["모둠 2를 읽어요.","갈고리예요.","도꼬마리 갈고리예요."],"asset":{"type":"passage","lines":["모둠별로 식물을 본뜬 발명 아이디어를 냈다.","모둠 1 — 민들레 솜털을 본떠 천천히 내려오는 인형","모둠 2 — 도꼬마리 갈고리를 본떠 끈 없는 신발","모둠 3 — 물을 빨아들이는 스펀지로 안 젖는 우비","친구 가 — 「모둠 2 아이디어는 이상해. 하하.」"],"title":"새싹반 일지 ⑦ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#8','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C43',1,'mc','auto','새싹반 일지 ⑧의 식물들이 벌레를 잡는 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X35']::text[],false,'{"seq":8,"concept":"SC3-1-u3-C43","difficulty":1,"kind":"mc","stem":"새싹반 일지 ⑧의 식물들이 벌레를 잡는 까닭은 무엇인가요?","options":[{"t":"양분이 적은 땅에 살아 부족한 양분을 얻으려고","correct":true},{"t":"햇빛이 싫어서","mis":"SC3-1-u3-X35"},{"t":"다른 식물과 싸우려고","mis":"SC3-1-u3-X35"},{"t":"물을 마시지 못해서","mis":"SC3-1-u3-X35"}],"explanation":["넷째 줄을 읽어요.","양분이 적어요.","첫 번째예요."],"asset":{"type":"passage","lines":["식물원에서 파리지옥, 끈끈이주걱, 벌레잡이통풀을 보았다.","파리지옥은 잎을 닫아, 끈끈이주걱은 끈끈한 액으로 벌레를 잡았다.","벌레잡이통풀은 미끄러운 통 속에 벌레를 빠뜨렸다.","이 식물들은 양분이 적은 땅에서 자란다고 한다.","친구 나 — 「벌레잡이 식물은 벌레만 먹고 사니 햇빛은 필요 없어.」"],"title":"새싹반 일지 ⑧ 신기한 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#9','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C1',2,'mc','auto','새싹반 일지 ①에서 식물을 찾은 곳끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X01']::text[],false,'{"seq":9,"concept":"SC3-1-u3-C1","difficulty":2,"kind":"mc","stem":"새싹반 일지 ①에서 식물을 찾은 곳끼리 모은 것은 무엇인가요?","options":[{"t":"화단, 길가","correct":true},{"t":"산속, 바닷속","mis":"SC3-1-u3-X01"},{"t":"식물원 안","mis":"SC3-1-u3-X01"},{"t":"교실 안","mis":"SC3-1-u3-X01"}],"explanation":["둘째 줄을 읽어요.","학교 둘레예요.","첫 번째예요."],"asset":{"type":"passage","lines":["학교 둘레를 걸으며 식물을 찾았다.","화단에는 튤립이, 길가에는 민들레가 자랐다.","민들레는 노란 꽃이 지고 하얀 솜털 씨앗이 생겼다.","소나무는 잎이 바늘 모양이었다.","친구 가 — 「식물은 다 초록색이니까 생김새가 모두 같아.」"],"title":"새싹반 일지 ① 주변의 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#10','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C11',2,'mc','auto','새싹반 일지 ②에서 「가장자리가 톱니 모양인가?」의 「그렇지 않다」 무리는 무엇인가요?',ARRAY['SC3-1-u3-X10','SC3-1-u3-X07']::text[],false,'{"seq":10,"concept":"SC3-1-u3-C11","difficulty":2,"kind":"mc","stem":"새싹반 일지 ②에서 「가장자리가 톱니 모양인가?」의 「그렇지 않다」 무리는 무엇인가요?","options":[{"t":"은행나무, 강아지풀","correct":true},{"t":"단풍나무, 민들레","mis":"SC3-1-u3-X10"},{"t":"은행나무, 민들레","mis":"SC3-1-u3-X07"},{"t":"단풍나무, 강아지풀","mis":"SC3-1-u3-X07"}],"explanation":["둘째 줄의 나머지예요.","두 잎이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["단풍나무, 은행나무, 강아지풀, 민들레 잎을 관찰했다.","「가장자리가 톱니 모양인가?」로 나누니 단풍나무, 민들레가 「그렇다」였다.","「잎이 길쭉한가?」로 나누니 강아지풀만 「그렇다」였다.","친구 나 — 「‘잎이 예쁜가?’도 알맞은 기준이야.」"],"title":"새싹반 일지 ② 잎 분류"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#11','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C14',2,'mc','auto','새싹반 일지 ③에서 산에서 본 줄기가 굵은 나무끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X12','SC3-1-u3-X13']::text[],false,'{"seq":11,"concept":"SC3-1-u3-C14","difficulty":2,"kind":"mc","stem":"새싹반 일지 ③에서 산에서 본 줄기가 굵은 나무끼리 모은 것은 무엇인가요?","options":[{"t":"소나무, 단풍나무","correct":true},{"t":"민들레, 강아지풀","mis":"SC3-1-u3-X12"},{"t":"진달래, 강아지풀","mis":"SC3-1-u3-X13"},{"t":"민들레, 진달래","mis":"SC3-1-u3-X13"}],"explanation":["둘째 줄을 읽어요.","산에서 보았어요.","첫 번째예요."],"asset":{"type":"passage","lines":["들에서 민들레, 강아지풀을 보았다. 줄기가 가늘고 연했다.","산에서 소나무, 단풍나무를 보았다. 줄기가 굵고 단단했다.","산길에서 키가 작은 진달래도 보았다. 줄기가 단단했다.","친구 다 — 「진달래는 키가 작으니까 풀이야.」"],"title":"새싹반 일지 ③ 들과 산"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#12','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C20',2,'mc','auto','새싹반 일지 ④에서 검정말이 물결에 따라 흔들린 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X17','SC3-1-u3-X18','SC3-1-u3-X19']::text[],false,'{"seq":12,"concept":"SC3-1-u3-C20","difficulty":2,"kind":"mc","stem":"새싹반 일지 ④에서 검정말이 물결에 따라 흔들린 까닭은 무엇인가요?","options":[{"t":"줄기와 잎이 가늘고 부드러워서","correct":true},{"t":"잎자루에 공기주머니가 있어서","mis":"SC3-1-u3-X17"},{"t":"줄기가 굵고 단단해서","mis":"SC3-1-u3-X18"},{"t":"뿌리가 없어서","mis":"SC3-1-u3-X19"}],"explanation":["검정말의 생김새예요.","가늘고 부드러워요.","첫 번째예요."],"asset":{"type":"passage","lines":["연못에 부레옥잠이 떠 있었다. 잎자루가 볼록했다.","검정말은 물속에 잠겨 물결에 따라 흔들렸다.","수련 잎은 물 위에 떠 있고 뿌리는 물속 땅에 있었다.","부들은 물가에 곧게 솟아 있었다.","친구 가 — 「물에 사는 식물은 모두 물 위에 떠서 살아.」"],"title":"새싹반 일지 ④ 연못"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#13','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C25',2,'mc','auto','새싹반 일지 ⑤의 알로에 잎이 두툼한 까닭은 무엇인가요?',ARRAY['SC3-1-u3-X21','SC3-1-u3-X24']::text[],false,'{"seq":13,"concept":"SC3-1-u3-C25","difficulty":2,"kind":"mc","stem":"새싹반 일지 ⑤의 알로에 잎이 두툼한 까닭은 무엇인가요?","options":[{"t":"잎 속에 물을 저장하기 때문에","correct":true},{"t":"잎이 가시로 변했기 때문에","mis":"SC3-1-u3-X21"},{"t":"잎자루에 공기가 있기 때문에","mis":"SC3-1-u3-X24"},{"t":"잎이 넓고 얇기 때문에","mis":"SC3-1-u3-X24"}],"explanation":["알로에 잎 속을 떠올려요.","물기가 많아요.","첫 번째예요."],"asset":{"type":"passage","lines":["식물원 사막 방에서 선인장, 용설란, 알로에를 보았다.","선인장은 줄기가 굵고 잎이 가시로 되어 있었다.","용설란과 알로에는 잎이 두툼했다.","친구 나 — 「선인장의 가시는 그냥 멋으로 달린 장식이야.」"],"title":"새싹반 일지 ⑤ 사막 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#14','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C32',2,'mc','auto','새싹반 일지 ⑥에서 연잎에 물을 떨어뜨렸을 때 본 모습은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":14,"concept":"SC3-1-u3-C32","difficulty":2,"kind":"mc","stem":"새싹반 일지 ⑥에서 연잎에 물을 떨어뜨렸을 때 본 모습은 무엇인가요?","options":[{"t":"물방울이 또르르 굴러떨어졌어요","correct":true},{"t":"물이 잎 속으로 쏙 스며들었어요","mis":"SC3-1-u3-X26"},{"t":"잎이 빙글빙글 돌았어요","mis":"SC3-1-u3-X26"},{"t":"잎이 옷에 착 붙었어요","mis":"SC3-1-u3-X26"}],"explanation":["둘째 줄을 읽어요.","또르르예요.","첫 번째예요."],"asset":{"type":"passage","lines":["옷에 붙은 도꼬마리 열매를 보았다. 갈고리 모양 가시가 있었다.","연잎에 물을 떨어뜨리니 물방울이 또르르 굴러떨어졌다.","단풍나무 씨앗을 떨어뜨리니 빙글빙글 돌며 내려왔다.","친구 다 — 「식물은 우리 생활에 아무 도움이 안 돼.」"],"title":"새싹반 일지 ⑥ 식물을 본뜬 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#15','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C38',2,'mc','auto','새싹반 일지 ⑦의 모둠 3 우비는 어떻게 될까요?',ARRAY['SC3-1-u3-X29']::text[],false,'{"seq":15,"concept":"SC3-1-u3-C38","difficulty":2,"kind":"mc","stem":"새싹반 일지 ⑦의 모둠 3 우비는 어떻게 될까요?","options":[{"t":"스펀지가 물을 빨아들여 오히려 흠뻑 젖어요","correct":true},{"t":"비를 하나도 맞지 않아요","mis":"SC3-1-u3-X29"},{"t":"하늘을 날 수 있어요","mis":"SC3-1-u3-X29"},{"t":"옷에 잘 붙어요","mis":"SC3-1-u3-X29"}],"explanation":["스펀지에 물을 부어 봐요.","젖어요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠별로 식물을 본뜬 발명 아이디어를 냈다.","모둠 1 — 민들레 솜털을 본떠 천천히 내려오는 인형","모둠 2 — 도꼬마리 갈고리를 본떠 끈 없는 신발","모둠 3 — 물을 빨아들이는 스펀지로 안 젖는 우비","친구 가 — 「모둠 2 아이디어는 이상해. 하하.」"],"title":"새싹반 일지 ⑦ 발명 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#16','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C45',2,'mc','auto','새싹반 일지 ⑧의 식물을 관찰할 때 알맞은 행동은 무엇인가요?',ARRAY['SC3-1-u3-X37']::text[],false,'{"seq":16,"concept":"SC3-1-u3-C45","difficulty":2,"kind":"mc","stem":"새싹반 일지 ⑧의 식물을 관찰할 때 알맞은 행동은 무엇인가요?","options":[{"t":"손대지 않고 가만히 살펴봐요","correct":true},{"t":"파리지옥 잎을 자꾸 건드려 닫히게 해요","mis":"SC3-1-u3-X37"},{"t":"끈끈이주걱 잎을 떼어 가져가요","mis":"SC3-1-u3-X37"},{"t":"벌레잡이통풀 통에 물건을 넣어 봐요","mis":"SC3-1-u3-X37"}],"explanation":["소중히 대해요.","눈으로 봐요.","첫 번째예요."],"asset":{"type":"passage","lines":["식물원에서 파리지옥, 끈끈이주걱, 벌레잡이통풀을 보았다.","파리지옥은 잎을 닫아, 끈끈이주걱은 끈끈한 액으로 벌레를 잡았다.","벌레잡이통풀은 미끄러운 통 속에 벌레를 빠뜨렸다.","이 식물들은 양분이 적은 땅에서 자란다고 한다.","친구 나 — 「벌레잡이 식물은 벌레만 먹고 사니 햇빛은 필요 없어.」"],"title":"새싹반 일지 ⑧ 신기한 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#17','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C8',3,'mc','auto','단풍나무 잎과 민들레 잎의 공통점은 무엇인가요?',ARRAY['SC3-1-u3-X07','SC3-1-u3-X08']::text[],false,'{"seq":17,"concept":"SC3-1-u3-C8","difficulty":3,"kind":"mc","stem":"단풍나무 잎과 민들레 잎의 공통점은 무엇인가요?","options":[{"t":"둘 다 가장자리가 톱니 모양이고 잎몸이 갈라져 있어요","correct":true},{"t":"둘 다 잎이 길쭉해요","mis":"SC3-1-u3-X07"},{"t":"둘 다 가장자리가 매끈해요","mis":"SC3-1-u3-X07"},{"t":"공통점은 찾을 수 없어요","mis":"SC3-1-u3-X08"}],"explanation":["두 잎을 견줘요.","톱니와 갈라짐이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#18','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C22',3,'mc','auto','땅에 사는 식물과 물에 사는 식물의 공통점은 무엇인가요?',ARRAY['SC3-1-u3-X15','SC3-1-u3-X19','SC3-1-u3-X17']::text[],false,'{"seq":18,"concept":"SC3-1-u3-C22","difficulty":3,"kind":"mc","stem":"땅에 사는 식물과 물에 사는 식물의 공통점은 무엇인가요?","options":[{"t":"둘 다 뿌리, 줄기, 잎이 있어요","correct":true},{"t":"둘 다 물 위에 떠서 살아요","mis":"SC3-1-u3-X15"},{"t":"물에 사는 식물만 뿌리가 없어요","mis":"SC3-1-u3-X19"},{"t":"둘 다 잎자루에 공기주머니가 있어요","mis":"SC3-1-u3-X17"}],"explanation":["식물의 기본 부분이에요.","세 가지예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#19','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C27',3,'mc','auto','사막에서 선인장이 물을 얻고 지키는 방법을 바르게 모은 것은 무엇인가요?',ARRAY['SC3-1-u3-X24','SC3-1-u3-X23']::text[],false,'{"seq":19,"concept":"SC3-1-u3-C27","difficulty":3,"kind":"mc","stem":"사막에서 선인장이 물을 얻고 지키는 방법을 바르게 모은 것은 무엇인가요?","options":[{"t":"넓게 뻗은 뿌리로 물을 빨아들이고, 굵은 줄기에 저장하며, 가시로 물이 빠져나가는 것을 막아요","correct":true},{"t":"잎자루의 공기주머니로 물에 떠요","mis":"SC3-1-u3-X24"},{"t":"넓고 얇은 잎으로 물을 많이 내보내요","mis":"SC3-1-u3-X24"},{"t":"뿌리 없이 잎으로만 물을 모아요","mis":"SC3-1-u3-X23"}],"explanation":["뿌리·줄기·잎을 차례로요.","모으고 저장하고 지켜요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#20','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C32',3,'mc','auto','연잎의 특징을 본떠 만들 물건으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X26']::text[],false,'{"seq":20,"concept":"SC3-1-u3-C32","difficulty":3,"kind":"mc","stem":"연잎의 특징을 본떠 만들 물건으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"물이 묻어도 젖지 않는 가방","correct":true},{"t":"잘 붙는 신발 여밈","mis":"SC3-1-u3-X26"},{"t":"빙글빙글 도는 장난감","mis":"SC3-1-u3-X26"},{"t":"천천히 떨어지는 인형","mis":"SC3-1-u3-X26"}],"explanation":["연잎은 물을 막아요.","안 젖어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#21','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C40',3,'mc','auto','단풍나무 씨앗의 특징을 본뜬 새 발명품으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X29']::text[],false,'{"seq":21,"concept":"SC3-1-u3-C40","difficulty":3,"kind":"mc","stem":"단풍나무 씨앗의 특징을 본뜬 새 발명품으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"빙글빙글 돌며 천천히 떨어지는 종이 장난감","correct":true},{"t":"끈 없이 붙는 신발","mis":"SC3-1-u3-X29"},{"t":"물 안 젖는 우산","mis":"SC3-1-u3-X29"},{"t":"미끄러운 통 모양 컵","mis":"SC3-1-u3-X29"}],"explanation":["날개 달린 씨앗이에요.","빙글빙글이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#22','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C45',3,'mc','auto','벌레잡이 식물을 기르는 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u3-X37','SC3-1-u3-X36']::text[],false,'{"seq":22,"concept":"SC3-1-u3-C45","difficulty":3,"kind":"mc","stem":"벌레잡이 식물을 기르는 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「햇빛과 물을 알맞게 주고, 잎은 자꾸 건드리지 마.」","correct":true},{"t":"「잎을 자꾸 건드려 닫히는 걸 구경해.」","mis":"SC3-1-u3-X37"},{"t":"「벌레만 주면 햇빛은 필요 없어.」","mis":"SC3-1-u3-X36"},{"t":"「잎을 떼어 친구들에게 나눠 줘.」","mis":"SC3-1-u3-X37"}],"explanation":["소중히 길러요.","햇빛과 물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#23','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C17',4,'mc','auto','새싹반 일지 ④의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X15','SC3-1-u3-X19','SC3-1-u3-X16']::text[],false,'{"seq":23,"concept":"SC3-1-u3-C17","difficulty":4,"kind":"mc","stem":"새싹반 일지 ④의 친구 가의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「부레옥잠은 떠서 살지만, 검정말은 물속에 잠겨 살고 부들은 물가에 솟아 살아.」","correct":true},{"t":"「맞아, 모두 물 위에 떠서 살아.」","mis":"SC3-1-u3-X15"},{"t":"「물에 사는 식물은 뿌리가 없어.」","mis":"SC3-1-u3-X19"},{"t":"「검정말도 공기주머니로 떠.」","mis":"SC3-1-u3-X16"}],"explanation":["검정말과 부들을 봐요.","사는 모습이 달라요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["연못에 부레옥잠이 떠 있었다. 잎자루가 볼록했다.","검정말은 물속에 잠겨 물결에 따라 흔들렸다.","수련 잎은 물 위에 떠 있고 뿌리는 물속 땅에 있었다.","부들은 물가에 곧게 솟아 있었다.","친구 가 — 「물에 사는 식물은 모두 물 위에 떠서 살아.」"],"title":"새싹반 일지 ④ 연못"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#24','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C44',4,'mc','auto','새싹반 일지 ⑧의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u3-X36','SC3-1-u3-X33','SC3-1-u3-X34']::text[],false,'{"seq":24,"concept":"SC3-1-u3-C44","difficulty":4,"kind":"mc","stem":"새싹반 일지 ⑧의 친구 나의 말에 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「벌레는 부족한 양분을 보태 줄 뿐이야. 벌레잡이 식물도 햇빛을 받아야 살아.」","correct":true},{"t":"「맞아, 햇빛은 필요 없어.」","mis":"SC3-1-u3-X36"},{"t":"「벌레잡이 식물은 동물이야.」","mis":"SC3-1-u3-X33"},{"t":"「모두 잎을 닫아 벌레를 잡아.」","mis":"SC3-1-u3-X34"}],"explanation":["식물은 햇빛이 필요해요.","벌레는 보탤 뿐이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["식물원에서 파리지옥, 끈끈이주걱, 벌레잡이통풀을 보았다.","파리지옥은 잎을 닫아, 끈끈이주걱은 끈끈한 액으로 벌레를 잡았다.","벌레잡이통풀은 미끄러운 통 속에 벌레를 빠뜨렸다.","이 식물들은 양분이 적은 땅에서 자란다고 한다.","친구 나 — 「벌레잡이 식물은 벌레만 먹고 사니 햇빛은 필요 없어.」"],"title":"새싹반 일지 ⑧ 신기한 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u3_review_d#25','sci',3,1,'u3','','g3_1_sci_u3_review_d','unit_review','SC3-1-u3-C44',4,'essay','teacher','새싹반 일지 ⑧을 보고 두 식물이 벌레를 잡는 방법을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u3-C44","difficulty":4,"kind":"essay","stem":"새싹반 일지 ⑧을 보고 두 식물이 벌레를 잡는 방법을 쓰고, 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 파리지옥은 잎을 닫아 벌레를 가두고, 끈끈이주걱은 끈끈한 액으로 벌레를 붙잡는다. 벌레잡이 식물은 양분이 적은 땅에 살아 부족한 양분을 벌레로 보탤 뿐이고, 다른 식물처럼 햇빛을 받아야 살 수 있다.","scoring_points":["두 식물의 잡는 방법을 바르게 썼는가","부족한 양분을 보태려고 잡는다고 썼는가","햇빛이 필요하다고 친구 나의 말을 고쳤는가"]},"explanation":["일지를 읽어요.","방법과 까닭이에요.","고쳐 써요."],"asset":{"type":"passage","lines":["식물원에서 파리지옥, 끈끈이주걱, 벌레잡이통풀을 보았다.","파리지옥은 잎을 닫아, 끈끈이주걱은 끈끈한 액으로 벌레를 잡았다.","벌레잡이통풀은 미끄러운 통 속에 벌레를 빠뜨렸다.","이 식물들은 양분이 적은 땅에서 자란다고 한다.","친구 나 — 「벌레잡이 식물은 벌레만 먹고 사니 햇빛은 필요 없어.」"],"title":"새싹반 일지 ⑧ 신기한 식물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
